def _parse_iso_datetime(value: str) -> Optional[datetime.datetime]:
    raw = (value or "").strip()
    if not raw:
        return None
    normalized = raw.replace("Z", "+00:00")
    try:
        return datetime.datetime.fromisoformat(normalized)
    except Exception:
        return None


