def _admin_notification_schedule_key(meta: Optional[Dict[str, Any]]) -> str:
    payload = meta or {}
    kind = str(payload.get("kind") or "").strip()
    scheduled_at = str(payload.get("scheduled_at") or "").strip()
    if not kind or not scheduled_at:
        return ""
    return f"{kind}|{scheduled_at}"


def _inject_vtc_exam_results_notifications(data: Dict[str, Any]) -> bool:
    paris_tz = ZoneInfo("Europe/Paris")
    now_paris = datetime.datetime.now(paris_tz)
    notifications = data.setdefault("notifications_admin", [])
    dismissed_keys = set(data.setdefault("notifications_admin_dismissed_schedule_keys", []))
    existing_keys = {
        _admin_notification_schedule_key(item.get("meta"))
        for item in notifications
        if _admin_notification_schedule_key(item.get("meta"))
    }
    existing_keys |= dismissed_keys

    changed = False
    for label, schedule_at in VTC_EXAM_RESULTS_NOTIFICATION_SCHEDULE:
        schedule_paris = datetime.datetime.fromisoformat(schedule_at).replace(tzinfo=paris_tz)
        key = _admin_notification_schedule_key({"kind": "vtc_exam_results_download", "scheduled_at": schedule_at})
        if now_paris < schedule_paris or key in existing_keys:
            continue
        add_admin_notification(
            data,
            label,
            {
                "kind": "vtc_exam_results_download",
                "scheduled_at": schedule_at,
                "timezone": "Europe/Paris",
            },
        )
        existing_keys.add(key)
        changed = True

    return changed

def _mark_public_login(data: Dict[str, Any], session_data: Dict[str, Any], trainee: Dict[str, Any]) -> None:
    if not trainee.get("public_has_logged_in"):
        trainee["public_has_logged_in"] = True
    trainee["public_last_login_at"] = _now_iso()
    session_data["trainees"] = _session_trainees_list(session_data)
    session_data.pop("stagiaires", None)
    save_data(data)


def _normalize_cnaps_status(value: Optional[str]) -> str:
    return (value or "").strip().upper()

def _cnaps_is_accepted(value: Optional[str]) -> bool:
    normalized = _normalize_cnaps_status(value)
    if not normalized:
        return False
    if normalized in {"ACCEPTE", "ACCEPTÉ"}:
        return True
    return normalized.startswith("CARTE PROFESSIONNELLE OK")


def _cnaps_status_is_unknown(value: Optional[str]) -> bool:
    normalized = _normalize_cnaps_status(value)
    return normalized in {"", "INCONNU", "UNKNOWN"}


def _cnaps_unknown_training_type_is_allowed(training_type: Optional[str]) -> bool:
    normalized = (training_type or "").strip().upper()
    return normalized.startswith("APS") or normalized.startswith("A3P")


def _cnaps_pre_training_type_is_allowed(training_type: Optional[str]) -> bool:
    """PRE/CAR imports only apply to APS and A3P training sessions."""
    return _cnaps_unknown_training_type_is_allowed(training_type)


def _collect_cnaps_unknown_trainees(data: Dict[str, Any]) -> List[Dict[str, Any]]:
    rows = []
    for session_data in data.get("sessions", []):
        if bool(session_data.get("archived")):
            continue

        session_id = session_data.get("id")
        session_name = _session_get(session_data, "name", "")
        training_type = _session_get(session_data, "training_type", "")
        if not _cnaps_unknown_training_type_is_allowed(training_type):
            continue

        date_start = _session_get(session_data, "date_start", "")
        date_end = _session_get(session_data, "date_end", "")

        for trainee in _session_trainees_list(session_data):
            if not _cnaps_status_is_unknown(trainee.get("cnaps")):
                continue

            trainee_id = trainee.get("id")
            rows.append({
                "session_id": session_id,
                "session_name": session_name,
                "training_type": training_type,
                "date_start": date_start,
                "date_end": date_end,
                "trainee_id": trainee_id,
                "first_name": normalize_first_name(trainee.get("first_name") or ""),
                "last_name": normalize_last_name(trainee.get("last_name") or ""),
                "birth_date": trainee.get("birth_date") or "",
                "email": (trainee.get("email") or "").strip(),
                "phone": format_phone_fr_for_display((trainee.get("phone") or "").strip()),
                "cnaps": "INCONNU",
                "admin_url": url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id),
                "session_url": url_for("admin_trainees", session_id=session_id),
            })

    rows.sort(key=lambda row: (
        _normalized_token(row.get("last_name") or ""),
        _normalized_token(row.get("first_name") or ""),
        _normalized_token(row.get("session_name") or ""),
    ))
    return rows


def record_cnaps_status_change(t: Dict[str, Any], new_status: Optional[str]) -> None:
    normalized = (new_status or "").strip()
    if not normalized:
        return
    history = t.get("cnaps_history")
    if not isinstance(history, list):
        history = []
    last_status = history[-1].get("status") if history else ""
    if _normalize_cnaps_status(last_status) != _normalize_cnaps_status(normalized):
        history.append({"status": normalized, "date": _now_iso()})
    t["cnaps_history"] = history


def record_cnaps_pre_request(t: Dict[str, Any]) -> None:
    history = t.get("cnaps_history")
    if not isinstance(history, list):
        history = []
    history.append({
        "status": "Demande de numéro PRE faite au CNAPS",
        "date": _now_iso(),
        "kind": "pre_request",
    })
    t["cnaps_history"] = history


def ensure_cnaps_history(t: Dict[str, Any]) -> None:
    history = t.get("cnaps_history")
    if not isinstance(history, list):
        history = []
    t["cnaps_history"] = history
    current_status = (t.get("cnaps") or "INCONNU").strip()
    if current_status:
        record_cnaps_status_change(t, current_status)


