def run_deferred_background_tasks(data: Dict[str, Any], force: bool = False) -> bool:
    global _BACKGROUND_TASKS_LAST_RUN_AT
    if has_request_context() and request.path == "/healthz":
        return False
    now = time.monotonic()
    if not force and now - _BACKGROUND_TASKS_LAST_RUN_AT < _BACKGROUND_TASKS_MIN_INTERVAL_SECONDS:
        return False
    if not _BACKGROUND_TASKS_LOCK.acquire(blocking=False):
        return False
    started_at = time.monotonic()
    _log_memory_stage("BACKGROUND_TASKS_BEGIN", route=_current_route_for_log())
    changed = False
    try:
        if _send_vtc_credentials_missing_reminders(data):
            changed = True
        if _send_vae_relance_reminders(data):
            changed = True
        if _send_docs_relance_reminders(data):
            changed = True
        if _send_a3p_hosting_reminders(data):
            changed = True
        if _inject_vtc_exam_results_notifications(data):
            changed = True
        _BACKGROUND_TASKS_LAST_RUN_AT = time.monotonic()
        return changed
    finally:
        _log_memory_stage("BACKGROUND_TASKS_END", started_at, _current_route_for_log())
        _BACKGROUND_TASKS_LOCK.release()


def load_data(run_background_tasks: bool = False) -> Dict[str, Any]:
    load_started_at = time.monotonic()
    if has_request_context():
        g.load_data_call_count = getattr(g, "load_data_call_count", 0) + 1
    baseline_mb = _log_memory_stage("LOAD_DATA_BEGIN", load_started_at, _current_route_for_log())
    if not os.path.exists(DATA_FILE):
        recovered_from = _recover_data_file(DATA_FILE)
        if recovered_from:
            loaded = _load_valid_json_payload(DATA_FILE)
            if loaded is not None:
                if not isinstance(loaded.get("wedof_links"), list):
                    loaded["wedof_links"] = []
                if not isinstance(loaded.get("wedof_automation_exceptions"), list):
                    loaded["wedof_automation_exceptions"] = []
                if not isinstance(loaded.get("wedof_automation_status"), list):
                    loaded["wedof_automation_status"] = []
                if not isinstance(loaded.get("wedof_automation_actions"), list): loaded["wedof_automation_actions"] = []
                if not isinstance(loaded.get("wedof_automation_blocks"), list): loaded["wedof_automation_blocks"] = []
                if not isinstance(loaded.get("wedof_automation_runs"), list): loaded["wedof_automation_runs"] = []
                if not isinstance(loaded.get("wedof_automation_sync"), dict): loaded["wedof_automation_sync"] = {"states": {}}
                _ensure_multi_partner_payload(loaded)
                _log_refused_user_password_hashes(loaded)
                _log_storage_state(loaded)
                _log_memory_stage("AFTER_LOAD_DATA", load_started_at, _current_route_for_log())
                return _filter_data_for_partner(loaded, _current_partner_id()) if _is_partner_scoped_session() else loaded
        base = _empty_data_payload()
        _ensure_multi_partner_payload(base)
        _log_storage_state(base)
        _log_memory_stage("AFTER_LOAD_DATA", load_started_at, _current_route_for_log())
        return _filter_data_for_partner(base, _current_partner_id()) if _is_partner_scoped_session() else base

    _log_memory_stage("BEFORE_JSON_LOAD", load_started_at, _current_route_for_log(), baseline_mb)
    data = _load_valid_json_payload(DATA_FILE)
    baseline_mb = _log_memory_stage("AFTER_JSON_LOAD", load_started_at, _current_route_for_log(), baseline_mb)
    if data is None:
        recovered_from = _recover_data_file(DATA_FILE)
        if recovered_from:
            data = _load_valid_json_payload(DATA_FILE)
        if data is None:
            app.logger.error("Unable to read %s and no valid recovery source found", DATA_FILE)
            base = _empty_data_payload()
            _log_storage_state(base)
            _log_memory_stage("AFTER_LOAD_DATA", load_started_at, _current_route_for_log())
            return base

    # Compatibilité ascendante : exposer une collection vide sans provoquer à
    # elle seule une réécriture du fichier lors d'une simple lecture.
    if not isinstance(data.get("wedof_links"), list):
        data["wedof_links"] = []
    if not isinstance(data.get("wedof_automation_exceptions"), list):
        data["wedof_automation_exceptions"] = []
    if not isinstance(data.get("wedof_automation_status"), list):
        data["wedof_automation_status"] = []
    if not isinstance(data.get("wedof_automation_actions"), list): data["wedof_automation_actions"] = []
    if not isinstance(data.get("wedof_automation_blocks"), list): data["wedof_automation_blocks"] = []
    if not isinstance(data.get("wedof_automation_runs"), list): data["wedof_automation_runs"] = []
    if not isinstance(data.get("wedof_automation_sync"), dict): data["wedof_automation_sync"] = {"states": {}}

    # Les post-traitements ne doivent jamais vider la base en cas d'erreur.
    changed = False
    try:
        # ✅ Assure que tous les stagiaires ont un public_token
        if ensure_public_tokens(data):
            changed = True
        baseline_mb = _log_memory_stage("NORMALIZATION ensure_public_tokens", load_started_at, _current_route_for_log(), baseline_mb)

        # ✅ IMPORTANT : normalise en "trainees" partout (sinon admin/public désynchronisés)
        if normalize_sessions_schema(data):
            changed = True
        baseline_mb = _log_memory_stage("NORMALIZATION normalize_sessions_schema", load_started_at, _current_route_for_log(), baseline_mb)

        if "positioning_tests" not in data:
            data["positioning_tests"] = []
            changed = True
        if not isinstance(data.get("afc"), dict):
            data["afc"] = {}
            changed = True
        if "notifications_edof" not in data:
            data["notifications_edof"] = []
            changed = True
        if "notifications_prelevements" not in data:
            data["notifications_prelevements"] = []
            changed = True
        if "notifications_prelevement_non_valides" not in data:
            data["notifications_prelevement_non_valides"] = []
            changed = True
        if "notifications_financement_refuse" not in data:
            data["notifications_financement_refuse"] = []
            changed = True
        if "notifications_phone_relances" not in data:
            data["notifications_phone_relances"] = []
            changed = True
        if "notifications_vae_relances" not in data:
            data["notifications_vae_relances"] = []
            changed = True
        if "notifications_cnaps_pre_relances" not in data:
            data["notifications_cnaps_pre_relances"] = []
            changed = True
        if "notifications_test_fr" not in data:
            data["notifications_test_fr"] = []
            changed = True
        if "notifications_convention_unsigned" not in data:
            data["notifications_convention_unsigned"] = []
            changed = True
        if "notifications_vtc_books" not in data:
            data["notifications_vtc_books"] = []
            changed = True
        if "notifications_admin" not in data:
            data["notifications_admin"] = []
            changed = True
        if "admin_push_subscriptions" not in data:
            data["admin_push_subscriptions"] = []
            changed = True
        if not isinstance(data.get("cnaps_tracking_deleted_keys"), list):
            data["cnaps_tracking_deleted_keys"] = []
            changed = True

        if not isinstance(data.get("notifications_admin_dismissed_schedule_keys"), list):
            data["notifications_admin_dismissed_schedule_keys"] = []
            changed = True

        if _ensure_multi_partner_payload(data):
            changed = True
        baseline_mb = _log_memory_stage("NORMALIZATION _ensure_multi_partner_payload", load_started_at, _current_route_for_log(), baseline_mb)
        if normalize_all_partner_subscriptions(data):
            changed = True
        baseline_mb = _log_memory_stage("NORMALIZATION normalize_all_partner_subscriptions", load_started_at, _current_route_for_log(), baseline_mb)

        if run_background_tasks and run_deferred_background_tasks(data):
            changed = True
        baseline_mb = _log_memory_stage("NORMALIZATION run_deferred_background_tasks", load_started_at, _current_route_for_log(), baseline_mb)

        for session_obj in (data.get("sessions") or []):
            for trainee in _session_trainees_list(session_obj):
                if not isinstance(trainee.get("vae_action_dates"), dict):
                    trainee["vae_action_dates"] = {}
                    changed = True
                action_dates = trainee["vae_action_dates"]
                for action_key in ("livret_1_transmitted_scotia", "livret_2_transmitted_scotia"):
                    if action_dates.get(action_key):
                        continue
                    legacy_value = trainee.get(action_key) or trainee.get(f"{action_key}_at") or ""
                    legacy_date = str(legacy_value).strip()
                    if legacy_date:
                        action_dates[action_key] = legacy_date
                        changed = True

            if "VTC" not in ((_session_get(session_obj, "training_type", "") or "").upper()):
                continue
            for trainee in _session_trainees_list(session_obj):
                if _sync_vtc_book_notification(data, session_obj, trainee):
                    changed = True

        baseline_mb = _log_memory_stage("NORMALIZATION vae_action_dates_and_vtc_book_notifications", load_started_at, _current_route_for_log(), baseline_mb)

        if changed:
            save_data(data)

    except Exception:
        app.logger.exception("Post-processing failed for %s; returning current in-memory data without reset", DATA_FILE)

    _log_refused_user_password_hashes(data)
    baseline_mb = _log_memory_stage("AFTER_PASSWORD_HASH_INSPECTION", load_started_at, _current_route_for_log(), baseline_mb)
    _log_storage_state(data)
    _log_memory_stage("BEFORE_PARTNER_FILTER", load_started_at, _current_route_for_log(), baseline_mb)
    result = _filter_data_for_partner(data, _current_partner_id()) if _is_partner_scoped_session() else data
    _log_memory_stage("AFTER_PARTNER_FILTER", load_started_at, _current_route_for_log(), baseline_mb)
    _log_memory_stage("LOAD_DATA_END", load_started_at, _current_route_for_log())
    return result


def save_data(data: Dict[str, Any], *, preserve_qonto_oauth: bool = True) -> None:
    """Persist business data without letting stale requests erase OAuth.

    Most handlers load the whole JSON document and save it later. A handler
    which loaded before a Qonto token rotation therefore carries an obsolete
    ``qonto_oauth`` object. Preserve the canonical on-disk object at the last
    possible moment, while holding the file lock. Only the OAuth callback,
    refresh and explicit reset opt out.
    """
    if _is_partner_scoped_session():
        data = _merge_partner_scoped_payload(data, _current_partner_id())
    _ensure_multi_partner_payload(data)
    normalize_all_partner_subscriptions(data)

    def preserve_canonical_oauth(payload: Dict[str, Any]) -> Dict[str, Any]:
        canonical = _load_valid_json_payload(DATA_FILE)
        if isinstance(canonical, dict) and isinstance(canonical.get("qonto_oauth"), dict):
            payload["qonto_oauth"] = canonical["qonto_oauth"]
        return payload

    transform = preserve_canonical_oauth if preserve_qonto_oauth else None
    _write_json_with_backups(DATA_FILE, data, _data_lock, payload_transform=transform)


def update_data(
    mutator: Callable[[Dict[str, Any]], Any],
    *,
    run_background_tasks: bool = False,
    preserve_qonto_oauth: bool = True,
) -> Any:
    """Apply one logical read-modify-write transaction to data.json.

    The shared RLock stays held from the canonical file read through the atomic
    replace so gthread requests cannot overwrite each other's changes with a
    stale in-memory copy. Do not perform network I/O or sleeps inside mutator.
    """
    with _data_lock:
        data = load_data(run_background_tasks=run_background_tasks)
        result = mutator(data)
        save_data(data, preserve_qonto_oauth=preserve_qonto_oauth)
        return data if result is None else result

def _atomic_update_data(mutator: Callable[[Dict[str, Any]], Dict[str, Any]]) -> Dict[str, Any]:
    """Apply a business mutation while holding the JSON store's process/file locks."""
    result: Dict[str, Any] = {}

    def transform(caller_payload: Dict[str, Any]) -> Dict[str, Any]:
        nonlocal result
        canonical = _load_valid_json_payload(DATA_FILE)
        payload = canonical if isinstance(canonical, dict) else caller_payload
        _ensure_multi_partner_payload(payload)
        result = mutator(payload)
        return payload

    seed = _load_valid_json_payload(DATA_FILE) or _empty_data_payload()
    _write_json_with_backups(DATA_FILE, seed, _data_lock, payload_transform=transform)
    return result

def _load_wedof_webhooks() -> List[Dict[str, Any]]:
    if not os.path.exists(WEDOF_WEBHOOK_FILE):
        return []
    try:
        with open(WEDOF_WEBHOOK_FILE, "r", encoding="utf-8") as f:
            loaded = json.load(f)
        if isinstance(loaded, list):
            return loaded
    except Exception:
        app.logger.exception("[WEDOF WEBHOOK] erreur lecture historique")
    return []

def _save_wedof_webhooks(entries: List[Dict[str, Any]]) -> None:
    _write_json_with_backups(WEDOF_WEBHOOK_FILE, entries, _wedof_webhook_lock)

def _extract_wedof_payload_fields(payload: Dict[str, Any]) -> Dict[str, str]:
    flat = json.dumps(payload, ensure_ascii=False)
    attendee = payload.get("attendee") if isinstance(payload.get("attendee"), dict) else {}
    attendee_address = attendee.get("address") if isinstance(attendee.get("address"), dict) else {}
    training = payload.get("trainingActionInfo") if isinstance(payload.get("trainingActionInfo"), dict) else {}
    session_info = training.get("session") if isinstance(training.get("session"), dict) else {}

    def to_text(value: Any) -> str:
        if value is None:
            return ""
        text = str(value).strip()
        return text

    def pick(*values: Any) -> str:
        for value in values:
            text = to_text(value)
            if text:
                return text
        return ""

    return {
        "wedof_case_id": pick(payload.get("externalId"), payload.get("dataProviderId"), payload.get("id"), payload.get("folderId"), payload.get("registrationFolderId"), payload.get("registration_folder_id"), payload.get("resourceId"), payload.get("objectId"), payload.get("dossierId"), payload.get("dossier_id"), payload.get("edof_id"), payload.get("application_id")),
        "first_name": pick(attendee.get("firstName"), payload.get("first_name"), payload.get("firstname"), payload.get("prenom")),
        "last_name": pick(attendee.get("lastName"), payload.get("last_name"), payload.get("lastname"), payload.get("nom")),
        "email": pick(attendee.get("email"), payload.get("email"), payload.get("mail")),
        "phone": pick(attendee.get("phoneNumber"), payload.get("phone"), payload.get("telephone"), payload.get("tel")),
        "full_address": pick(attendee.get("fullAddress")),
        "city": pick(attendee_address.get("city")),
        "zip_code": pick(attendee_address.get("zipCode")),
        "date_of_birth": pick(attendee.get("dateOfBirth")),
        "training_title": pick(training.get("title"), payload.get("training_title"), payload.get("formation"), payload.get("formation_title"), payload.get("intitule_formation")),
        "status": pick(payload.get("state"), payload.get("status"), payload.get("dossier_status"), payload.get("statut")),
        "external_link": pick(payload.get("externalLink")),
        "training_date": pick(
            training.get("sessionStartDate"),
            training.get("startDate"),
            training.get("dateStart"),
            session_info.get("startDate"),
            session_info.get("sessionStartDate"),
            payload.get("training_date"),
            payload.get("date_formation"),
            payload.get("start_date"),
        ),
        "training_end_date": pick(
            training.get("sessionEndDate"),
            training.get("endDate"),
            training.get("dateEnd"),
            session_info.get("endDate"),
            session_info.get("sessionEndDate"),
            payload.get("training_end_date"),
            payload.get("end_date"),
        ),
        "price_total_incl": pick(training.get("totalIncl")),
        "_raw": flat,
    }


def _wedof_entry_display_fields(entry: Dict[str, Any]) -> Dict[str, str]:
    """Return the first displayable WeDoF values from webhook and folder data."""
    payload = entry.get("payload") if isinstance(entry.get("payload"), dict) else {}
    folder_details = entry.get("wedof_folder_details") if isinstance(entry.get("wedof_folder_details"), dict) else {}
    candidates = [payload]
    if isinstance(payload.get("data"), dict):
        candidates.append(payload["data"])
    candidates.append(folder_details)
    if isinstance(folder_details.get("data"), dict):
        candidates.append(folder_details["data"])

    extracted = [_extract_wedof_payload_fields(candidate) for candidate in candidates]
    keys = ("first_name", "last_name", "email", "phone", "training_title", "training_date", "training_end_date")
    return {
        key: next((fields[key] for fields in extracted if fields.get(key)), "")
        for key in keys
    }


def _find_wedof_folder_id(payload: Any) -> str:
    if not isinstance(payload, dict):
        return ""
    data_obj = payload.get("data") if isinstance(payload.get("data"), dict) else {}
    candidates = [
        payload.get("id"),
        payload.get("folderId"),
        payload.get("registrationFolderId"),
        payload.get("registration_folder_id"),
        payload.get("resourceId"),
        payload.get("objectId"),
        payload.get("dossierId"),
        data_obj.get("id"),
        data_obj.get("folderId"),
        data_obj.get("registrationFolderId"),
    ]
    for value in candidates:
        if value is None:
            continue
        text = str(value).strip()
        if text:
            return text
    return ""


def _fetch_wedof_folder_details(folder_id: str) -> Dict[str, Any]:
    token = (os.environ.get("WEDOF_API_TOKEN") or "").strip()
    if not folder_id or not token:
        return {}

    url_candidates = [
        f"https://www.wedof.fr/api/registration-folders/{folder_id}",
        f"https://api.wedof.fr/registration-folders/{folder_id}",
        f"https://api.wedof.fr/api/registration-folders/{folder_id}",
    ]
    headers = {
        "Authorization": f"Bearer {token}",
        "Accept": "application/json",
    }

    for url in url_candidates:
        try:
            app.logger.info("[WEDOF] appel API détail dossier = %s", url)
            resp = requests.get(url, headers=headers, timeout=15)
            body_preview = resp.text[:1200]
            app.logger.info("[WEDOF] réponse API détail dossier = status=%s body=%s", resp.status_code, body_preview)
            if resp.ok:
                return resp.json() if resp.content else {}
        except Exception:
            app.logger.exception("[WEDOF] erreur appel API détail dossier url=%s", url)
    return {}


def _notification_id(prefix: str) -> str:
    return f"{prefix}-{uuid.uuid4().hex[:10].upper()}"


def add_notification(data: Dict[str, Any], bucket: str, label: str, meta: Optional[dict] = None) -> dict:
    notifications = data.setdefault(bucket, [])
    prefix_map = {
        "notifications_edof": "EDOF",
        "notifications_financement_refuse": "FTR",
        "notifications_prelevements": "PREL",
        "notifications_prelevement_non_valides": "PNV",
        "notifications_phone_relances": "REL",
        "notifications_vae_relances": "RVE",
        "notifications_cnaps_pre_relances": "PRE",
        "notifications_test_fr": "TFR",
        "notifications_convention_unsigned": "CNS",
        "notifications_vtc_books": "VTB",
        "notifications_admin": "ADM",
    }
    entry = {
        "id": _notification_id(prefix_map.get(bucket, "NOTI")),
        "label": label,
        "created_at": _now_iso(),
        "done": False,
    }
    if meta:
        entry["meta"] = meta
    notifications.insert(0, entry)
    return entry


def _notifications_bucket_key(bucket: str) -> Optional[str]:
    return {
        "edof": "notifications_edof",
        "financement_refuse": "notifications_financement_refuse",
        "prelevements": "notifications_prelevements",
        "prelevements_non_valides": "notifications_prelevement_non_valides",
        "relances": "notifications_phone_relances",
        "vae_relances": "notifications_vae_relances",
        "cnaps_pre": "notifications_cnaps_pre_relances",
        "test_fr": "notifications_test_fr",
        "convention_unsigned": "notifications_convention_unsigned",
        "vtc_books": "notifications_vtc_books",
    }.get(bucket)


def _is_vtc_book_address_complete(trainee: Dict[str, Any]) -> bool:
    return bool((trainee.get("address") or "").strip() and (trainee.get("zip_code") or "").strip() and (trainee.get("city") or "").strip())


def _sync_vtc_book_notification(data: Dict[str, Any], session_obj: Dict[str, Any], trainee: Dict[str, Any]) -> bool:
    notifications = data.setdefault("notifications_vtc_books", [])
    session_id = (session_obj.get("id") or "").strip()
    trainee_id = (trainee.get("id") or "").strip()
    if not session_id or not trainee_id:
        return False

    trainee_name = _format_trainee_name(trainee.get("first_name", ""), trainee.get("last_name", ""))
    should_notify = _is_vtc_book_address_complete(trainee) and not (trainee.get("vtc_book_sent_at") or "").strip()
    changed = False

    entry = next(
        (
            item
            for item in notifications
            if (item.get("meta") or {}).get("session_id") == session_id
            and (item.get("meta") or {}).get("trainee_id") == trainee_id
        ),
        None,
    )

    if should_notify:
        if entry is None:
            add_notification(
                data,
                "notifications_vtc_books",
                f"📚 Livre à envoyer — {trainee_name}",
                meta={
                    "session_id": session_id,
                    "trainee_id": trainee_id,
                    "first_name": (trainee.get("first_name") or "").strip(),
                    "last_name": (trainee.get("last_name") or "").strip(),
                    "address": (trainee.get("address") or "").strip(),
                    "zip_code": (trainee.get("zip_code") or "").strip(),
                    "city": (trainee.get("city") or "").strip(),
                },
            )
            changed = True
        else:
            if entry.get("done"):
                entry["done"] = False
                entry["done_at"] = ""
                changed = True
            meta = entry.setdefault("meta", {})
            refreshed_meta = {
                "session_id": session_id,
                "trainee_id": trainee_id,
                "first_name": (trainee.get("first_name") or "").strip(),
                "last_name": (trainee.get("last_name") or "").strip(),
                "address": (trainee.get("address") or "").strip(),
                "zip_code": (trainee.get("zip_code") or "").strip(),
                "city": (trainee.get("city") or "").strip(),
            }
            for key, value in refreshed_meta.items():
                if meta.get(key) != value:
                    meta[key] = value
                    changed = True
            expected_label = f"📚 Livre à envoyer — {trainee_name}"
            if entry.get("label") != expected_label:
                entry["label"] = expected_label
                changed = True
    elif entry is not None and not entry.get("done"):
        entry["done"] = True
        entry["done_at"] = _now_iso()
        changed = True

    return changed


def _secretariat_notifications_payload(data: Dict[str, Any]) -> Dict[str, Any]:
    def _clean(value: Any) -> str:
        return str(value or "").strip()

    def _test_fr_contact(meta: Dict[str, Any]) -> Dict[str, str]:
        session_id = _clean(meta.get("session_id"))
        trainee_id = _clean(meta.get("trainee_id"))
        if not session_id or not trainee_id:
            return {}

        session_obj = _find_session_by_id(data, session_id)
        if not session_obj:
            return {}

        trainee = next(
            (item for item in _session_trainees_list(session_obj) if _clean(item.get("id")) == trainee_id),
            None,
        )
        if not trainee:
            return {}

        return {
            "first_name": _clean(trainee.get("first_name")),
            "last_name": _clean(trainee.get("last_name")),
            "phone": _clean(trainee.get("phone")),
        }

    def _with_created_fr(items: List[Dict[str, Any]], bucket: str) -> List[Dict[str, Any]]:
        out = []
        for item in items:
            if bucket == "cnaps_pre":
                meta = item.get("meta") or {}
                cnaps_space = (meta.get("cnapsv3_espace_cnaps") if isinstance(meta, dict) else "") or ""
                if _normalize_status(str(cnaps_space)).startswith("VALIDE"):
                    continue
            cloned = dict(item)
            cloned["created_fr"] = fr_datetime(item.get("created_at") or "")
            if bucket == "test_fr":
                meta = dict(cloned.get("meta") or {})
                fallback = _test_fr_contact(meta)
                for key in ("first_name", "last_name", "phone"):
                    if not _clean(meta.get(key)) and fallback.get(key):
                        meta[key] = fallback[key]
                if meta:
                    cloned["meta"] = meta
            out.append(cloned)
        return out

    notifications = {
        "edof": _with_created_fr(list(data.get("notifications_edof", [])), "edof"),
        "financement_refuse": _with_created_fr(list(data.get("notifications_financement_refuse", [])), "financement_refuse"),
        "prelevements": _with_created_fr(list(data.get("notifications_prelevements", [])), "prelevements"),
        "prelevements_non_valides": _with_created_fr(list(data.get("notifications_prelevement_non_valides", [])), "prelevements_non_valides"),
        "relances": _with_created_fr(list(data.get("notifications_phone_relances", [])), "relances"),
        "vae_relances": _with_created_fr(list(data.get("notifications_vae_relances", [])), "vae_relances"),
        "cnaps_pre": _with_created_fr(list(data.get("notifications_cnaps_pre_relances", [])), "cnaps_pre"),
        "test_fr": _with_created_fr(list(data.get("notifications_test_fr", [])), "test_fr"),
        "convention_unsigned": _with_created_fr(list(data.get("notifications_convention_unsigned", [])), "convention_unsigned"),
        "vtc_books": _with_created_fr(list(data.get("notifications_vtc_books", [])), "vtc_books"),
    }
    unresolved_total = 0
    for items in notifications.values():
        unresolved_total += sum(1 for item in items if not item.get("done"))
    return {
        "notifications": notifications,
        "unresolved_total": unresolved_total,
    }


def _session_period_label(session_obj: Dict[str, Any]) -> str:
    training = formation_label(_session_get(session_obj, "training_type", ""))
    start = fr_date(_session_get(session_obj, "date_start", ""))
    end = fr_date(_session_get(session_obj, "date_end", ""))
    if training and start and end:
        return f"{training} du {start} au {end}"
    if training:
        return training
    return ""


def _find_session_by_id(data: Dict[str, Any], session_id: str) -> Optional[Dict[str, Any]]:
    target = (session_id or "").strip()
    if not target:
        return None
    for session_obj in (data.get("sessions", []) or []):
        if (session_obj.get("id") or "").strip() == target:
            return session_obj
    return None


def _history_sort_key(value: str) -> float:
    s = (value or "").strip()
    if not s:
        return 0.0
    normalized = s.replace("Z", "+00:00")
    try:
        return datetime.datetime.fromisoformat(normalized).timestamp()
    except Exception:
        pass
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%dT%H:%M", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%dT%H:%M:%S.%f"):
        try:
            return datetime.datetime.strptime(s[:26], fmt).timestamp()
        except Exception:
            pass
    return 0.0


def _history_kind_from_text(raw: str) -> str:
    source = (raw or "").upper()
    if "SMS" in source:
        return "sms"
    if "MAIL" in source or "EMAIL" in source:
        return "mail"
    if "APPEL" in source or "RÉPONSE SECRÉTAIRE" in source or "REPONSE SECRETAIRE" in source:
        return "appel"
    if "RELANCE" in source:
        return "relance"
    return "action"


def append_trainee_history_event(trainee: Dict[str, Any], label: str, details: str = "", kind: str = "action", at: Optional[str] = None) -> None:
    history = trainee.get("activity_history")
    if not isinstance(history, list):
        history = []
    history.insert(0, {
        "label": (label or "Action").strip(),
        "details": (details or "").strip(),
        "kind": (kind or "action").strip().lower(),
        "at": (at or _now_iso()).strip(),
    })
    trainee["activity_history"] = history[:1000]



VAE_IMPORTANT_HISTORY_STATUS_LABELS = {
    "livret_1_todo": "Livret 1 en attente de transmission",
    "livret_1_analysis": "Livret 1 en analyse (transmis à SCOTIA)",
    "livret_1_validated": "Livret 1 validé",
    "non_recevable": "Livret 1 non recevable",
    "complement_requested": "En attente de documents complémentaires",
    "complement_to_review": "Complément de dossier à consulter (SCOTIA)",
    "livret_2_todo": "Livret 2 à compléter",
    "livret_2_validated": "Livret 2 validé",
    "certified": "Certification obtenue",
}


def _vae_history_normalized_date(value: Any) -> str:
    """Retourne une date triable/affichable pour l'historique VAE condensé."""
    s = str(value or "").strip()
    if not s:
        return ""
    for fmt in ("%d/%m/%Y à %Hh%M", "%d/%m/%Y %Hh%M", "%d/%m/%Y"):
        try:
            return datetime.datetime.strptime(s, fmt).isoformat()
        except Exception:
            pass
    return s


def _vae_first_history_date(*values: Any) -> str:
    for value in values:
        normalized = _vae_history_normalized_date(value)
        if normalized:
            return normalized
    return ""


def _latest_activity_history_date(trainee: Dict[str, Any], label: str = "", details: str = "") -> str:
    label_norm = _normalize_vae_status_text(label)
    details_norm = _normalize_vae_status_text(details)
    for item in (trainee.get("activity_history") or []):
        if not isinstance(item, dict):
            continue
        item_label = _normalize_vae_status_text(item.get("label") or "")
        item_details = _normalize_vae_status_text(item.get("details") or "")
        label_matches = not label_norm or label_norm in item_label
        details_matches = not details_norm or details_norm in item_details
        if label_matches and details_matches:
            return _vae_history_normalized_date(item.get("at") or "")
    return ""


def build_vae_important_history_entries(trainee: Dict[str, Any]) -> List[Dict[str, str]]:
    """Historique VAE volontairement limité aux jalons métier utiles à l'admin."""
    entries: List[Dict[str, str]] = []
    seen_labels = set()
    action_dates = trainee.get("vae_action_dates") if isinstance(trainee.get("vae_action_dates"), dict) else {}
    status_key = vae_status_view(trainee.get("vae_status") or trainee.get("vae_status_label"))["key"]
    scotia_status = (trainee.get("scotia_status") or "").strip()
    scotia_need_control = _scotia_complementary_documents_need_control(trainee)

    def _add(status: str, at: str, details: str = "") -> None:
        label = VAE_IMPORTANT_HISTORY_STATUS_LABELS.get(status, "")
        if not label or label in seen_labels:
            return
        at = _vae_history_normalized_date(at)
        if not at:
            return
        seen_labels.add(label)
        entries.append({
            "kind": "action",
            "emoji": "📝",
            "label": label,
            "at": at,
            "at_display": history_datetime(at),
            "details": (details or "").strip(),
        })

    _add(
        "livret_1_todo",
        _vae_first_history_date(trainee.get("created_at"), action_dates.get("livret_1_todo_at")),
    )

    transmitted_at = _vae_first_history_date(
        action_dates.get("livret_1_transmitted_scotia"),
        trainee.get("livret_1_transmitted_scotia_at"),
        _latest_activity_history_date(trainee, "Dossier transmis à SCOTIA", "Livret 1"),
        action_dates.get("livret_1_received"),
        action_dates.get("livret_1_analysis_at"),
    )
    if transmitted_at or status_key not in {"livret_1_todo"}:
        _add("livret_1_analysis", transmitted_at or trainee.get("updated_at") or trainee.get("created_at"))

    if scotia_status == "complement_requested" or status_key == "complement_requested":
        _add(
            "complement_requested",
            _vae_first_history_date(action_dates.get("complement_requested_at"), trainee.get("scotia_processed_at")),
        )
    if scotia_need_control:
        _add(
            "complement_to_review",
            _vae_first_history_date(
                trainee.get("scotia_complementary_documents_received_at"),
                trainee.get("updated_at"),
                action_dates.get("complementary_documents_reviewed_at"),
            ),
        )

    if scotia_status == "non_recevable" or status_key == "non_recevable":
        _add(
            "non_recevable",
            _vae_first_history_date(action_dates.get("non_recevable_scotia_at"), trainee.get("scotia_processed_at")),
        )

    if scotia_status == "recevable" or status_key in {
        "livret_1_validated",
        "financement_validated",
        "livret_2_todo",
        "livret_2_analysis",
        "livret_2_validated",
        "financement_l2_validated",
        "jury",
        "certified",
    }:
        _add(
            "livret_1_validated",
            _vae_first_history_date(
                action_dates.get("livret_1_validated"),
                action_dates.get("recevable_scotia_at"),
                trainee.get("scotia_processed_at"),
            ),
        )

    if status_key in {"livret_2_todo", "livret_2_analysis", "livret_2_validated", "financement_l2_validated", "jury", "certified"}:
        _add("livret_2_todo", _vae_first_history_date(action_dates.get("financement_validated"), trainee.get("updated_at")))

    if status_key in {"livret_2_validated", "financement_l2_validated", "jury", "certified"} or (trainee.get("scotia_livret_2_status") or "").strip() == "livret_2_ok":
        _add(
            "livret_2_validated",
            _vae_first_history_date(action_dates.get("livret_2_validated"), trainee.get("scotia_livret_2_processed_at")),
        )

    if status_key == "certified":
        _add("certified", _vae_first_history_date(action_dates.get("diplome_obtenu"), trainee.get("updated_at")))

    entries.sort(key=lambda item: _history_sort_key(item.get("at") or ""), reverse=True)
    return entries


def build_trainee_history_entries(trainee: Dict[str, Any]) -> List[Dict[str, str]]:
    entries: List[Dict[str, str]] = []

    def _add(kind: str, label: str, at: str, details: str = "") -> None:
        if not (at or "").strip():
            return
        emoji = {
            "mail": "📧",
            "relance": "🔁",
            "appel": "📞",
            "sms": "📱",
            "action": "📝",
        }.get(kind, "📌")
        entries.append({
            "kind": kind,
            "emoji": emoji,
            "label": label,
            "at": at,
            "at_display": history_datetime(at),
            "details": (details or "").strip(),
        })

    field_events = [
        ("access_sent_at", "Espace stagiaire envoyé", "mail"),
        ("docs_notified_at", "Notification envoi des documents", "mail"),
        ("docs_last_nonconform_notified_at", "Notification documents non conformes", "mail"),
        ("docs_last_relance_at", "Relance documents", "relance"),
        ("test_fr_last_notified_at", "Lien test de français envoyé", "mail"),
        ("test_fr_last_relance_at", "Relance test de français", "relance"),
        ("convention_unsigned_notified_at", "Relance convention non signée", "relance"),
        ("cnaps_pre_relance_last_sent_at", "Relance PRE envoyée", "relance"),
        ("elearning_link_sent_at", "Lien e-learning envoyé", "mail"),
        ("vtc_cm_reminder_sent_at", "Relance identifiants VTC envoyée", "relance"),
        ("public_last_login_at", "Connexion espace stagiaire", "action"),
        ("etiquette_word_downloaded_at", "Étiquette Word téléchargée", "action"),
        ("created_at", "Dossier créé", "action"),
    ]
    for field_name, label, kind in field_events:
        _add(kind, label, trainee.get(field_name) or "")

    for field_name, value in trainee.items():
        if not (isinstance(field_name, str) and field_name.endswith("_at") and isinstance(value, str)):
            continue
        if field_name in {x[0] for x in field_events}:
            continue
        if not value.strip():
            continue
        auto_label = field_name[:-3].replace("_", " ").strip().capitalize()
        _add(_history_kind_from_text(field_name), auto_label, value)

    for followup in (trainee.get("phone_followups") or []):
        event_type = (followup.get("type") or "Suivi").strip()
        details = (followup.get("details") or "").strip()
        comment = (followup.get("comment") or "").strip()
        full_details = " · ".join([chunk for chunk in (details, comment) if chunk])
        _add(_history_kind_from_text(f"{event_type} {details}"), event_type, followup.get("at") or "", full_details)

    for doc in (trainee.get("documents") or []):
        label = (doc.get("label") or "Document").strip()
        status = (doc.get("status") or "").strip()
        comment = (doc.get("comment") or "").strip()
        files = [x for x in (doc.get("files") or []) if x]
        if not files and (doc.get("file") or "").strip():
            files = [(doc.get("file") or "").strip()]
        details = []
        if status:
            details.append(f"Statut actuel : {status}")
        if files:
            details.append(f"Fichiers : {len(files)}")
        if comment:
            details.append(f"Commentaire : {comment}")
        if details:
            _add("action", f"Document · {label}", trainee.get("updated_at") or trainee.get("created_at") or "", " · ".join(details))

    for item in (trainee.get("activity_history") or []):
        if not isinstance(item, dict):
            continue
        _add(
            (item.get("kind") or "action").strip().lower(),
            (item.get("label") or "Action").strip(),
            (item.get("at") or "").strip(),
            (item.get("details") or "").strip(),
        )

    entries.sort(key=lambda item: _history_sort_key(item.get("at") or ""), reverse=True)
    return entries


def build_trainee_email_history_entries(trainee: Dict[str, Any]) -> List[Dict[str, str]]:
    entries: List[Dict[str, str]] = []
    for item in (trainee.get("sent_email_history") or []):
        if not isinstance(item, dict):
            continue
        sent_at = (item.get("sent_at") or "").strip()
        if not sent_at:
            continue
        entries.append({
            "to_email": (item.get("to_email") or "").strip(),
            "subject": (item.get("subject") or "(Sans objet)").strip(),
            "html": item.get("html") or "",
            "sent_at": sent_at,
            "sent_date": fr_date(sent_at),
        })

    entries.sort(key=lambda item: _history_sort_key(item.get("sent_at") or ""), reverse=True)
    return entries


def _admin_notification_details(data: Dict[str, Any], item: Dict[str, Any]) -> List[str]:
    meta = item.get("meta") or {}
    details: List[str] = []

    session_obj = _find_session_by_id(data, meta.get("session_id") or "")
    period = ""
    if session_obj:
        period = _session_period_label(session_obj)
    if not period:
        training = (meta.get("training") or "").strip()
        date_start = fr_date(meta.get("date_start") or "")
        date_end = fr_date(meta.get("date_end") or "")
        if training and date_start and date_end:
            period = f"{training} du {date_start} au {date_end}"
        elif training:
            period = training
    if period:
        details.append(period)

    called_resolution = (meta.get("called_resolution") or "").strip()
    if called_resolution:
        details.append(f"Résultat : {called_resolution}")

    comment = (meta.get("comment") or meta.get("last_comment") or "").strip()
    if comment:
        details.append(f"Commentaire : {comment}")

    call_status = (meta.get("call_status") or "").strip()
    if call_status:
        details.append(f"Statut d'appel : {call_status}")

    if meta.get("kind") == "qonto_direct_debit_rejected":
        details.append(f"Montant rejeté : {_format_euro(meta.get('amount'))}")
        details.append(f"Date prévue : {fr_date(meta.get('scheduled_date') or '') or 'Non renseignée'}")

    return details


def _admin_notification_trainee_url(data: Dict[str, Any], item: Dict[str, Any]) -> str:
    meta = item.get("meta") or {}
    session_id = (meta.get("session_id") or "").strip()
    trainee_id = (meta.get("trainee_id") or "").strip()
    if not session_id or not trainee_id:
        return ""

    session_obj = _find_session_by_id(data, session_id)
    if not session_obj:
        return ""

    trainee_exists = any(
        (trainee.get("id") or "").strip() == trainee_id
        for trainee in _session_trainees_list(session_obj)
    )
    if not trainee_exists:
        return ""

    return url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id)


def _admin_notifications_payload(data: Dict[str, Any]) -> Dict[str, Any]:
    notifications = []
    unresolved_total = 0
    for item in list(data.get("notifications_admin", [])):
        cloned = dict(item)
        cloned["created_fr"] = fr_datetime(item.get("created_at") or "")
        cloned["details"] = _admin_notification_details(data, item)
        cloned["trainee_url"] = _admin_notification_trainee_url(data, item)
        notifications.append(cloned)
        if not item.get("done"):
            unresolved_total += 1
    return {
        "notifications": notifications,
        "unresolved_total": unresolved_total,
    }


def _admin_can_view_notifications() -> bool:
    return bool(session.get("admin_logged_in"))


def _admin_can_manage_notifications() -> bool:
    return session.get("admin_role") in {"admin", "super_admin"}


def _format_trainee_name(first_name: str, last_name: str) -> str:
    return f"{normalize_first_name(first_name)} {normalize_last_name(last_name)}".strip()


def _web_push_enabled() -> bool:
    return bool(WEB_PUSH_VAPID_PUBLIC_KEY and WEB_PUSH_VAPID_PRIVATE_KEY and WEB_PUSH_LIBRARY_AVAILABLE)


def _normalize_push_subscription(payload: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    endpoint = str(payload.get("endpoint") or "").strip()
    keys = payload.get("keys") or {}
    p256dh = str(keys.get("p256dh") or "").strip()
    auth = str(keys.get("auth") or "").strip()
    if not endpoint or not p256dh or not auth:
        return None
    return {
        "endpoint": endpoint,
        "keys": {
            "p256dh": p256dh,
            "auth": auth,
        },
    }


def _send_admin_push_notifications(data: Dict[str, Any], notification: Dict[str, Any]) -> int:
    if not _web_push_enabled():
        return 0

    subscriptions = list(data.get("admin_push_subscriptions", []))
    if not subscriptions:
        return 0

    from pywebpush import webpush, WebPushException

    payload = json.dumps({
        "title": ADMIN_PUSH_TITLE or "Intégrale Connect",
        "body": (notification.get("label") or "").strip() or "Nouvelle notification admin",
        "url": url_for("admin_sessions", _external=True),
        "notification_id": notification.get("id") or "",
        "icon": url_for("static", filename="logo-integrale.png", _external=True),
        "badge": url_for("static", filename="logo-integrale.png", _external=True),
        "image": url_for("static", filename="logo-integrale.png", _external=True),
    })
    sent = 0
    invalid_endpoints: Set[str] = set()

    for sub in subscriptions:
        try:
            webpush(
                subscription_info=sub,
                data=payload,
                vapid_private_key=WEB_PUSH_VAPID_PRIVATE_KEY,
                vapid_claims={"sub": WEB_PUSH_VAPID_CLAIMS_SUB},
                ttl=300,
            )
            sent += 1
        except WebPushException as exc:
            status = getattr(exc.response, "status_code", None)
            if status in (404, 410):
                invalid_endpoints.add(str(sub.get("endpoint") or ""))
        except Exception as exc:
            print(f"[PUSH] Erreur push web: {exc}")

    if invalid_endpoints:
        data["admin_push_subscriptions"] = [
            sub for sub in subscriptions
            if str(sub.get("endpoint") or "") not in invalid_endpoints
        ]

    return sent


def add_admin_notification(data: Dict[str, Any], label: str, meta: Optional[dict] = None) -> dict:
    entry = add_notification(data, "notifications_admin", label, meta=meta)
    _send_admin_push_notifications(data, entry)
    return entry


