def find_session(data: Dict[str, Any], session_id: str) -> Optional[Dict[str, Any]]:
    for s in data.get("sessions", []):
        if s.get("id") == session_id:
            return s
    return None


def ensure_public_tokens(data):
    changed = False

    for session in data.get("sessions", []):
        trainees = session.get("trainees") or session.get("stagiaires") or []

        for trainee in trainees:
            if "public_token" not in trainee or not trainee["public_token"]:
                trainee["public_token"] = uuid.uuid4().hex
                changed = True

    return changed



def find_trainee(session: Dict[str, Any], trainee_id: str) -> Optional[Dict[str, Any]]:
    for t in session.get("trainees", []):
        if t.get("id") == trainee_id:
            return t
    return None


def _session_get(s: Dict[str, Any], key: str, fallback: str = "") -> str:
    """
    Backward compatible getter: support old FR keys if needed.
    """
    if key in s and s.get(key) not in (None, ""):
        return s.get(key)

    # old keys from previous versions
    fr_map = {
        "name": "nom",
        "date_start": "date_debut",
        "date_end": "date_fin",
        "exam_date": "date_examen",
        "exam_theory_date": "date_examen_theorique",
        "exam_practice_date": "date_examen_pratique",
        "training_type": "type_formation",
        "trainees": "stagiaires",
    }
    fr_key = fr_map.get(key)
    if fr_key and fr_key in s and s.get(fr_key) not in (None, ""):
        return s.get(fr_key)

    return fallback


def _session_trainees_list(s: Dict[str, Any]) -> List[Dict[str, Any]]:
    if "trainees" in s and isinstance(s.get("trainees"), list):
        return s.get("trainees", [])
    if "stagiaires" in s and isinstance(s.get("stagiaires"), list):
        # convert on the fly (non destructif)
        out = []
        for st in s.get("stagiaires", []):
            out.append(_convert_old_stagiaire_to_trainee(st))
        return out
    return []


def _convert_old_stagiaire_to_trainee(st: Dict[str, Any]) -> Dict[str, Any]:
    # best-effort mapping
    printed_raw = st.get("printed")
    printed_bool = printed_raw if isinstance(printed_raw, bool) else str(printed_raw or "").strip().lower() in {"1", "true", "yes", "oui"}
    return {
        "id": st.get("id") or ("TRN-" + uuid.uuid4().hex[:8].upper()),
        "personal_id": st.get("id") or "",
        "last_name": st.get("nom") or "",
        "first_name": st.get("prenom") or "",
        "email": st.get("email") or "",
        "phone": st.get("telephone") or "",
        "birth_date": st.get("date_naissance") or st.get("birth_date") or "",
        "birth_city": st.get("ville_naissance") or st.get("birth_city") or "",
        "birth_department": st.get("departement_naissance") or st.get("birth_department") or "",
        "address": st.get("adresse") or st.get("address") or "",
        "zip_code": st.get("code_postal") or st.get("zip_code") or "",
        "city": st.get("ville") or st.get("city") or "",
        "nom_naissance": st.get("nom_naissance") or "",
        "comment": st.get("commentaire") or "",
        "cnaps": (st.get("cnaps") or "INCONNU"),
        "convention_status": _map_convention_to_enum(st.get("convention")),
        "test_fr_status": _map_testfr_to_enum(st.get("test_francais")),
        "dossier_status": "complete" if (st.get("dossier") == "complet") else "incomplete",
        "financement_status": _map_financement_to_enum(st.get("financement")),
        "vae_status": _map_vae_to_enum(st.get("vae")),
        "hosting_status": _map_hosting_to_enum(st.get("hebergement")),
        "documents": st.get("documents") or [],
        "public_token": st.get("public_token") or "",
        "created_at": st.get("created_at") or "",
        "updated_at": st.get("updated_at") or "",
        "phone_followups": st.get("phone_followups") or [],
        "summary_printed_at": st.get("summary_printed_at") or "",
        "printed": printed_bool,
        "printed_at": st.get("printed_at") or "",
        "ypareo_statut": st.get("ypareo_statut") or "Non envoyé",
        "ypareo_id": st.get("ypareo_id") or "",
        "ypareo_erreur": st.get("ypareo_erreur") or "",
    }


def _map_convention_to_enum(v: Optional[str]) -> str:
    v = (v or "").strip().lower()
    if v in ("signée", "signee", "signed"):
        return "signed"
    if "signature" in v or v in ("en cours de signature", "signing"):
        return "signing"
    return "soon"


def _map_testfr_to_enum(v: Optional[str]) -> str:
    v = (v or "").strip().lower()
    if v in ("validé", "valide", "validated"):
        return "validated"
    if v in ("relancé", "relance", "relancé(e)", "relancee"):
        return "relance"
    if v in ("en cours", "in progress", "in_progress", "en_cours"):
        return "in_progress"
    return "soon"


def _map_financement_to_enum(v: Optional[str]) -> str:
    v = (v or "").strip().lower()
    if v in ("validé", "valide", "validated"):
        return "validated"
    if "validation" in v or v in ("en cours de validation", "in_review"):
        return "in_review"
    return "soon"


def _map_vae_to_enum(v: Optional[str]) -> str:
    v = (v or "").strip().lower()
    if v in ("validé", "valide", "validated"):
        return "validated"
    if v in ("en cours", "in_progress", "in progress"):
        return "in_progress"
    return "soon"


def _map_hosting_to_enum(v: Optional[str]) -> str:
    v = (v or "").strip().lower()
    if v in ("réservé", "reserve", "reserved"):
        return "reserved"
    return "unknown"




# =========================
# Conformity logic (matching your enums)
# =========================

def trainee_is_conform(t: Dict[str, Any], training_type: str) -> bool:
    tt = (training_type or "").strip().upper()

    if t.get("dossier_status") != "complete":
        return False

    # Pour les formations dirigeant (hors VAE), la conformité de session
    # doit suivre l'état du dossier complet affiché en back-office.
    if "DIRIGEANT" in tt and tt != "DIRIGEANT VAE":
        return True

    if t.get("convention_status") != "signed":
        return False
    if t.get("test_fr_status") != "validated":
        return False
    if t.get("financement_status") != "validated":
        return False
    if tt == "DIRIGEANT VAE" and t.get("vae_status") != "validated":
        return False
    return True


def session_is_conform(session: Dict[str, Any]) -> bool:
    training_type = _session_get(session, "training_type", "")
    trainees = _session_trainees_list(session)
    if not trainees:
        return False
    return all(trainee_is_conform(t, training_type) for t in trainees)

def normalize_sessions_schema(data: Dict[str, Any]) -> bool:
    changed = False
    for s in data.get("sessions", []):
        # Si pas de trainees, on convertit depuis stagiaires
        if "trainees" not in s or not isinstance(s.get("trainees"), list):
            s["trainees"] = _session_trainees_list(s)
            changed = True

        # On supprime l’ancienne clé pour éviter 2 sources
        if "stagiaires" in s:
            s.pop("stagiaires", None)
            changed = True

    return changed

def _apply_vtc_manual_exam_status(trainee: Dict[str, Any], mode: str, status: str) -> None:
    """Keep legacy VTC exam fields in sync with a manual admin status."""
    normalized_status = (status or "").strip().lower()
    now = _now_iso()

    if mode == "theory":
        if normalized_status == "success":
            trainee["vtc_theory_result"] = "admissible"
            trainee["vtc_theory_result_label"] = "admissible"
        elif normalized_status == "failed":
            trainee["vtc_theory_result"] = "non_admissible"
            trainee["vtc_theory_result_label"] = "échec examen théorique"
            trainee["vtc_theory_failed_at"] = trainee.get("vtc_theory_failed_at") or now
            trainee["vtc_theory_exam_sent_at"] = ""
        elif normalized_status in ("waiting_registration", "waiting_result", ""):
            trainee["vtc_theory_result"] = ""
            trainee["vtc_theory_result_label"] = ""
            trainee["vtc_theory_exam_sent_at"] = ""
        return

    if mode == "practice":
        if normalized_status == "success":
            trainee["vtc_practice_result"] = "success"
            trainee["vtc_practice_result_label"] = "réussite examen pratique"
            trainee["vtc_practice_exam_sent_at"] = trainee.get("vtc_practice_exam_sent_at") or now
        elif normalized_status == "failed":
            trainee["vtc_practice_result"] = "non_admissible"
            trainee["vtc_practice_result_label"] = "échec examen pratique"
            trainee["vtc_practice_failed_at"] = trainee.get("vtc_practice_failed_at") or now
            trainee["vtc_practice_exam_sent_at"] = ""
        elif normalized_status in ("waiting_registration", "waiting_theory", "waiting_result", ""):
            trainee["vtc_practice_result"] = ""
            trainee["vtc_practice_result_label"] = ""
            trainee["vtc_practice_exam_sent_at"] = ""

def compute_vtc_exam_stats(trainees: List[Dict[str, Any]]) -> Dict[str, int]:
    total = len(trainees)
    theory_success = sum(
        1
        for t in trainees
        if (t.get("vtc_theory_status_manual") == "success")
        or (
            not t.get("vtc_theory_status_manual")
            and t.get("vtc_theory_exam_sent_at")
            and t.get("vtc_theory_result") not in ("failed", "non_admissible")
        )
    )
    theory_failed = sum(
        1
        for t in trainees
        if t.get("vtc_theory_status_manual") == "failed"
        or (not t.get("vtc_theory_status_manual") and t.get("vtc_theory_result") in ("failed", "non_admissible"))
    )
    practice_success = sum(
        1
        for t in trainees
        if (t.get("vtc_practice_status_manual") == "success")
        or (
            not t.get("vtc_practice_status_manual")
            and (t.get("vtc_practice_result") == "success" or t.get("vtc_practice_exam_sent_at"))
            and t.get("vtc_practice_result") not in ("failed", "non_admissible")
        )
    )
    practice_failed = sum(
        1
        for t in trainees
        if t.get("vtc_practice_status_manual") == "failed"
        or (not t.get("vtc_practice_status_manual") and t.get("vtc_practice_result") in ("failed", "non_admissible"))
    )
    cmar_ready = sum(1 for t in trainees if t.get("exam_fees_paid") or t.get("vtc_cmar_manual_ok"))
    convocation_sent = sum(1 for t in trainees if t.get("vtc_practice_convocation_sent_at"))
    return {
        "total": total,
        "theory_success": theory_success,
        "theory_failed": theory_failed,
        "theory_pending": max(total - theory_success - theory_failed, 0),
        "practice_success": practice_success,
        "practice_failed": practice_failed,
        "practice_pending": max(total - practice_success - practice_failed, 0),
        "cmar_ready": cmar_ready,
        "convocation_sent": convocation_sent,
    }


def compute_stats(session: Dict[str, Any]) -> Dict[str, Any]:
    training_type = _session_get(session, "training_type", "")
    trainees = _session_trainees_list(session)
    conform_count = sum(1 for t in trainees if trainee_is_conform(t, training_type))
    total = len(trainees)
    cnaps_accepted_count = sum(1 for t in trainees if _cnaps_is_accepted(t.get("cnaps")))
    return {
        "total": total,
        "conform_count": conform_count,
        "non_conform_count": total - conform_count,
        "session_is_conform": (total > 0 and conform_count == total),
        "cnaps_accepted_count": cnaps_accepted_count,
        "vtc": compute_vtc_exam_stats(trainees) if "VTC" in (training_type or "").upper() else {},
    }


def _session_jury_entries(session: Dict[str, Any]) -> List[Dict[str, Any]]:
    raw = session.get("juries")
    if raw is None:
        raw = session.get("jurys")
    if raw is None:
        raw = session.get("jury")
    if isinstance(raw, dict):
        if isinstance(raw.get("items"), list):
            raw = raw.get("items")
        else:
            raw = [raw]
    if not isinstance(raw, list):
        return []
    return [item for item in raw if isinstance(item, dict)]


def _normalize_jury_status(value: str) -> str:
    raw = (value or "").strip()
    if not raw:
        return ""
    cleaned = unicodedata.normalize("NFD", raw)
    cleaned = "".join(ch for ch in cleaned if unicodedata.category(ch) != "Mn")
    cleaned = cleaned.upper()
    cleaned = " ".join(cleaned.replace("_", " ").replace("-", " ").split())
    if cleaned in ("EN ATTENTE", "EN ATTENTE DE REPONSE", "ATTENTE", "PENDING", "A CONFIRMER"):
        return "pending"
    if cleaned in ("PRESENT", "PRESENTE", "PRESENTS", "PRESENTES"):
        return "present"
    if cleaned in ("ABSENT", "ABSENTE", "ABSENTS", "ABSENTES"):
        return "absent"
    return ""


# =========================
# CNAPS / Hosting fetchers
# =========================

def _normalize_cnaps_remote_history(raw_history: Any) -> List[Dict[str, str]]:
    normalized_entries: List[Dict[str, str]] = []
    if not isinstance(raw_history, list):
        return normalized_entries

    for item in raw_history:
        status = ""
        date = ""
        if isinstance(item, dict):
            status = (
                item.get("status")
                or item.get("statut")
                or item.get("statut_cnaps")
                or item.get("label")
                or ""
            )
            date = item.get("date") or item.get("at") or item.get("created_at") or ""
        elif isinstance(item, str):
            status = item

        status = str(status or "").strip()
        date = str(date or "").strip()
        if not status:
            continue
        normalized_entries.append({"status": status.upper(), "date": date})

    return normalized_entries


def merge_cnaps_history_entries(t: Dict[str, Any], entries: List[Dict[str, str]]) -> None:
    if not isinstance(entries, list) or not entries:
        return

    history = t.get("cnaps_history")
    if not isinstance(history, list):
        history = []

    def _entry_key(entry: Dict[str, Any]) -> str:
        status = _normalize_cnaps_status(entry.get("status"))
        date = str(entry.get("date") or "").strip()
        return f"{status}|{date}"

    known = {_entry_key(item) for item in history if isinstance(item, dict)}
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        status = str(entry.get("status") or "").strip()
        date = str(entry.get("date") or "").strip()
        if not status:
            continue
        candidate = {"status": status.upper(), "date": date or _now_iso()}
        key = _entry_key(candidate)
        if key in known:
            continue
        history.append(candidate)
        known.add(key)

    t["cnaps_history"] = history




def _first_non_empty_value(payload: Any, keys: Iterable[str]) -> str:
    wanted = {str(k).lower().replace("_", "").replace("-", "") for k in keys}

    def _walk(value: Any) -> str:
        if isinstance(value, dict):
            for key, item in value.items():
                normalized_key = str(key).lower().replace("_", "").replace("-", "")
                if normalized_key in wanted and item not in (None, ""):
                    return str(item).strip()
            for item in value.values():
                found = _walk(item)
                if found:
                    return found
        elif isinstance(value, list):
            for item in value:
                found = _walk(item)
                if found:
                    return found
        return ""

    return _walk(payload)


CNAPS_PUBLIC_ANNUAIRE_PAGE_SIZE = 10
CNAPS_PUBLIC_ANNUAIRE_MAX_PAGES = 25
CNAPS_TITLE_ORDER = ["AP SH", "AP A3P", "CP SH", "CP A3P"]
CNAPS_EXPLICIT_ACTIVITY_CODES = {
    "autorisation prealable - surveillance humaine ou gardiennage": "AP SH",
    "carte professionnelle - surveillance humaine ou gardiennage": "CP SH",
    "autorisation prealable - agent de protection physique des personnes": "AP A3P",
    "autorisation prealable - protection physique des personnes": "AP A3P",
    "carte professionnelle - agent de protection physique des personnes": "CP A3P",
    "carte professionnelle - protection physique des personnes": "CP A3P",
}
CNAPS_ACTIVITY_LABELS = {
    "AP SH": "Autorisation préalable - Surveillance humaine ou gardiennage",
    "CP SH": "Carte professionnelle - Surveillance humaine ou gardiennage",
    "AP A3P": "Autorisation préalable - Agent de protection physique des personnes",
    "CP A3P": "Carte professionnelle - Agent de protection physique des personnes",
}


def _normalize_cnaps_nub(value: Any) -> str:
    return re.sub(r"\D+", "", str(value or ""))


def _normalize_cnaps_name(value: Any) -> str:
    raw = unicodedata.normalize("NFD", str(value or ""))
    raw = "".join(ch for ch in raw if unicodedata.category(ch) != "Mn")
    return re.sub(r"\s+", " ", raw).strip().casefold()


def _normalize_cnaps_activity(value: Any) -> str:
    raw = str(value or "").strip()
    raw = unicodedata.normalize("NFD", raw)
    raw = "".join(ch for ch in raw if unicodedata.category(ch) != "Mn")
    raw = raw.replace("—", "-").replace("–", "-").replace("‑", "-")
    raw = raw.replace("’", "'").replace("`", "'")
    raw = re.sub(r"\s*-\s*", " - ", raw)
    raw = re.sub(r"\s+", " ", raw)
    return raw.strip().casefold()


def _build_cnaps_public_annuaire_payload(normalized_nom: str, normalized_nub: str, page_number: int) -> Dict[str, Any]:
    return {
        "nom": normalized_nom,
        "nub": normalized_nub,
        "page": page_number,
        "size": CNAPS_PUBLIC_ANNUAIRE_PAGE_SIZE,
        "sorts": [
            {"field": "nom", "asc": True},
            {"field": "dateFinValidite", "asc": True},
        ],
    }


def _cnaps_activity_code(label: Any) -> str:
    original = str(label or "").strip()
    normalized = _normalize_cnaps_activity(original)
    explicit = CNAPS_EXPLICIT_ACTIVITY_CODES.get(normalized)
    if explicit:
        return explicit
    principal = ""
    if normalized.startswith("autorisation prealable"):
        principal = "AP"
    elif normalized.startswith("carte professionnelle"):
        principal = "CP"
    activity = ""
    if "surveillance humaine ou gardiennage" in normalized:
        activity = "SH"
    elif "agent de protection physique des personnes" in normalized or "protection physique des personnes" in normalized:
        activity = "A3P"
    if principal and activity:
        return f"{principal} {activity}"
    return original or "Titre CNAPS inconnu"


def _cnaps_display_status(code: str, status: str) -> str:
    return " ".join(part for part in [str(code or "").strip(), str(status or "").strip().upper()] if part).strip()


def _extract_cnaps_public_annuaire_results(payload: Any) -> List[Dict[str, str]]:
    """Return title rows from the real CNAPS response_json['results'] list only."""
    if not isinstance(payload, dict) or not isinstance(payload.get("results"), list):
        return []
    rows: List[Dict[str, str]] = []
    seen: Set[Tuple[str, str, str, str]] = set()
    for item in payload["results"]:
        if not isinstance(item, dict):
            continue
        row = {
            "nom": str(item.get("nom") or "").strip(),
            "prenom": str(item.get("prenom") or "").strip(),
            "nub": _normalize_cnaps_nub(item.get("nub")),
            "typeActivite": str(item.get("typeActivite") or "").strip(),
            "agrementStatutEs": str(item.get("agrementStatutEs") or "").strip().upper(),
            "dateFinValidite": str(item.get("dateFinValidite") or "").strip(),
            "recepisse": item.get("recepisse"),
        }
        key = (row["nub"], row["typeActivite"], row["dateFinValidite"], row["agrementStatutEs"])
        if key in seen:
            continue
        seen.add(key)
        rows.append(row)
    return rows


def build_cnaps_public_annuaire_snapshot(rows: List[Dict[str, str]], nub: str, nom: str = "") -> Dict[str, Any]:
    normalized_nub = _normalize_cnaps_nub(nub)
    normalized_nom = _normalize_cnaps_name(nom)
    matched_rows = []
    seen: Set[Tuple[str, str, str, str]] = set()
    for row in rows:
        if _normalize_cnaps_nub(row.get("nub")) != normalized_nub:
            continue
        if normalized_nom and _normalize_cnaps_name(row.get("nom")) != normalized_nom:
            continue
        key = (_normalize_cnaps_nub(row.get("nub")), str(row.get("typeActivite") or ""), str(row.get("dateFinValidite") or ""), str(row.get("agrementStatutEs") or ""))
        if key in seen:
            continue
        seen.add(key)
        matched_rows.append(row)
    titles = []
    for row in matched_rows:
        label = str(row.get("typeActivite") or "").strip()
        status = str(row.get("agrementStatutEs") or "").strip().upper()
        code = _cnaps_activity_code(label)
        titles.append({
            "code": code,
            "label": label,
            "activity": label,
            "status": status,
            "validity": status,
            "display_status": _cnaps_display_status(code, status),
            "date_fin_validite": str(row.get("dateFinValidite") or "").strip(),
            "valid_until": str(row.get("dateFinValidite") or "").strip(),
        })
    titles.sort(key=lambda t: (CNAPS_TITLE_ORDER.index(t["code"]) if t["code"] in CNAPS_TITLE_ORDER else 999, t["label"], t["date_fin_validite"]))
    active_title_objects = [t for t in titles if t["status"] == "ACTIF"]
    active_title_labels = [t["display_status"] for t in active_title_objects]
    app.logger.info(
        'CNAPS check rows=%s matched=%s active_titles=%s nub_masked=%s',
        len(rows), len(matched_rows), active_title_labels, _mask_cnaps_nub(normalized_nub),
    )
    message = None if titles else "Aucun titre CNAPS trouvé"
    return {
        "status": "ok",
        "matched": bool(matched_rows),
        "checked_at": _now_iso(),
        "check_status": "success",
        "nub": normalized_nub,
        "titles": titles,
        "active_titles": active_title_objects,
        "cnaps_active_titles": active_title_labels,
        "results": matched_rows,
        "message": message,
        "error": None,
    }


def _mask_cnaps_nub(nub: str) -> str:
    value = _normalize_cnaps_nub(nub)
    return "***" + value[-3:] if value else ""


def _cnaps_public_error_snapshot(nub: str, error: str, status_code: Optional[int] = None, previous_success: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    checked_at = _now_iso()
    snapshot = {
        "status": "error",
        "matched": False,
        "checked_at": checked_at,
        "check_status": "error",
        "nub": _normalize_cnaps_nub(nub),
        "titles": [],
        "active_titles": [],
        "cnaps_active_titles": [],
        "results": [],
        "message": "Vérification CNAPS impossible",
        "error": (error or "CNAPS error")[:120],
        "http_status": status_code,
        "last_attempt": {"checked_at": checked_at, "status": "error", "error": (error or "CNAPS error")[:120]},
    }
    if previous_success:
        snapshot["last_successful_check"] = previous_success
    return snapshot


def _validate_cnaps_json_response(response: Any) -> Any:
    status_code = getattr(response, "status_code", None)
    content_type = (getattr(response, "headers", {}) or {}).get("Content-Type", "")
    final_url = getattr(response, "url", "") or CNAPS_PUBLIC_ANNUAIRE_ENDPOINT
    app.logger.info(
        "CNAPS outbound method=POST url=%s status=%s content_type=%s final_url=%s",
        CNAPS_PUBLIC_ANNUAIRE_ENDPOINT, status_code, content_type or "unknown", final_url,
    )
    if status_code != 200:
        raise RuntimeError(f"CNAPS HTTP {status_code}")
    if "json" not in (content_type or "").lower():
        text = (getattr(response, "text", "") or "")[:200].lstrip().lower()
        if text.startswith("<") or "<!doctype html" in text or "<html" in text:
            raise RuntimeError("CNAPS unexpected HTML response")
        if content_type:
            raise RuntimeError(f"CNAPS unexpected Content-Type {content_type}")
    try:
        data = response.json()
    except Exception as exc:
        raise RuntimeError("CNAPS invalid JSON") from exc
    if not isinstance(data, dict):
        raise RuntimeError("CNAPS unexpected JSON structure")
    if "results" not in data or not isinstance(data.get("results"), list):
        raise RuntimeError("CNAPS missing results")
    return data


def fetch_cnaps_public_annuaire(nom: str, nub: str, previous_success: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    endpoint = (CNAPS_PUBLIC_ANNUAIRE_ENDPOINT or "").strip()
    normalized_nom = " ".join((nom or "").strip().split()).upper()
    normalized_nub = _normalize_cnaps_nub(nub)
    if not endpoint or not normalized_nom or not normalized_nub:
        return _cnaps_public_error_snapshot(normalized_nub, "missing_cnaps_query", previous_success=previous_success)
    headers = {
        "Accept": "application/json",
        "Content-Type": "application/json",
        "Referer": CNAPS_PUBLIC_ANNUAIRE_PAGE_URL,
        "Origin": "https://espace-consultation.cnaps.interieur.gouv.fr",
        "User-Agent": "Mozilla/5.0 (compatible; gestionstagiaires/1.0; +https://gestionstagiaires-r5no.onrender.com)",
    }
    rows: List[Dict[str, str]] = []
    total_elements = 0
    try:
        session = requests.Session()
        total_pages = 1
        page = 0
        while page < min(total_pages, CNAPS_PUBLIC_ANNUAIRE_MAX_PAGES):
            payload = _build_cnaps_public_annuaire_payload(normalized_nom, normalized_nub, page)
            response = session.post(endpoint, json=payload, headers=headers, timeout=(3, 10), allow_redirects=True)
            data = _validate_cnaps_json_response(response)
            rows.extend(_extract_cnaps_public_annuaire_results(data))
            total_elements = int(data.get("totalElements") or total_elements or 0)
            if page == 0:
                total_pages = max(1, int(data.get("totalPages") or 1))
            page += 1
        snapshot = build_cnaps_public_annuaire_snapshot(rows, normalized_nub, normalized_nom)
        snapshot["total_elements"] = total_elements
        snapshot["last_successful_check"] = {"checked_at": snapshot["checked_at"], "active_titles": snapshot["active_titles"]}
        snapshot["last_attempt"] = {"checked_at": snapshot["checked_at"], "status": "success", "error": None}
        return snapshot
    except Exception as exc:
        app.logger.warning(
            "CNAPS check rows=%s matched=0 active_titles=[] status=error nub_masked=%s error=%s",
            len(rows), _mask_cnaps_nub(normalized_nub), exc,
        )
        status_code = None
        m = re.search(r"CNAPS HTTP (\d+)", str(exc))
        if m:
            status_code = int(m.group(1))
        return _cnaps_public_error_snapshot(normalized_nub, str(exc), status_code=status_code, previous_success=previous_success)

def fetch_cnaps_lookup_by_name(nom: str, prenom: str) -> Optional[Dict[str, Any]]:
    if not CNAPS_LOOKUP_ENDPOINT:
        return None

    def _normalize_cnaps_name(value: str) -> str:
        raw = (value or "").strip()
        if not raw:
            return ""
        cleaned = unicodedata.normalize("NFD", raw)
        cleaned = "".join(ch for ch in cleaned if unicodedata.category(ch) != "Mn")
        cleaned = " ".join(cleaned.replace("-", " ").split())
        return cleaned.upper()

    nom = _normalize_cnaps_name(nom)
    prenom = _normalize_cnaps_name(prenom)
    if not nom or not prenom:
        return None

    try:
        r = requests.get(CNAPS_LOOKUP_ENDPOINT, params={"nom": nom, "prenom": prenom}, timeout=10)
        if r.status_code != 200:
            return None
        data = r.json()
        payload = data if isinstance(data, dict) else {}
        nested_payload = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        status = (
            payload.get("statut_cnaps")
            or payload.get("status")
            or payload.get("statut")
            or payload.get("cnaps_status")
            or nested_payload.get("statut_cnaps")
            or nested_payload.get("status")
            or nested_payload.get("statut")
            or nested_payload.get("cnaps_status")
        )
        return {
            "status": str(status or "").strip() or "INCONNU",
            "statut_cnaps_history": _normalize_cnaps_remote_history(
                payload.get("statut_cnaps_history") or nested_payload.get("statut_cnaps_history")
            ),
        }
    except Exception:
        return None


def fetch_cnaps_status_by_name(nom: str, prenom: str) -> Optional[str]:
    lookup = fetch_cnaps_lookup_by_name(nom, prenom)
    if not lookup:
        return None
    return lookup.get("status")


def fetch_hebergement_status(
    email: str,
    *,
    last_name: str = "",
    first_name: str = "",
    session_name: str = "",
    session_date_start: str = "",
    session_date_end: str = "",
) -> Optional[str]:
    if not HEBERGEMENT_STATUS_ENDPOINT:
        return None

    def _collapse_matching_spaces(value: str) -> str:
        return " ".join((value or "").strip().split())

    def _normalize_matching_text(value: Any) -> str:
        raw = _collapse_matching_spaces(str(value or "")).lower()
        cleaned = unicodedata.normalize("NFKD", raw)
        cleaned = "".join(ch for ch in cleaned if not unicodedata.combining(ch))
        return cleaned

    def _normalize_matching_token(value: Any) -> str:
        text = _normalize_matching_text(value)
        return "".join(ch for ch in text if ch.isalnum())

    def _normalize_matching_email(value: Any) -> str:
        return _normalize_matching_text(value)

    def _extract_normalized_dates(value: Any) -> Set[str]:
        raw = _normalize_matching_text(value)
        if not raw:
            return set()

        out: Set[str] = set()
        for year, month, day in re.findall(r"(\d{4})-(\d{2})-(\d{2})", raw):
            out.add(f"{day}/{month}/{year}")
            out.add(f"{day} {month} {year}")

        for day, month, year in re.findall(r"(\d{1,2})/(\d{1,2})/(\d{4})", raw):
            out.add(f"{int(day):02d}/{int(month):02d}/{year}")
            out.add(f"{int(day)} {int(month)} {year}")

        months = {
            "janvier": "01",
            "fevrier": "02",
            "mars": "03",
            "avril": "04",
            "mai": "05",
            "juin": "06",
            "juillet": "07",
            "aout": "08",
            "septembre": "09",
            "octobre": "10",
            "novembre": "11",
            "decembre": "12",
        }
        month_pattern = "|".join(months.keys())
        for day, month_name, year in re.findall(rf"(\d{{1,2}})\s+({month_pattern})\s+(\d{{4}})", raw):
            month = months[month_name]
            out.add(f"{int(day):02d}/{month}/{year}")
            out.add(f"{int(day)} {int(month)} {year}")

        return {item for item in out if item}

    email = _normalize_matching_email(email)
    last_name = normalize_last_name(last_name or "")
    first_name = normalize_first_name(first_name or "")
    session_name = _collapse_matching_spaces(session_name or "")
    session_date_start = (session_date_start or "").strip()
    session_date_end = (session_date_end or "").strip()

    if not any((email, last_name, first_name, session_name, session_date_start, session_date_end)):
        return None

    def _is_truthy(v) -> bool:
        if v is True:
            return True
        if isinstance(v, (int, float)) and v == 1:
            return True
        if isinstance(v, str) and v.strip().lower() in ("true", "1", "yes", "y", "ok", "oui"):
            return True
        return False

    def _format_fr_date_long(date_str: str, *, include_year: bool = True) -> str:
        try:
            dt = datetime.datetime.strptime(date_str, "%Y-%m-%d")
        except ValueError:
            return ""
        months = {
            1: "janvier",
            2: "février",
            3: "mars",
            4: "avril",
            5: "mai",
            6: "juin",
            7: "juillet",
            8: "août",
            9: "septembre",
            10: "octobre",
            11: "novembre",
            12: "décembre",
        }
        day = str(dt.day)
        month = months.get(dt.month, "")
        if include_year:
            return f"{day} {month} {dt.year}".strip()
        return f"{day} {month}".strip()

    def _session_candidates() -> set[str]:
        candidates = set()
        if session_name:
            candidates.add(_normalize_matching_token(session_name))
        if session_date_start and session_date_end:
            start_dt = ""
            end_dt = ""
            try:
                start_dt = datetime.datetime.strptime(session_date_start, "%Y-%m-%d").strftime("%d/%m/%Y")
                end_dt = datetime.datetime.strptime(session_date_end, "%Y-%m-%d").strftime("%d/%m/%Y")
            except ValueError:
                pass
            if start_dt and end_dt:
                candidates.add(_normalize_matching_token(f"{start_dt} {end_dt}"))
                candidates.add(_normalize_matching_token(f"du {start_dt} au {end_dt}"))

            long_start = _format_fr_date_long(session_date_start, include_year=False)
            long_end = _format_fr_date_long(session_date_end, include_year=True)
            if long_start and long_end:
                candidates.add(_normalize_matching_token(f"du {long_start} au {long_end}"))
                candidates.add(_normalize_matching_token(f"{long_start} {long_end}"))

        return {candidate for candidate in candidates if candidate}

    def _preferred_session_label() -> str:
        if session_name:
            return session_name
        if session_date_start and session_date_end:
            long_start = _format_fr_date_long(session_date_start, include_year=False)
            long_end = _format_fr_date_long(session_date_end, include_year=True)
            if long_start and long_end:
                return f"Du {long_start} au {long_end}"
            try:
                start_dt = datetime.datetime.strptime(session_date_start, "%Y-%m-%d").strftime("%d/%m/%Y")
                end_dt = datetime.datetime.strptime(session_date_end, "%Y-%m-%d").strftime("%d/%m/%Y")
                return f"Du {start_dt} au {end_dt}"
            except ValueError:
                return ""
        return ""

    session_candidates = _session_candidates()
    expected_last_name = _normalize_matching_token(last_name)
    expected_first_name = _normalize_matching_token(first_name)
    expected_session_dates = _extract_normalized_dates(
        " ".join(part for part in (session_name, session_date_start, session_date_end) if part)
    )
    debug_enabled = (
        expected_last_name == _normalize_matching_token("Debouvry")
        and expected_first_name == _normalize_matching_token("Charles")
    )

    def _debug_log(message: str, **kwargs: Any) -> None:
        if not debug_enabled:
            return
        app.logger.info("[HEBERGEMENT][DEBUG][Charles Debouvry] %s | %s", message, kwargs)

    def _is_reserved_value(value: Any) -> bool:
        if _is_truthy(value):
            return True
        if not isinstance(value, str):
            return False
        return _normalize_matching_text(value) in (
            "reserved",
            "reserve",
            "reserver",
            "reservee",
            "reservee ",
            "ok",
            "oui",
        )

    def _looks_like_hosting_record(payload: Any) -> bool:
        if not isinstance(payload, dict):
            return False
        record_keys = {
            "nom",
            "prenom",
            "email",
            "session",
            "paiement",
            "date_paiement",
            "mode",
            "mode_paiement",
            "cle",
            "clé",
            "etat_cle",
            "état clé",
        }
        return any(k in payload for k in record_keys)

    def _record_matches(payload: Dict[str, Any]) -> bool:
        if not isinstance(payload, dict):
            return False

        record_email = _normalize_matching_email(payload.get("email") or payload.get("mail") or "")
        record_last_name = _normalize_matching_token(payload.get("nom") or payload.get("last_name") or "")
        record_first_name = _normalize_matching_token(payload.get("prenom") or payload.get("first_name") or "")
        record_session_raw = (
            payload.get("session")
            or payload.get("session_name")
            or payload.get("session_label")
            or payload.get("libelle_session")
            or payload.get("formation")
            or ""
        )
        record_session = _normalize_matching_token(record_session_raw)
        record_session_dates = _extract_normalized_dates(
            " ".join(
                str(value or "")
                for value in (
                    record_session_raw,
                    payload.get("date_start"),
                    payload.get("date_end"),
                    payload.get("session_date_start"),
                    payload.get("session_date_end"),
                    payload.get("start_date"),
                    payload.get("end_date"),
                )
            )
        )

        if email and record_email and record_email == email:
            _debug_log(
                "match via email normalisé",
                trainee_email=email,
                record_email=record_email,
                trainee_last_name=expected_last_name,
                trainee_first_name=expected_first_name,
                trainee_session_candidates=sorted(session_candidates),
                trainee_session_dates=sorted(expected_session_dates),
                record_last_name=record_last_name,
                record_first_name=record_first_name,
                record_session=record_session,
                record_session_dates=sorted(record_session_dates),
            )
            return True

        name_matches = (
            expected_last_name
            and expected_first_name
            and record_last_name == expected_last_name
            and record_first_name == expected_first_name
        )

        session_match = bool(
            session_candidates
            and record_session
            and record_session in session_candidates
        )
        session_dates_match = bool(expected_session_dates and record_session_dates and expected_session_dates == record_session_dates)

        if name_matches and (session_match or session_dates_match):
            _debug_log(
                "match via fallback nom+prenom+session normalisés",
                trainee_email=email,
                record_email=record_email,
                trainee_last_name=expected_last_name,
                trainee_first_name=expected_first_name,
                trainee_session_candidates=sorted(session_candidates),
                trainee_session_dates=sorted(expected_session_dates),
                record_last_name=record_last_name,
                record_first_name=record_first_name,
                record_session=record_session,
                record_session_dates=sorted(record_session_dates),
                session_match=session_match,
                session_dates_match=session_dates_match,
            )
            return True

        if debug_enabled and name_matches and not (session_match or session_dates_match):
            _debug_log(
                "échec fallback: session non concordante",
                trainee_email=email,
                record_email=record_email,
                trainee_last_name=expected_last_name,
                trainee_first_name=expected_first_name,
                trainee_session_candidates=sorted(session_candidates),
                trainee_session_dates=sorted(expected_session_dates),
                record_last_name=record_last_name,
                record_first_name=record_first_name,
                record_session=record_session,
                record_session_dates=sorted(record_session_dates),
            )
        elif debug_enabled and (record_last_name or record_first_name or record_email):
            _debug_log(
                "échec matching: identité non concordante",
                trainee_email=email,
                record_email=record_email,
                trainee_last_name=expected_last_name,
                trainee_first_name=expected_first_name,
                trainee_session_candidates=sorted(session_candidates),
                trainee_session_dates=sorted(expected_session_dates),
                record_last_name=record_last_name,
                record_first_name=record_first_name,
                record_session=record_session,
                record_session_dates=sorted(record_session_dates),
            )

        return False

    def _payload_contains_reservation(payload: Any) -> bool:
        if isinstance(payload, list):
            return any(_payload_contains_reservation(item) for item in payload)

        if not isinstance(payload, dict):
            return False

        for key in ("reserved", "is_reserved", "booking_reserved", "hebergement_reserved"):
            if _is_reserved_value(payload.get(key)):
                return True

        for key in (
            "status",
            "hosting_status",
            "hebergement",
            "value",
            "result",
            "reservation_status",
            "booking_status",
            "statut",
        ):
            if _is_reserved_value(payload.get(key)):
                return True

        if _looks_like_hosting_record(payload) and _record_matches(payload):
            return True

        return any(_payload_contains_reservation(value) for value in payload.values())

    for attempt in range(2):
        try:
            if email:
                params = {"email": email}
            elif last_name and first_name:
                params = {"nom": last_name, "prenom": first_name}
            else:
                app.logger.warning("[HEBERGEMENT] lookup ignoré: paramètres insuffisants")
                _debug_log(
                    "lookup annulé: aucun paramètre valide",
                    trainee_email=email,
                    trainee_last_name=expected_last_name,
                    trainee_first_name=expected_first_name,
                )
                return None

            final_url = requests.Request("GET", HEBERGEMENT_STATUS_ENDPOINT, params=params).prepare().url or HEBERGEMENT_STATUS_ENDPOINT
            app.logger.info("[HEBERGEMENT] final_url=%s", final_url)
            _debug_log("url finale appelée", final_url=final_url)

            r = requests.get(
                final_url,
                timeout=8
            )

            app.logger.info("[HEBERGEMENT] status=%s email=%s", r.status_code, email)
            if r.status_code != 200:
                app.logger.warning("[HEBERGEMENT] body=%s", r.text[:400])
                time.sleep(0.3)
                continue

            data = r.json()
            app.logger.info("[HEBERGEMENT] json=%s", data)
            _debug_log(
                "réponse brute plateforme hébergement",
                raw_response=data,
            )
            _debug_log(
                "requête de lookup envoyée",
                params=params,
                final_url=final_url,
                trainee_email=email,
                trainee_last_name=expected_last_name,
                trainee_first_name=expected_first_name,
                trainee_session_candidates=sorted(session_candidates),
                trainee_session_dates=sorted(expected_session_dates),
            )

            if isinstance(data, dict) and data.get("reserved") is True:
                _debug_log("réservation détectée via reserved=true", final_url=final_url)
                return "reserved"

            if _payload_contains_reservation(data):
                _debug_log("réservation détectée côté hébergement", payload_type=type(data).__name__)
                return "reserved"

            _debug_log("aucune réservation retenue", reason="aucun record matchant ou aucun indicateur de réservation")
            # si rien de concluant -> on ne touche pas l'existant
            return None

        except Exception as e:
            app.logger.warning("[HEBERGEMENT] exception=%r", e)
            time.sleep(0.3)

    return None


def _refresh_trainee_hebergement_status(
    session_item: Dict[str, Any],
    trainee: Dict[str, Any],
) -> bool:
    """Refresh one A3P trainee's hosting status without ever downgrading it."""
    training_type = str(_session_get(session_item, "training_type", "") or "").strip().upper()
    if training_type != "A3P":
        return False

    current_status = str(trainee.get("hosting_status") or "unknown").strip().lower() or "unknown"
    if current_status == "reserved":
        trainee["hosting_status"] = "reserved"
        return False

    remote_status = fetch_hebergement_status(
        str(trainee.get("email") or "").strip().lower(),
        last_name=normalize_last_name(trainee.get("last_name") or ""),
        first_name=normalize_first_name(trainee.get("first_name") or ""),
        session_name=_session_get(session_item, "name", ""),
        session_date_start=_session_get(session_item, "date_start", ""),
        session_date_end=_session_get(session_item, "date_end", ""),
    )
    if remote_status != "reserved":
        trainee["hosting_status"] = current_status
        return False

    trainee["hosting_status"] = "reserved"
    return True


def _is_charles_debouvry_debug_target(*, email: str = "", last_name: str = "", first_name: str = "") -> bool:
    normalized_email = (email or "").strip().lower()
    normalized_last_name = _normalized_token(normalize_last_name(last_name or ""))
    normalized_first_name = _normalized_token(normalize_first_name(first_name or ""))
    return (
        normalized_email == "charles.debouvry@gmail.com"
        or (
            normalized_last_name == _normalized_token("DEBOUVRY")
            and normalized_first_name == _normalized_token("Charles")
        )
    )


def _log_charles_hebergement_trace(scope: str, message: str, **kwargs: Any) -> None:
    if not _is_charles_debouvry_debug_target(
        email=str(kwargs.get("email") or ""),
        last_name=str(kwargs.get("last_name") or ""),
        first_name=str(kwargs.get("first_name") or ""),
    ):
        return
    app.logger.info("[HEBERGEMENT][TRACE][Charles Debouvry][%s] %s | %s", scope, message, kwargs)




