@app.post('/scotia/sessions/<session_id>/stagiaires/<trainee_id>/attestation/upload')
@scotia_login_required
def scotia_upload_attestation(session_id: str, trainee_id: str):
    data = load_data()
    s, trainees, t = _find_session_trainee(data, session_id, trainee_id)
    if not s or not t:
        abort(404)

    f = request.files.get('file')
    if not f or not f.filename:
        return redirect(url_for('scotia_dashboard'))

    try:
        stored = _store_file(session_id, trainee_id, 'deliverables', f)
    except Exception:
        return redirect(url_for('scotia_dashboard'))

    token = _tokenize_path(stored)
    previous_status = vae_status_view(t.get("vae_status") or t.get("vae_status_label"))["key"]
    previous_attestation_token = str(((t.get("deliverables") or {}).get("attestation_recevabilite") or "")).strip()

    t.setdefault('deliverables', {})
    t['deliverables']['attestation_recevabilite'] = token
    if not isinstance(t.get("vae_action_dates"), dict):
        t["vae_action_dates"] = {}
    t["vae_action_dates"]["attestation_recevabilite_imported_at"] = fr_date(datetime.datetime.utcnow().strftime("%Y-%m-%d"))
    if not t["vae_action_dates"].get("livret_1_validated"):
        t["vae_action_dates"]["livret_1_validated"] = fr_date(datetime.datetime.utcnow().strftime("%Y-%m-%d"))

    livret1_validated_view = vae_status_view("livret_1_validated")
    t["vae_status"] = livret1_validated_view["key"]
    t["vae_status_label"] = livret1_validated_view["label"]
    t['updated_at'] = _now_iso()

    s['trainees'] = trainees
    s.pop('stagiaires', None)
    save_data(data)

    should_notify = previous_status != livret1_validated_view["key"] or (not previous_attestation_token and bool(token))
    if should_notify:
        _notify_vae_status_change(t, livret1_validated_view["key"])

    return redirect(url_for('scotia_dashboard'))


@app.post('/scotia/sessions/<session_id>/stagiaires/<trainee_id>/livret2/upload')
@scotia_login_required
def scotia_upload_livret2(session_id: str, trainee_id: str):
    data = load_data()
    s, trainees, t = _find_session_trainee(data, session_id, trainee_id)
    if not s or not t:
        abort(404)

    if _scotia_effective_status(t) != "recevable":
        return redirect(url_for('scotia_dashboard'))

    f = request.files.get('file')
    if not f or not f.filename:
        return redirect(url_for('scotia_dashboard'))

    ext = os.path.splitext(f.filename)[1].lower()
    if ext != ".pdf":
        return redirect(url_for('scotia_dashboard'))

    try:
        stored = _store_file(session_id, trainee_id, 'deliverables', f)
    except Exception:
        return redirect(url_for('scotia_dashboard'))

    token = _tokenize_path(stored)
    t.setdefault('deliverables', {})
    t['deliverables']['livret_2'] = token
    if not (t.get("scotia_status") or "").strip():
        t["scotia_status"] = "recevable"

    if not isinstance(t.get("vae_action_dates"), dict):
        t["vae_action_dates"] = {}
    today_fr = fr_date(datetime.datetime.utcnow().strftime("%Y-%m-%d"))
    t["vae_action_dates"]["livret_2_imported_at"] = today_fr
    if not t["vae_action_dates"].get("livret_2_received"):
        t["vae_action_dates"]["livret_2_received"] = today_fr

    t['updated_at'] = _now_iso()

    s['trainees'] = trainees
    s.pop('stagiaires', None)
    save_data(data)

    trainee_display_name = _format_trainee_name(t.get("first_name", ""), t.get("last_name", ""))
    subject = "Nouveau Livret 2 déposé (SCOTIA)"
    html = mail_layout(f"""
    <h2 style="margin:0 0 12px 0;color:#0f172a;">📥 Nouveau Livret 2 déposé</h2>
    <p>Un Livret 2 vient d'être déposé depuis l'espace SCOTIA.</p>
    <p><strong>Stagiaire :</strong> {trainee_display_name or "—"}</p>
    <p><strong>Email :</strong> {(t.get("email") or "").strip() or "—"}</p>
    <p><strong>Téléphone :</strong> {(t.get("phone") or "").strip() or "—"}</p>
    <p><strong>Session :</strong> {s.get("name") or s.get("title") or session_id}</p>
    <p><strong>Date :</strong> {today_fr}</p>
    """)
    # L'envoi Brevo peut prendre plusieurs secondes (timeout réseau, API lente).
    # Le fichier est déjà sauvegardé juste au-dessus : on déclenche donc l'alerte
    # en arrière-plan afin que le bouton "Importer Livret 2" rende la main
    # immédiatement et que l'utilisateur voie l'import sans rester bloqué.
    threading.Thread(
        target=brevo_send_email,
        args=("scotiaformation@gmail.com", subject, html),
        kwargs={"cc_emails": ["clement@integraleacademy.com"]},
        daemon=True,
    ).start()
    return redirect(url_for('scotia_dashboard'))


@app.post('/scotia/sessions/<session_id>/stagiaires/<trainee_id>/livret2/reset')
@scotia_login_required
def scotia_reset_livret2(session_id: str, trainee_id: str):
    data = load_data()
    s, trainees, t = _find_session_trainee(data, session_id, trainee_id)
    if not s or not t:
        abort(404)

    deliverables = t.get('deliverables')
    if not isinstance(deliverables, dict):
        deliverables = {}
        t['deliverables'] = deliverables

    livret_2_token = (deliverables.get('livret_2') or '').strip()
    if livret_2_token:
        try:
            _safe_remove_file(_detokenize_path(livret_2_token))
        except Exception:
            pass

    deliverables.pop('livret_2', None)
    t['scotia_livret_2_status'] = ''
    t['scotia_livret_2_processed_at'] = ''

    action_dates = t.get('vae_action_dates')
    if isinstance(action_dates, dict):
        action_dates.pop('livret_2_imported_at', None)
        action_dates.pop('livret_2_received', None)

    t['updated_at'] = _now_iso()

    s['trainees'] = trainees
    s.pop('stagiaires', None)
    save_data(data)
    return redirect(url_for('scotia_dashboard'))


