@app.get("/admin/sessions/suivi-cnaps")
@admin_login_required
def admin_cnaps_tracking():
    requests_rows, fetch_error = fetch_cnapsv3_tracking_requests()
    data = load_data()
    requests_rows = enrich_cnaps_tracking_rows_with_enrollment(requests_rows, data)
    annuaire_statuses = data.get("cnaps_public_annuaire_statuses") or {}
    today = datetime.date.today()
    for row in requests_rows:
        nub = re.sub(r"\D+", "", str(row.get("nub") or ""))[-7:]
        status = annuaire_statuses.get(
            _cnaps_public_annuaire_status_key(str(row.get("last_name") or ""), nub)
        ) if isinstance(annuaire_statuses, dict) else None
        since = _daily_recap_date(status.get("status_since") or status.get("checked_at")) if isinstance(status, dict) else None
        row["taj_suspected"] = bool(
            status is not None and not status.get("known") and since and (today - since).days >= 10
        )
    requests_rows = _annotate_cnaps_tracking_status_changes(requests_rows, data)
    enrolled_count = sum(1 for row in requests_rows if row.get("is_enrolled"))
    # The dashboard badge and this tile both represent outstanding changes that
    # can actually be reviewed from the tracking list.  Notifications for a
    # dossier that is no longer returned by CNAPSV3 must not inflate the count.
    status_change_count = sum(
        1
        for row in requests_rows
        if row.get("status_change_notified") and not row.get("status_change_reviewed")
    )
    response = make_response(render_template(
        "admin_cnaps_tracking.html",
        requests_rows=requests_rows,
        enrolled_count=enrolled_count,
        status_change_count=status_change_count,
        fetch_error=fetch_error,
    ))
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    response.headers["Pragma"] = "no-cache"
    return response


@app.post("/api/admin/cnaps-status-changes/toggle-reviewed")
@admin_login_required
@admin_write_required
def api_admin_cnaps_status_change_toggle_reviewed():
    payload = request.get_json(silent=True) or {}
    last_name = str(payload.get("last_name") or "").strip()
    nub = str(payload.get("nub") or "").strip()
    key = _cnaps_status_change_key(last_name, nub)
    if not last_name or not re.sub(r"\D+", "", nub) or key == "|":
        return jsonify({"ok": False, "error": "missing_identity"}), 400

    data = load_data()
    notifications = data.get("cnaps_status_change_notifications")
    notification = notifications.get(key) if isinstance(notifications, dict) else None
    if not isinstance(notification, dict):
        return jsonify({"ok": False, "error": "notification_not_found"}), 404

    reviewed = not bool(notification.get("reviewed_at"))
    if reviewed:
        notification["reviewed_at"] = _now_iso()
        notification["reviewed_reason"] = "manual_seen"
    else:
        notification.pop("reviewed_at", None)
        notification.pop("reviewed_reason", None)
    save_data(data)
    return jsonify({
        "ok": True,
        "reviewed": reviewed,
        "pending_status_changes_count": _cnaps_pending_status_change_count(data),
    })



@app.post("/api/admin/cnaps-tracking/delete")
@admin_login_required
@admin_write_required
def api_admin_cnaps_tracking_delete():
    payload = request.get_json(silent=True) or {}
    delete_key = _cnaps_tracking_delete_key(payload.get("last_name"), payload.get("first_name"), payload.get("nub"))
    if not delete_key.replace("|", "").strip():
        return jsonify({"ok": False, "error": "missing_identity"}), 400
    data = load_data()
    deleted_keys = data.setdefault("cnaps_tracking_deleted_keys", [])
    if not isinstance(deleted_keys, list):
        deleted_keys = []
        data["cnaps_tracking_deleted_keys"] = deleted_keys
    if delete_key not in deleted_keys:
        deleted_keys.append(delete_key)
        _append_activity_log(data, "cnaps_tracking_row_deleted", "cnaps_tracking", delete_key, details={
            "last_name": str(payload.get("last_name") or ""),
            "first_name": str(payload.get("first_name") or ""),
            "nub": str(payload.get("nub") or ""),
        })
        save_data(data)
    return jsonify({"ok": True, "deleted": True})


@app.post("/api/admin/cnaps-tracking/nub")
@admin_login_required
@admin_write_required
def api_admin_cnaps_tracking_nub():
    """Persist a manually supplied NUB for a CNAPS tracking row."""
    payload = request.get_json(silent=True) or {}
    last_name = str(payload.get("last_name") or "").strip()
    first_name = str(payload.get("first_name") or "").strip()
    nub = re.sub(r"\D+", "", str(payload.get("nub") or ""))
    if not last_name or not first_name:
        return jsonify({"ok": False, "error": "missing_identity"}), 400
    if len(nub) != 7:
        return jsonify({"ok": False, "error": "invalid_nub", "message": "Le NUB doit comporter 7 chiffres."}), 400

    data = load_data()
    manual_nubs = data.setdefault("cnaps_tracking_manual_nubs", {})
    if not isinstance(manual_nubs, dict):
        manual_nubs = {}
        data["cnaps_tracking_manual_nubs"] = manual_nubs
    manual_nubs[_cnaps_tracking_manual_nub_key(last_name, first_name)] = nub
    _append_activity_log(data, "cnaps_tracking_nub_updated", "cnaps_tracking", nub, details={
        "last_name": last_name,
        "first_name": first_name,
    })
    save_data(data)
    return jsonify({"ok": True, "nub": nub})



def _cnaps_tracking_normalize_key_part(value: Any) -> str:
    text = unicodedata.normalize("NFKD", str(value or ""))
    text = "".join(ch for ch in text if not unicodedata.combining(ch))
    return re.sub(r"[^A-Z0-9]+", " ", text.upper()).strip()


def _cnaps_tracking_match_key(last_name: Any, first_name: Any) -> Tuple[str, str]:
    return _cnaps_tracking_normalize_key_part(last_name), _cnaps_tracking_normalize_key_part(first_name)


def _cnaps_tracking_delete_key(last_name: Any, first_name: Any, nub: Any) -> str:
    return "|".join((
        _cnaps_tracking_normalize_key_part(last_name),
        _cnaps_tracking_normalize_key_part(first_name),
        _cnaps_tracking_normalize_key_part(nub),
    ))


def _cnaps_tracking_manual_nub_key(last_name: Any, first_name: Any) -> str:
    return "|".join(_cnaps_tracking_match_key(last_name, first_name))


def _cnaps_tracking_manual_nubs(data: Dict[str, Any]) -> Dict[str, str]:
    raw = data.get("cnaps_tracking_manual_nubs")
    if not isinstance(raw, dict):
        return {}
    return {
        str(key): re.sub(r"\D+", "", str(nub))
        for key, nub in raw.items()
        if len(re.sub(r"\D+", "", str(nub))) == 7
    }


def _cnaps_tracking_deleted_keys(data: Dict[str, Any]) -> Set[str]:
    raw = data.get("cnaps_tracking_deleted_keys")
    return {str(key) for key in raw if str(key).strip()} if isinstance(raw, list) else set()


def enrich_cnaps_tracking_rows_with_enrollment(rows: List[Dict[str, Any]], data: Dict[str, Any]) -> List[Dict[str, Any]]:
    deleted_keys = _cnaps_tracking_deleted_keys(data)
    manual_nubs = _cnaps_tracking_manual_nubs(data)
    enrolled_by_name: Dict[Tuple[str, str], Dict[str, str]] = {}
    for sess in data.get("sessions", []) or []:
        if bool(sess.get("archived")) or _is_wedof_leads_session(sess):
            continue
        session_name = _session_get(sess, "name", "") or str(sess.get("id") or "")
        training_type = _session_get(sess, "training_type", "")
        for trainee in _session_trainees_list(sess):
            key = _cnaps_tracking_match_key(trainee.get("last_name"), trainee.get("first_name"))
            if not all(key) or key in enrolled_by_name:
                continue
            enrolled_by_name[key] = {
                "session_id": str(sess.get("id") or ""),
                "session_name": session_name,
                "training_type": training_type,
                "date_start": str(_session_get(sess, "date_start", "") or ""),
                "date_end": str(_session_get(sess, "date_end", "") or ""),
                "trainee_id": str(trainee.get("id") or ""),
            }

    enriched: List[Dict[str, Any]] = []
    for row in rows or []:
        item = dict(row)
        manual_nub = manual_nubs.get(_cnaps_tracking_manual_nub_key(item.get("last_name"), item.get("first_name")))
        if manual_nub:
            item["nub"] = manual_nub
        if _cnaps_tracking_delete_key(item.get("last_name"), item.get("first_name"), item.get("nub")) in deleted_keys:
            continue
        match = enrolled_by_name.get(_cnaps_tracking_match_key(item.get("last_name"), item.get("first_name")))
        item["is_enrolled"] = bool(match)
        item["enrollment"] = match or {}
        enriched.append(item)
    return enriched




def _cnaps_tracking_nub_by_name(rows: List[Dict[str, Any]]) -> Dict[Tuple[str, str], str]:
    nub_by_name: Dict[Tuple[str, str], str] = {}
    for row in rows or []:
        key = _cnaps_tracking_match_key(row.get("last_name"), row.get("first_name"))
        nub = re.sub(r"\D+", "", str(row.get("nub") or ""))
        if not all(key) or not nub or key in nub_by_name:
            continue
        nub_by_name[key] = nub[-7:] if len(nub) >= 7 else nub
    return nub_by_name


def _hydrate_missing_trainee_nubs_from_cnaps_tracking(trainees: List[Dict[str, Any]]) -> bool:
    candidates = [
        trainee for trainee in trainees
        if not extract_nub_from_pre_car(str(trainee.get("pre_number") or trainee.get("cnaps_tracking_nub") or ""))
        and all(_cnaps_tracking_match_key(trainee.get("last_name"), trainee.get("first_name")))
    ]
    if not candidates:
        return False

    rows, error = fetch_cnapsv3_tracking_requests()
    if error or not rows:
        return False

    nub_by_name = _cnaps_tracking_nub_by_name(rows)
    changed = False
    for trainee in candidates:
        nub = nub_by_name.get(_cnaps_tracking_match_key(trainee.get("last_name"), trainee.get("first_name")))
        if not nub:
            continue
        if str(trainee.get("cnaps_tracking_nub") or "").strip() != nub:
            trainee["cnaps_tracking_nub"] = nub
            changed = True
    return changed

def _cash_amount_value(raw_value: Any) -> float:
    try:
        return max(float(str(raw_value or "").replace(",", ".").strip() or "0"), 0.0)
    except (TypeError, ValueError):
        return 0.0


def _cash_installments_total(raw_installments: Any) -> float:
    if not isinstance(raw_installments, list):
        return 0.0
    total = 0.0
    for item in raw_installments:
        if isinstance(item, dict):
            total += _cash_amount_value(item.get("amount"))
    return round(total, 2)


def _cash_installments_dates(raw_installments: Any) -> List[str]:
    if not isinstance(raw_installments, list):
        return []
    dates = []
    for item in raw_installments:
        if not isinstance(item, dict):
            continue
        date_value = str(item.get("date") or "").strip()
        if date_value:
            dates.append(date_value)
    return sorted(dates)


