def _format_cash_reminder_date(value: Any) -> str:
    try:
        return datetime.date.fromisoformat(str(value or "")[:10]).strftime("%d/%m/%Y")
    except (TypeError, ValueError):
        return str(value or "").strip() or "Non renseignée"


