def _send_wedof_entry_to_salesforce(entry: Dict[str, Any]) -> Tuple[Dict[str, Any], int]:
    entry_id = str(entry.get("id") or "")
    payload = entry.get("payload") if isinstance(entry.get("payload"), dict) else {}
    training = payload.get("trainingActionInfo") if isinstance(payload.get("trainingActionInfo"), dict) else {}
    folder_details = entry.get("wedof_folder_details") if isinstance(entry.get("wedof_folder_details"), dict) else {}
    wedof_fields = _wedof_entry_display_fields(entry)

    first_name = wedof_fields["first_name"]
    last_name = wedof_fields["last_name"]
    email = wedof_fields["email"]
    phone = wedof_fields["phone"]
    training_title = wedof_fields["training_title"]
    training_start_date = wedof_fields["training_date"]
    training_end_date = wedof_fields["training_end_date"]
    location = str(training.get("location") or folder_details.get("location") or "").strip()
    origin = "Compte CPF"

    if training_start_date and training_end_date:
        desired_dates = f"Du {fr_date(training_start_date)} au {fr_date(training_end_date)}"
    elif training_start_date:
        desired_dates = fr_date(training_start_date)
    elif training_end_date:
        desired_dates = f"Jusqu'au {fr_date(training_end_date)}"
    else:
        desired_dates = ""

    def _map_training_type(raw_value: str) -> str:
        value = (raw_value or "").strip().lower()
        if not value:
            return ""
        if "vtc" in value or "chauffeur" in value:
            return "CHAUFFEUR VTC"
        if "a3p" in value:
            return "A3P"
        if "aps" in value:
            return "APS"
        if "dirigeant" in value or "desp" in value:
            return "DIRIGEANT"
        if "bts" in value:
            return "BTS"
        if "ssiap" in value:
            return "SSIAP"
        return ""

    training_type = _map_training_type(training_title)

    summary = []
    if training_title:
        summary.append(f"Formation: {training_title}")
    if desired_dates:
        summary.append(f"Dates souhaitées: {desired_dates}")
    if location:
        summary.append(f"Lieu: {location}")
    case_id = str(entry.get("folder_id") or payload.get("externalId") or "").strip()
    if case_id:
        summary.append(f"Dossier WeDoF: {case_id}")
    if entry.get("event"):
        summary.append(f"Événement: {entry.get('event')}")

    if not last_name:
        last_name = "Nom inconnu"
    company = "Intégrale Connect"

    salesforce_payload = {
        "oid": "00DJ9000000PT9F",
        "encoding": "UTF-8",
        "retURL": f"{PUBLIC_BASE_URL.rstrip('/')}/admin/wedof",
        "first_name": first_name,
        "last_name": last_name,
        "email": email,
        "phone": phone,
        "mobile": phone,
        "company": company,
        "lead_source": "Website",
        "industry": "Education",
        "description": " | ".join(summary) or "Demande WeDoF CPF/EDOF",
        "00NSa00000G2PxB": training_type,
        "00NSa00000KDPOT": location,
        "00NSa00000KPDmX": origin,
        # Do not send the complete webhook body here.  WeDoF folder payloads can
        # be several tens of kilobytes (and may even contain the same JSON more
        # than once).  Salesforce Web-to-Lead rejects oversized form posts with
        # a 503 instead of a validation error.  The permalink is enough to find
        # the source folder from the lead and remains safely bounded.
        "00NSa00000GcKVx": str(payload.get("permalink") or entry.get("permalink") or "")[:255],
        # Champ Salesforce « Dates souhaitées » (plage choisie dans WeDoF).
        "00NSa00000GcKxN": desired_dates,
    }
    # Empty custom fields provide no information and can trigger Salesforce
    # validation rules depending on their configured type.
    salesforce_payload = {
        key: value
        for key, value in salesforce_payload.items()
        if value not in (None, "") or not key.startswith("00N")
    }
    attempted_at = _now_iso()
    entry["salesforce_last_attempt_at"] = attempted_at
    entry.pop("salesforce_last_error", None)

    has_required_contact = bool(email or phone)
    if not has_required_contact:
        error = "Email ou téléphone manquant : envoi Salesforce impossible."
        entry["salesforce_last_error"] = error
        app.logger.warning("[SALESFORCE] envoi ignoré id=%s: %s", entry_id, error)
        return {
            "success": False,
            "salesforce_status": 0,
            "payload_sent": salesforce_payload,
            "salesforce_response_preview": "",
            "error": error,
        }, 422

    app.logger.info(
        "[SALESFORCE] préparation envoi id=%s first_name=%s last_name=%s email=%s phone=%s company=%s lead_source=%s payload=%s",
        entry_id,
        salesforce_payload.get("first_name"),
        salesforce_payload.get("last_name"),
        salesforce_payload.get("email"),
        salesforce_payload.get("phone"),
        salesforce_payload.get("company"),
        salesforce_payload.get("lead_source"),
        salesforce_payload,
    )

    try:
        sf_response = requests.post(
            "https://webto.salesforce.com/servlet/servlet.WebToLead?encoding=UTF-8",
            data=salesforce_payload,
            timeout=20,
        )
    except Exception:
        error = "Erreur réseau lors de l'envoi Salesforce."
        entry["salesforce_last_error"] = error
        app.logger.exception("[SALESFORCE] erreur d'envoi Web-to-Lead")
        return {
            "success": False,
            "salesforce_status": 0,
            "payload_sent": salesforce_payload,
            "salesforce_response_preview": "",
            "error": error,
        }, 502

    response_preview = (sf_response.text or "")[:500]
    app.logger.info(
        "[SALESFORCE] réponse id=%s status=%s url=%s preview=%s",
        entry_id,
        sf_response.status_code,
        sf_response.url,
        response_preview,
    )

    if sf_response.status_code != 200:
        error = f"Salesforce a répondu {sf_response.status_code}. Vérifiez les champs obligatoires et la réponse."
        entry["salesforce_last_error"] = error
        return {
            "success": False,
            "salesforce_status": sf_response.status_code,
            "payload_sent": salesforce_payload,
            "salesforce_response_preview": response_preview,
            "error": error,
        }, 502

    entry["salesforce_sent"] = True
    entry["salesforce_sent_at"] = attempted_at
    entry["salesforce_send_count"] = int(entry.get("salesforce_send_count") or 0) + 1
    return {
        "success": True,
        "salesforce_status": sf_response.status_code,
        "payload_sent": salesforce_payload,
        "salesforce_response_preview": response_preview,
        "salesforce_sent": True,
        "salesforce_sent_at": attempted_at,
        "salesforce_send_count": entry["salesforce_send_count"],
    }, 200


@app.post("/api/send-to-salesforce/<entry_id>")
@admin_login_required
@admin_write_required
def send_wedof_to_salesforce(entry_id: str):
    entries = _load_wedof_webhooks()
    entry = next((item for item in entries if str(item.get("id") or "") == str(entry_id)), None)
    if entry is None:
        return jsonify({"ok": False, "error": "Demande introuvable."}), 404

    result, status_code = _send_wedof_entry_to_salesforce(entry)
    _save_wedof_webhooks(entries)
    return jsonify(result), status_code


@app.route("/api/webhooks/wedof", methods=["POST"])
def wedof_webhook():
    event = (request.headers.get("X-Wedof-Event") or "").strip()
    signature = (request.headers.get("X-Wedof-Signature") or "").strip()
    delivery_id = (request.headers.get("X-Wedof-Delivery") or "").strip()
    raw_body = request.get_data(cache=True) or b""
    payload = request.get_json(silent=True)
    if payload is None:
        payload = {}
    headers_map = {k: v for k, v in request.headers.items()}

    wedof_headers = {
        k: v
        for k, v in headers_map.items()
        if k.lower().startswith("x-wedof") or k.lower() in ("authorization", "x-webhook-secret", "x-api-key")
    }
    app.logger.info("[WEDOF] headers wedof reçus (avant vérification) = %s", wedof_headers)
    app.logger.info("[WEDOF] payload brut reçu = %s", raw_body.decode("utf-8", errors="replace"))

    secret_raw = (os.environ.get("WEDOF_WEBHOOK_SECRET") or "")
    secret = secret_raw.encode("utf-8")
    sig_valid = False

    if signature and secret:
        computed_digest = hmac.new(secret, raw_body, hashlib.sha256).digest()
        computed_hex = computed_digest.hex()
        computed_b64 = base64.b64encode(computed_digest).decode("ascii")
        computed_b64url = base64.urlsafe_b64encode(computed_digest).decode("ascii").rstrip("=")

        provided = signature.split("=", 1)[-1].strip().strip('"').strip("'")
        sig_valid = any(
            hmac.compare_digest(candidate, provided)
            for candidate in (
                computed_hex,
                computed_hex.upper(),
                computed_b64,
                computed_b64url,
            )
        )
        if not sig_valid:
            app.logger.warning("[WEDOF WEBHOOK] invalid_signature: signature reçue mais non valide; webhook accepté temporairement")
    elif secret:
        header_secret = (
            request.headers.get("X-Wedof-Secret")
            or request.headers.get("X-Webhook-Secret")
            or request.headers.get("X-Api-Key")
            or ""
        ).strip().strip('"').strip("'")
        auth_header = (request.headers.get("Authorization") or "").strip()
        auth_secret = ""
        if auth_header.lower().startswith("bearer "):
            auth_secret = auth_header[7:].strip().strip('"').strip("'")
        if header_secret and hmac.compare_digest(header_secret, secret_raw):
            sig_valid = True
            app.logger.info("[WEDOF WEBHOOK] authentifié via secret header")
        elif auth_secret and hmac.compare_digest(auth_secret, secret_raw):
            sig_valid = True
            app.logger.info("[WEDOF WEBHOOK] authentifié via Authorization Bearer")
        else:
            app.logger.warning("[WEDOF WEBHOOK] missing_signature: aucun header signature/secret exploitable; requête acceptée en mode compatibilité")
            sig_valid = True
    else:
        app.logger.warning("[WEDOF WEBHOOK] missing_secret: WEDOF_WEBHOOK_SECRET non configuré; webhook accepté")
        sig_valid = True


    try:
        folder_id = _find_wedof_folder_id(payload)
        app.logger.info("[WEDOF] identifiant dossier trouvé = %s", folder_id or "(aucun)")
        wedof_folder_details = _fetch_wedof_folder_details(folder_id) if folder_id else {}

        entries = _load_wedof_webhooks()
        entry = {
            "id": f"WEDOF-{uuid.uuid4().hex[:10].upper()}",
            "received_at": _now_iso(),
            "event": event,
            "delivery_id": delivery_id,
            "payload": payload,
            "raw_payload": raw_body.decode("utf-8", errors="replace"),
            "headers": headers_map,
            "folder_id": folder_id,
            "wedof_folder_details": wedof_folder_details,
            "processed": False,
            "signature": signature,
            "signature_present": bool(signature),
            "signature_valid": bool(sig_valid),
        }
        entries.insert(0, entry)
        salesforce_result, salesforce_status = _send_wedof_entry_to_salesforce(entry)
        if not salesforce_result.get("success"):
            app.logger.warning(
                "[WEDOF WEBHOOK] envoi Salesforce automatique échoué id=%s status=%s error=%s",
                entry.get("id"),
                salesforce_status,
                salesforce_result.get("error") or "erreur inconnue",
            )
        _save_wedof_webhooks(entries)

        merged_payload = payload.copy() if isinstance(payload, dict) else {}
        if isinstance(wedof_folder_details, dict):
            merged_payload.update({k: v for k, v in wedof_folder_details.items() if k not in merged_payload})
        fields = _extract_wedof_payload_fields(merged_payload if isinstance(merged_payload, dict) else {})
        app.logger.info("[WEDOF MAPPING] nom = %s", fields.get("last_name") or "-")
        app.logger.info("[WEDOF MAPPING] prenom = %s", fields.get("first_name") or "-")
        app.logger.info("[WEDOF MAPPING] email = %s", fields.get("email") or "-")
        app.logger.info("[WEDOF MAPPING] formation = %s", fields.get("training_title") or "-")
        if folder_id and not fields.get("wedof_case_id"):
            fields["wedof_case_id"] = folder_id
        if event.lower().startswith(("cpf", "edof", "dossier", "registrationfolder")) or fields.get("wedof_case_id"):
            app.logger.info(
                "[WEDOF WEBHOOK] dossier conservé uniquement dans /admin/wedof case_id=%s email=%s",
                fields.get("wedof_case_id") or "-",
                fields.get("email") or "-",
            )
    except Exception:
        app.logger.exception("[WEDOF WEBHOOK] erreur")

    return jsonify({"ok": True}), 200


