def _send_afc_candidate_notification(bucket: dict, candidate: dict) -> tuple[bool, str]:
    """Envoie la notification AFC pour un candidat et met à jour son statut."""

    to_email = (candidate.get("email") or "").strip()
    if not to_email:
        return False, "Email manquant"

    decision = (candidate.get("decision") or "").strip().upper()
    templates = bucket.get("mail_templates") or {}
    if decision == "RETENU":
        subject = "Formation APS/SSIAP 1 - Dossier retenu"
        template = templates.get("retained") or AFC_DEFAULT_MAIL_TEMPLATE_RETAINED
    else:
        subject = "Formation APS/SSIAP 1 - Dossier non retenu"
        template = templates.get("rejected") or AFC_DEFAULT_MAIL_TEMPLATE_REJECTED

    raw_content = _afc_render_mail_template(template, candidate)
    html = mail_layout("<p>" + "</p><p>".join([line for line in raw_content.splitlines() if line.strip()]) + "</p>")
    ok = brevo_send_email(to_email, subject, html)
    if not ok:
        return False, "Échec envoi email"

    candidate["notification_status"] = "ENVOYEE"
    candidate["notification_sent_at"] = _now_iso()
    return True, ""


def _send_afc_convocation_notification(bucket: dict, candidate: dict) -> tuple[bool, str]:
    templates = bucket.get("mail_templates") or {}

    email = (candidate.get("email") or "").strip()
    phone = (candidate.get("telephone") or "").strip()
    if not email and not phone:
        return False, "Email et téléphone manquants"

    subject = (templates.get("convocation_subject") or "").strip() or AFC_DEFAULT_CONVOCATION_EMAIL_SUBJECT
    raw_mail = _afc_render_mail_template(
        (templates.get("convocation_email") or "").strip() or AFC_DEFAULT_CONVOCATION_EMAIL_TEMPLATE,
        candidate,
    )
    raw_sms = _afc_render_mail_template(
        (templates.get("convocation_sms") or "").strip() or AFC_DEFAULT_CONVOCATION_SMS_TEMPLATE,
        candidate,
    )

    sent_at = _now_iso()
    email_ok = True
    if email:
        html = mail_layout("<p>" + "</p><p>".join([line for line in raw_mail.splitlines() if line.strip()]) + "</p>")
        email_ok = brevo_send_email(email, subject, html)

    sms_ok = True
    if phone:
        sms_ok = brevo_send_sms(phone, raw_sms)

    # These statuses mean that Brevo accepted the send request.  Actual delivery
    # (or opening for e-mail) requires provider webhooks and must not be implied.
    candidate["convocation_email_status"] = "ACCEPTE" if email and email_ok else ("ECHEC" if email else "ABSENT")
    candidate["convocation_sms_status"] = "ACCEPTE" if phone and sms_ok else ("ECHEC" if phone else "ABSENT")
    candidate["convocation_email_sent_at"] = sent_at if email_ok and email else ""
    candidate["convocation_sms_sent_at"] = sent_at if sms_ok and phone else ""

    if (email and not email_ok) or (phone and not sms_ok):
        return False, "Échec envoi convocation"
    return True, ""


def _send_afc_documents_reminder(
    bucket: Dict[str, Any],
    candidate: Dict[str, Any],
    *,
    source: str,
    sent_at: str = "",
) -> Dict[str, Any]:
    templates = bucket.get("mail_templates") or {}
    email = str(candidate.get("email") or "").strip()
    phone = str(candidate.get("telephone") or "").strip()
    attempt_at = sent_at or _now_iso()

    subject = (
        str(templates.get("documents_reminder_subject") or "").strip()
        or AFC_DEFAULT_DOCUMENTS_REMINDER_EMAIL_SUBJECT
    )
    raw_mail = _afc_render_mail_template(
        str(templates.get("documents_reminder_email") or "").strip()
        or AFC_DEFAULT_DOCUMENTS_REMINDER_EMAIL_TEMPLATE,
        candidate,
    )
    raw_sms = _afc_render_mail_template(
        str(templates.get("documents_reminder_sms") or "").strip()
        or AFC_DEFAULT_DOCUMENTS_REMINDER_SMS_TEMPLATE,
        candidate,
    )

    email_status = "ABSENT"
    email_error = ""
    if email:
        html_body = mail_layout(
            "<p>" + "</p><p>".join(line for line in raw_mail.splitlines() if line.strip()) + "</p>"
        )
        email_result = brevo_send_email(
            email,
            subject,
            html_body,
            text_content=raw_mail,
            metadata={
                "purpose": "afc_documents_reminder",
                "candidate_id": str(candidate.get("id") or ""),
                "source": source,
            },
        )
        email_ok = bool(email_result.get("ok")) if isinstance(email_result, dict) else bool(email_result)
        email_status = "ACCEPTE" if email_ok else "ECHEC"
        if not email_ok:
            email_error = (
                str(email_result.get("error") or "").strip()
                if isinstance(email_result, dict)
                else "Échec envoi e-mail"
            ) or "Échec envoi e-mail"

    sms_status = "ABSENT"
    sms_error = ""
    if phone:
        sms_ok = bool(brevo_send_sms(phone, raw_sms))
        sms_status = "ACCEPTE" if sms_ok else "ECHEC"
        if not sms_ok:
            sms_error = "Échec envoi SMS"

    email_accepted = email_status == "ACCEPTE"
    sms_accepted = sms_status == "ACCEPTE"
    accepted = email_accepted or sms_accepted
    attempted_failures = [
        message
        for message in (email_error, sms_error)
        if message
    ]

    candidate["documents_reminder_last_attempt_at"] = attempt_at
    candidate["documents_reminder_email_status"] = email_status
    candidate["documents_reminder_sms_status"] = sms_status
    if accepted:
        history = _afc_documents_reminder_history(candidate)
        history.append({
            "sent_at": attempt_at,
            "source": "manual" if source == "manual" else "automatic",
            "email_status": email_status,
            "sms_status": sms_status,
        })
        candidate["documents_reminder_history"] = history[-100:]
        candidate["documents_reminder_last_sent_at"] = attempt_at

    if not email and not phone:
        error = "Email et téléphone manquants"
    else:
        error = " ; ".join(attempted_failures)
    if error:
        candidate["documents_reminder_last_error"] = error
    else:
        candidate.pop("documents_reminder_last_error", None)

    intended_channels = int(bool(email)) + int(bool(phone))
    accepted_channels = int(email_accepted) + int(sms_accepted)
    return {
        "ok": accepted,
        "partial": bool(accepted and accepted_channels < intended_channels),
        "error": error,
        "sent_at": attempt_at if accepted else "",
        "email_status": email_status,
        "sms_status": sms_status,
        "history": _afc_documents_reminder_history(candidate),
    }


def _refresh_afc_cnaps_status_for_reminder(candidate: Dict[str, Any], *, changed_at: str = "") -> bool:
    lookup = fetch_cnaps_lookup_by_name(candidate.get("nom") or "", candidate.get("prenom") or "") or {}
    remote_status = str(lookup.get("status") or "").strip()
    if not remote_status:
        return False
    changed = _set_afc_candidate_cnaps_status(candidate, remote_status, changed_at=changed_at)
    remote_history = _normalize_cnaps_remote_history(lookup.get("statut_cnaps_history"))
    if candidate.get("cnaps_status_history") != remote_history:
        candidate["cnaps_status_history"] = remote_history
        changed = True
    return changed


def run_afc_cnaps_status_refresh(
    now: Optional[datetime.datetime] = None,
) -> Dict[str, Any]:
    """Refresh active AFC candidates without waiting for an admin page visit."""
    base_result: Dict[str, Any] = {
        "attempted": 0,
        "checked": 0,
        "updated": 0,
        "errors": 0,
        "skipped_fresh": 0,
    }
    if not (CNAPS_LOOKUP_ENDPOINT or "").strip():
        return {**base_result, "status": "not_configured"}

    current = _afc_utc_datetime(now)
    attempted_at = _iso_from_dt(current)
    snapshot = load_data(run_background_tasks=False)
    afc_bucket = snapshot.get("afc") if isinstance(snapshot.get("afc"), dict) else {}
    raw_candidates = afc_bucket.get("candidates") if isinstance(afc_bucket.get("candidates"), list) else []

    selected: List[Dict[str, str]] = []
    skipped_fresh = 0
    refresh_interval = datetime.timedelta(seconds=AFC_CNAPS_REFRESH_INTERVAL_SECONDS)
    for candidate in raw_candidates:
        if not isinstance(candidate, dict) or candidate.get("archived") or candidate.get("cnaps_priority"):
            continue
        candidate_id = str(candidate.get("id") or "").strip()
        last_name = str(candidate.get("nom") or "").strip()
        first_name = str(candidate.get("prenom") or "").strip()
        if not candidate_id or not last_name or not first_name:
            continue

        last_attempts = [
            parsed
            for parsed in (
                _parse_iso_datetime(candidate.get("cnaps_auto_refresh_attempted_at")),
                _parse_iso_datetime(candidate.get("cnaps_status_checked_at")),
            )
            if parsed is not None
        ]
        if last_attempts and current < max(last_attempts) + refresh_interval:
            skipped_fresh += 1
            continue
        selected.append({"id": candidate_id, "nom": last_name, "prenom": first_name})

    attempts: List[Dict[str, Any]] = []
    successful_checks = errors = 0
    for index, candidate_snapshot in enumerate(selected):
        lookup: Optional[Dict[str, Any]] = None
        try:
            lookup = fetch_cnaps_lookup_by_name(
                candidate_snapshot["nom"],
                candidate_snapshot["prenom"],
            )
        except Exception:
            app.logger.exception(
                "[AFC_CNAPS_REFRESH] lookup failed candidate_id=%s",
                candidate_snapshot["id"],
            )
        remote_status = str((lookup or {}).get("status") or "").strip()
        if remote_status:
            successful_checks += 1
        else:
            errors += 1
        attempts.append({**candidate_snapshot, "lookup": lookup if remote_status else None})
        if AFC_CNAPS_REFRESH_REQUEST_DELAY_SECONDS and index + 1 < len(selected):
            time.sleep(AFC_CNAPS_REFRESH_REQUEST_DELAY_SECONDS)

    updated = 0
    if attempts:
        def merge_afc_cnaps_results(latest_data: Dict[str, Any]) -> int:
            latest_afc = latest_data.get("afc") if isinstance(latest_data.get("afc"), dict) else {}
            latest_candidates = latest_afc.get("candidates") if isinstance(latest_afc.get("candidates"), list) else []
            candidates_by_id = {
                str(item.get("id") or ""): item
                for item in latest_candidates
                if isinstance(item, dict) and item.get("id")
            }
            changed_candidates = 0
            unknown_statuses = {"", "INCONNU", "UNKNOWN", "AUCUN DOSSIER", "NON TRANSMIS", "STATUT CNAPS"}

            for attempt in attempts:
                candidate = candidates_by_id.get(attempt["id"])
                if not candidate or candidate.get("archived") or candidate.get("cnaps_priority"):
                    continue
                # Do not merge a result obtained for an identity edited while
                # the remote request was in flight. The next cycle retries it.
                if (
                    str(candidate.get("nom") or "").strip() != attempt["nom"]
                    or str(candidate.get("prenom") or "").strip() != attempt["prenom"]
                ):
                    continue

                candidate["cnaps_auto_refresh_attempted_at"] = attempted_at
                lookup = attempt.get("lookup")
                if not isinstance(lookup, dict):
                    continue

                candidate["cnaps_status_checked_at"] = attempted_at
                remote_status = str(lookup.get("status") or "").strip()
                current_status = _normalize_afc_cnaps_status(candidate.get("cnaps_status"))
                normalized_remote_status = _normalize_afc_cnaps_status(remote_status)

                # A temporary empty/unknown answer must not erase a status
                # which had already progressed in the CNAPS workflow.
                preserve_known_status = (
                    normalized_remote_status in unknown_statuses
                    and current_status not in unknown_statuses
                )
                candidate_changed = False
                if not preserve_known_status:
                    candidate_changed = _set_afc_candidate_cnaps_status(
                        candidate,
                        remote_status,
                        changed_at=attempted_at,
                    )

                remote_history = _normalize_cnaps_remote_history(lookup.get("statut_cnaps_history"))
                preserve_known_history = preserve_known_status and not remote_history
                if not preserve_known_history and candidate.get("cnaps_status_history") != remote_history:
                    candidate["cnaps_status_history"] = remote_history
                    candidate_changed = True
                if candidate_changed:
                    changed_candidates += 1
            return changed_candidates

        updated = update_data(merge_afc_cnaps_results, run_background_tasks=False)

    app.logger.info(
        "[AFC_CNAPS_REFRESH] status=done selected=%s checked=%s updated=%s errors=%s skipped_fresh=%s",
        len(selected),
        successful_checks,
        updated,
        errors,
        skipped_fresh,
    )
    return {
        "status": "done",
        "attempted": len(selected),
        "checked": successful_checks,
        "updated": updated,
        "errors": errors,
        "skipped_fresh": skipped_fresh,
    }


def _afc_documents_reminders_allowed_now(now_utc: Optional[datetime.datetime] = None) -> bool:
    """Keep automatic AFC e-mail/SMS reminders inside French daytime hours."""
    current = now_utc or datetime.datetime.now(datetime.timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=datetime.timezone.utc)
    paris_hour = current.astimezone(ZoneInfo("Europe/Paris")).hour
    return 8 <= paris_hour < 20


def _run_afc_documents_reminders(
    now: Optional[datetime.datetime] = None,
    *,
    refresh_cnaps: bool = True,
) -> Dict[str, int]:
    current = _afc_utc_datetime(now)
    if not _afc_documents_reminders_allowed_now(current):
        return {"checked": 0, "eligible": 0, "sent": 0, "failed": 0}
    data = load_data()
    bucket = _afc_bucket(data)
    checked = eligible = sent = failed = 0
    changed = False

    for candidate in bucket.get("candidates") or []:
        if not isinstance(candidate, dict) or candidate.get("archived"):
            continue
        checked += 1
        if not _afc_documents_reminder_due(candidate, current):
            continue
        if refresh_cnaps and _afc_candidate_waits_for_documents(candidate):
            if _refresh_afc_cnaps_status_for_reminder(candidate, changed_at=_iso_from_dt(current)):
                changed = True
        if not _afc_documents_reminder_due(candidate, current):
            continue
        eligible += 1
        result = _send_afc_documents_reminder(
            bucket,
            candidate,
            source="automatic",
            sent_at=_iso_from_dt(current),
        )
        changed = True
        if result.get("ok"):
            sent += 1
            _append_activity_log(
                data,
                "afc_documents_reminder_sent",
                "afc_candidate",
                str(candidate.get("id") or ""),
                details={"source": "automatic"},
            )
        else:
            failed += 1

    if changed:
        save_data(data)
    return {
        "checked": checked,
        "eligible": eligible,
        "sent": sent,
        "failed": failed,
    }


def run_afc_documents_reminders(
    now: Optional[datetime.datetime] = None,
    *,
    refresh_cnaps: bool = True,
) -> Dict[str, Any]:
    """Run AFC reminders once, regardless of which scheduler triggered them."""
    if not _afc_documents_reminders_lock.acquire(blocking=False):
        app.logger.info("[AFC_DOCUMENTS_REMINDERS] already_running")
        return {
            "checked": 0,
            "eligible": 0,
            "sent": 0,
            "failed": 0,
            "status": "already_running",
        }
    try:
        return _run_afc_documents_reminders(now, refresh_cnaps=refresh_cnaps)
    finally:
        _afc_documents_reminders_lock.release()


@app.post("/api/admin/afc/candidates/<candidate_id>/documents-reminder")
def api_admin_afc_send_documents_reminder(candidate_id: str):
    data = load_data()
    bucket = _afc_bucket(data)
    candidate = next(
        (item for item in bucket.get("candidates", []) if str(item.get("id") or "") == candidate_id),
        None,
    )
    if not candidate:
        return jsonify({"ok": False, "error": "Candidat introuvable"}), 404
    if candidate.get("archived"):
        return jsonify({"ok": False, "error": "Ce candidat est archivé"}), 400

    result = _send_afc_documents_reminder(bucket, candidate, source="manual")
    if result.get("ok"):
        _append_activity_log(
            data,
            "afc_documents_reminder_sent",
            "afc_candidate",
            candidate_id,
            details={"source": "manual", "partial": bool(result.get("partial"))},
        )
    save_data(data)
    if not result.get("ok"):
        return jsonify(result), 400 if result.get("error") == "Email et téléphone manquants" else 502
    return jsonify(result)


@app.post("/api/admin/afc/candidates/notify-pending")
def api_admin_afc_notify_pending_candidates():
    data = load_data()
    bucket = _afc_bucket(data)
    candidates = bucket.get("candidates") or []

    notified = 0
    skipped = 0
    failed = 0
    for candidate in candidates:
        if candidate.get("archived"):
            skipped += 1
            continue
        status = (candidate.get("notification_status") or "").strip().upper()
        if status == "ENVOYEE":
            skipped += 1
            continue

        decision = (candidate.get("decision") or "").strip().upper()
        if decision in {"", "EN ATTENTE", "EN_ATTENTE", "ATTENTE"}:
            skipped += 1
            continue

        ok, _ = _send_afc_candidate_notification(bucket, candidate)
        if ok:
            notified += 1
        else:
            failed += 1

    if notified:
        save_data(data)

    return jsonify({"ok": True, "notified": notified, "skipped": skipped, "failed": failed})


@app.get("/admin/afc/candidates/<candidate_id>")
def admin_afc_candidate_sheet(candidate_id: str):
    data = load_data()
    bucket = _afc_bucket(data)
    sessions = [s for s in (data.get("sessions") or []) if not s.get("archived")]
    candidate = next((c for c in bucket["candidates"] if str(c.get("id") or "") == candidate_id), None)
    if not candidate:
        abort(404)
    candidate.setdefault("test_francais_reussi", None)
    candidate.setdefault("cnaps_priority", False)
    if candidate.get("cnaps_priority"):
        candidate["cnaps_status"] = "ACCEPTE"
        candidate["decision"] = "RETENU"
        candidate["motif_refus"] = ""
        candidate["complement_refus"] = ""
        candidate["complement_refus_autre"] = ""
    candidate.setdefault("test_results_comment", "")
    positioning_score = _afc_find_latest_positioning_score(candidate, list(data.get("positioning_tests") or []))
    return render_template(
        "admin_afc_candidate_sheet.html",
        candidate=candidate,
        sessions=sessions,
        positioning_score=positioning_score,
        refusal_reasons=AFC_REFUSAL_REASONS,
        refusal_complements=AFC_REFUSAL_COMPLEMENTS,
    )


@app.get("/admin/afc/export")
def admin_afc_export():
    data = load_data()
    bucket = _afc_bucket(data)
    candidates = [c for c in bucket.get("candidates", []) if not c.get("archived")]
    prioritized = [c for c in candidates if c.get("cnaps_priority")]
    non_prioritized = [c for c in candidates if not c.get("cnaps_priority")]
    retained = [c for c in non_prioritized if (c.get("decision") or "").strip().upper() == "RETENU"]
    others = [c for c in non_prioritized if (c.get("decision") or "").strip().upper() != "RETENU"]
    ordered_candidates = prioritized + retained + others
    return render_template("admin_afc_export.html", afc=bucket, candidates=ordered_candidates)




