def _require_exam_dossier_session(data: Dict[str, Any], session_id: str, training: str = "A3P") -> Dict[str, Any]:
    session_item = find_session(data, session_id)
    if not session_item:
        raise LookupError("session_not_found")
    label = f"{_session_get(session_item, 'training_type', '')} {_session_get(session_item, 'name', '')}".upper()
    if training not in label:
        raise ValueError(f"Cette action est réservée aux sessions {training}.")
    return session_item


def _require_a3p_session(data: Dict[str, Any], session_id: str) -> Dict[str, Any]:
    return _require_exam_dossier_session(data, session_id, "A3P")


def _exam_dossier_training() -> str:
    return "APS" if "/aps-exam-dossiers" in request.path else "A3P"


def _exam_dossier_profile(training: str) -> Dict[str, Any]:
    slug = training.lower()
    return {"training": training, "slug": slug, "storage_key": f"{slug}_exam_dossier",
            "template": "dossierexamenaps.docx" if training == "APS" else "docexamena3p.docx",
            # The APS Word model has one more rendered page than the A3P model.
            # Keeping this constraint in the profile prevents APS generation from
            # being rejected by the historical A3P-only six-page validation.
            "expected_pages": 7 if training == "APS" else 6,
            "output_dir": APS_EXAM_DOSSIER_DIR if training == "APS" else A3P_EXAM_DOSSIER_DIR}


def _a3p_exam_dossier_public_config(session_item: Dict[str, Any], storage_key: str = "a3p_exam_dossier") -> Dict[str, Any]:
    saved = session_item.get(storage_key) if isinstance(session_item.get(storage_key), dict) else {}
    generation = saved.get("generation") if isinstance(saved.get("generation"), dict) else {}
    return {
        "training_start_date": saved.get("training_start_date") or _session_get(session_item, "date_start", ""),
        "training_end_date": saved.get("training_end_date") or _session_get(session_item, "date_end", ""),
        "exam_date": saved.get("exam_date") or _session_get(session_item, "exam_date", ""),
        "epi_training_date": saved.get("epi_training_date") or "",
        "selected_trainee_ids": saved.get("selected_trainee_ids") or [],
        "generation": {
            "available": bool(generation.get("archive_path") and os.path.isfile(generation.get("archive_path"))),
            "created_at": generation.get("created_at") or "",
            "candidate_count": generation.get("candidate_count") or 0,
        },
    }


@app.get("/api/admin/sessions/<session_id>/a3p-exam-dossiers")
@app.get("/api/admin/sessions/<session_id>/aps-exam-dossiers")
@admin_login_required
def api_a3p_exam_dossier_config(session_id: str):
    data = load_data()
    profile = _exam_dossier_profile(_exam_dossier_training())
    try:
        session_item = _require_exam_dossier_session(data, session_id, profile["training"])
    except LookupError:
        abort(404)
    except ValueError as exc:
        return jsonify({"ok": False, "message": str(exc)}), 400
    return jsonify({"ok": True, **_a3p_exam_dossier_public_config(session_item, profile["storage_key"])})


def _a3p_exam_context(trainee: Dict[str, Any], values: Dict[str, str]) -> Dict[str, str]:
    first_name = normalize_first_name(trainee.get("first_name") or "")
    last_name = normalize_last_name(trainee.get("last_name") or "")
    address = trainee.get("address") if isinstance(trainee.get("address"), dict) else {}
    address_line = trainee.get("address_line1") or (trainee.get("address") if isinstance(trainee.get("address"), str) else address.get("line1")) or ""
    return {
        "nom": last_name,
        "prenom": first_name,
        "nom_complet": " ".join(part for part in (first_name, last_name) if part),
        "adresse": str(address_line).strip(),
        "code_postal": str(trainee.get("postal_code") or trainee.get("zip_code") or address.get("postal_code") or "").strip(),
        "ville": str(trainee.get("city") or address.get("city") or "").strip(),
        "date_debut_formation": fr_date(values["training_start_date"]),
        "date_fin_formation": fr_date(values["training_end_date"]),
        "date_un_mois_avant_debut_formation": _fr_date_offset(values["training_start_date"], months=-1),
        "periode_formation": f"{fr_date(values['training_start_date'])} au {fr_date(values['training_end_date'])}",
        "date_examen": fr_date(values["exam_date"]),
        "date_15_jours_avant_examen": _fr_date_offset(values["exam_date"], days=-15),
        "date_formation_epi": fr_date(values["epi_training_date"]),
        "date_jour": datetime.datetime.now().strftime("%d/%m/%Y"),
    }


def _prepare_a3p_exam_template(template_path: str, prepared_path: str) -> str:
    """Create a renderable copy without requiring a binary DOCX change in Git.

    The supplied Word file predates this feature and contains a fixed EPI date.
    Replacing it in the DOCX XML copy keeps the original binary untouched while
    still exposing ``date_formation_epi`` to docxtpl at generation time.
    """
    placeholder = "{{ date_formation_epi }}"
    fixed_value = "22 avril 2026"
    placeholder_found = False
    fixed_value_found = False

    def replace_visible_text(xml_text: str, searched: str, replacement: str) -> Tuple[str, bool]:
        """Replace text even when Word has split it over several ``w:t`` nodes."""
        text_node_pattern = re.compile(r"(<w:t\b[^>]*>)(.*?)(</w:t>)", re.DOTALL)
        paragraph_pattern = re.compile(r"(<w:p\b[^>]*>)(.*?)(</w:p>)", re.DOTALL)
        replaced = False

        def replace_in_paragraph(paragraph_match):
            nonlocal replaced
            paragraph = paragraph_match.group(2)
            nodes = list(text_node_pattern.finditer(paragraph))
            visible_text = "".join(html.unescape(node.group(2)) for node in nodes)
            start = visible_text.find(searched)
            if start < 0:
                return paragraph_match.group(0)

            end = start + len(searched)
            cursor = 0
            pieces = []
            for node in nodes:
                node_text = html.unescape(node.group(2))
                node_start, node_end = cursor, cursor + len(node_text)
                if node_end > start and node_start < end:
                    prefix = node_text[:max(0, start - node_start)]
                    suffix = node_text[max(0, end - node_start):] if end < node_end else ""
                    inserted = replacement if node_start <= start < node_end else ""
                    pieces.append((node.start(2), node.end(2), escape(prefix + inserted + suffix)))
                cursor = node_end

            for content_start, content_end, value in reversed(pieces):
                paragraph = paragraph[:content_start] + value + paragraph[content_end:]
            replaced = True
            return paragraph_match.group(1) + paragraph + paragraph_match.group(3)

        # A placeholder occurs only once in this template, but replacing paragraph
        # by paragraph also prevents a match from leaking across page boundaries.
        xml_text = paragraph_pattern.sub(replace_in_paragraph, xml_text)
        return xml_text, replaced

    with zipfile.ZipFile(template_path, "r") as source, zipfile.ZipFile(prepared_path, "w") as destination:
        for item in source.infolist():
            content = source.read(item.filename)
            if item.filename.startswith("word/") and item.filename.endswith(".xml"):
                xml_text = content.decode("utf-8")
                xml_text, found_placeholder = replace_visible_text(xml_text, placeholder, placeholder)
                placeholder_found = placeholder_found or found_placeholder
                xml_text, found_fixed_value = replace_visible_text(xml_text, fixed_value, placeholder)
                fixed_value_found = fixed_value_found or found_fixed_value
                content = xml_text.encode("utf-8")
            destination.writestr(item, content)
    if not placeholder_found and not fixed_value_found:
        os.remove(prepared_path)
        raise RuntimeError(
            "Le modèle Word doit contenir {{ date_formation_epi }} ou la date EPI d'origine « 22 avril 2026 »."
        )
    return prepared_path


def _replace_a3p_docx_ooxml(template_path: str, output_path: str, context: Dict[str, str]) -> str:
    """Fill the A3P template without letting a word processor rebuild its layout.

    Word commonly splits a placeholder over several ``w:t`` elements.  This
    routine changes only the character data of those existing elements: runs,
    paragraphs, tables, headers, footers, relationships and page breaks remain
    byte-for-byte structurally identical to the original package.
    """
    text_node_pattern = re.compile(r"(<w:t\b[^>]*>)(.*?)(</w:t>)", re.DOTALL)
    paragraph_pattern = re.compile(r"(<w:p\b[^>]*>)(.*?)(</w:p>)", re.DOTALL)
    replacements = {
        re.sub(r"\s+", "", "{{" + key + "}}"): str(value)
        for key, value in context.items()
    }

    def fill_paragraph(match):
        paragraph = match.group(2)
        nodes = list(text_node_pattern.finditer(paragraph))
        visible = "".join(html.unescape(node.group(2)) for node in nodes)
        compact = re.sub(r"\s+", "", visible)
        # Preserve ordinary spaces in the document; compacting is only used to
        # recognize the optional spaces inside a complete template expression.
        found = []
        for placeholder, value in replacements.items():
            pattern = re.compile(r"\{\{\s*" + re.escape(placeholder[2:-2]) + r"\s*\}\}")
            for occurrence in pattern.finditer(visible):
                found.append((occurrence.start(), occurrence.end(), value))
        if not found:
            return match.group(0)
        for start, end, value in sorted(found, reverse=True):
            cursor = 0
            edits = []
            inserted = False
            for node in nodes:
                node_text = html.unescape(node.group(2))
                node_start, node_end = cursor, cursor + len(node_text)
                if node_end > start and node_start < end:
                    prefix = node_text[:max(0, start - node_start)]
                    suffix = node_text[max(0, end - node_start):] if end < node_end else ""
                    addition = value if not inserted else ""
                    edits.append((node.start(2), node.end(2), escape(prefix + addition + suffix)))
                    inserted = True
                cursor = node_end
            for content_start, content_end, replacement in reversed(edits):
                paragraph = paragraph[:content_start] + replacement + paragraph[content_end:]
            nodes = list(text_node_pattern.finditer(paragraph))
        return match.group(1) + paragraph + match.group(3)

    unresolved = set()
    with zipfile.ZipFile(template_path, "r") as source, zipfile.ZipFile(output_path, "w") as destination:
        for item in source.infolist():
            content = source.read(item.filename)
            if item.filename.startswith("word/") and item.filename.endswith(".xml"):
                xml_text = content.decode("utf-8")
                xml_text = paragraph_pattern.sub(fill_paragraph, xml_text)
                unresolved.update(re.findall(r"\{\{\s*([a-zA-Z0-9_]+)\s*\}\}", xml_text))
                content = xml_text.encode("utf-8")
            destination.writestr(item, content)
    if unresolved:
        os.remove(output_path)
        raise RuntimeError("Variables Word A3P non remplacées : " + ", ".join(sorted(unresolved)))
    return output_path


def _assert_calibri_font_substitution() -> None:
    """Fail before LibreOffice starts if Render would fall back to DejaVu."""
    result = subprocess.run(
        ["fc-match", "-f", "%{family}\n", "Calibri"],
        check=True, capture_output=True, text=True, timeout=15,
    )
    matched_family = (result.stdout or "").splitlines()[0].strip()
    if "Carlito" not in matched_family:
        raise RuntimeError(f"Fontconfig invalide : Calibri correspond à {matched_family or 'aucune police'}, pas à Carlito.")


def _validate_a3p_pdf(pdf_path: str, training: str = "A3P", expected_pages: int = 6) -> None:
    """Reject a conversion with altered pagination, blank pages or bad fonts."""
    reader = PdfReader(pdf_path)
    if len(reader.pages) != expected_pages:
        raise RuntimeError(
            f"Le dossier {training} doit faire exactement {expected_pages} pages "
            f"(obtenu : {len(reader.pages)})."
        )
    font_names, embedded_fonts = set(), set()
    for page_number, page in enumerate(reader.pages, 1):
        resources = page.get("/Resources") or {}
        xobjects = resources.get("/XObject") or {}
        has_image = any((obj.get_object().get("/Subtype") == "/Image") for obj in xobjects.values())
        if not (page.extract_text() or "").strip() and not has_image:
            raise RuntimeError(f"Le dossier {training} contient une page blanche (page {page_number}).")
        for font_ref in (resources.get("/Font") or {}).values():
            font = font_ref.get_object()
            name = str(font.get("/BaseFont") or "")
            font_names.add(name)
            descriptor = font.get("/FontDescriptor")
            if not descriptor and font.get("/DescendantFonts"):
                descendant = font["/DescendantFonts"][0].get_object()
                descriptor = descendant.get("/FontDescriptor")
            if descriptor:
                descriptor = descriptor.get_object()
                if any(descriptor.get(key) for key in ("/FontFile", "/FontFile2", "/FontFile3")):
                    embedded_fonts.add(name)
    normalized = " ".join(font_names).lower()
    if "dejavusans" in normalized or "dejavuserif" in normalized:
        raise RuntimeError(f"Le PDF {training} utilise encore DejaVu Sans/Serif.")
    if not any("carlito" in name.lower() for name in embedded_fonts):
        raise RuntimeError(f"Carlito n'est pas intégrée dans le PDF {training}.")


@app.post("/api/admin/sessions/<session_id>/a3p-exam-dossiers/generate")
@app.post("/api/admin/sessions/<session_id>/aps-exam-dossiers/generate")
@admin_login_required
@admin_write_required
def api_generate_a3p_exam_dossiers(session_id: str):
    profile = _exam_dossier_profile(_exam_dossier_training())
    payload = request.get_json(silent=True) or {}
    values = {key: str(payload.get(key) or "").strip() for key in (
        "training_start_date", "training_end_date", "exam_date", "epi_training_date"
    )}
    selected_ids = [str(value) for value in payload.get("selected_trainee_ids", []) if str(value).strip()]
    if not all(values.values()) or not selected_ids:
        return jsonify({"ok": False, "message": "Toutes les dates et au moins un candidat sont obligatoires."}), 400
    if values["training_end_date"] < values["training_start_date"]:
        return jsonify({"ok": False, "message": "La date de fin doit être postérieure à la date de début."}), 400
    template_path = os.path.join(app.root_path, "templates_word", profile["template"])
    if not os.path.isfile(template_path):
        return jsonify({"ok": False, "message": f"Le modèle de dossier examen {profile['training']} est introuvable."}), 503
    data = load_data()
    try:
        session_item = _require_exam_dossier_session(data, session_id, profile["training"])
    except LookupError:
        abort(404)
    except ValueError as exc:
        return jsonify({"ok": False, "message": str(exc)}), 400
    trainee_by_id = {str(item.get("id") or ""): item for item in _session_trainees_list(session_item)}
    selected = [trainee_by_id[item_id] for item_id in selected_ids if item_id in trainee_by_id]
    if not selected:
        return jsonify({"ok": False, "message": "Aucun candidat valide n'a été sélectionné."}), 400

    generation_id = uuid.uuid4().hex
    output_dir = os.path.join(profile["output_dir"], str(session_id), generation_id)
    os.makedirs(output_dir, exist_ok=True)
    pdf_paths = []
    try:
        lo_binary = _find_libreoffice_binary()
        _assert_calibri_font_substitution()
        prepared_template_path = _prepare_a3p_exam_template(
            template_path, os.path.join(output_dir, f"modele_dossier_examen_{profile['slug']}.docx")
        )
        for trainee in selected:
            display_last = normalize_last_name(trainee.get("last_name") or "")
            display_first = normalize_first_name(trainee.get("first_name") or "")
            base_name = f"Dossier examen {profile['training']} {display_last} {display_first}".strip()
            safe_base = secure_filename(base_name) or f"Dossier_examen_{profile['training']}_{trainee.get('id')}"
            docx_path = os.path.join(output_dir, safe_base + ".docx")
            _replace_a3p_docx_ooxml(prepared_template_path, docx_path, _a3p_exam_context(trainee, values))
            result = subprocess.run(
                [lo_binary, "--headless", "--convert-to", "pdf", "--outdir", output_dir, docx_path],
                check=True, capture_output=True, text=True, timeout=120,
            )
            pdf_path = os.path.join(output_dir, safe_base + ".pdf")
            if not os.path.isfile(pdf_path):
                raise RuntimeError(result.stderr or "Le PDF n'a pas été créé.")
            _validate_a3p_pdf(pdf_path, profile["training"], profile["expected_pages"])
            pdf_paths.append((pdf_path, base_name + ".pdf"))
            os.remove(docx_path)
        os.remove(prepared_template_path)

        combined_path = os.path.join(output_dir, f"Tous les dossiers examen {profile['training']}.pdf")
        writer = PdfWriter()
        for pdf_path, _ in pdf_paths:
            for page in PdfReader(pdf_path).pages:
                writer.add_page(page)
        with open(combined_path, "wb") as combined_file:
            writer.write(combined_file)
        archive_path = os.path.join(output_dir, f"Dossiers examen {profile['training']}.zip")
        with zipfile.ZipFile(archive_path, "w", zipfile.ZIP_DEFLATED) as archive:
            for pdf_path, download_name in pdf_paths:
                archive.write(pdf_path, download_name)
            archive.write(combined_path, os.path.basename(combined_path))
    except Exception as exc:
        shutil.rmtree(output_dir, ignore_errors=True)
        app.logger.exception("Génération des dossiers examen %s impossible", profile["training"])
        return jsonify({"ok": False, "message": f"La génération a échoué : {exc}"}), 500

    session_item[profile["storage_key"]] = {
        **values,
        "selected_trainee_ids": [str(item.get("id") or "") for item in selected],
        "generation": {"id": generation_id, "archive_path": archive_path, "created_at": _now_iso(), "candidate_count": len(selected)},
    }
    save_data(data)
    download_endpoint = "admin_download_aps_exam_dossiers" if profile["training"] == "APS" else "admin_download_a3p_exam_dossiers"
    return jsonify({"ok": True, "candidate_count": len(selected), "download_url": url_for(download_endpoint, session_id=session_id)})


@app.get("/admin/sessions/<session_id>/a3p-exam-dossiers/download")
@admin_login_required
def admin_download_a3p_exam_dossiers(session_id: str):
    return _download_exam_dossiers(session_id, "A3P")


@app.get("/admin/sessions/<session_id>/aps-exam-dossiers/download")
@admin_login_required
def admin_download_aps_exam_dossiers(session_id: str):
    return _download_exam_dossiers(session_id, "APS")


def _download_exam_dossiers(session_id: str, training: str):
    data = load_data()
    profile = _exam_dossier_profile(training)
    try:
        session_item = _require_exam_dossier_session(data, session_id, training)
    except LookupError:
        abort(404)
    except ValueError as exc:
        return str(exc), 400
    generation = (session_item.get(profile["storage_key"]) or {}).get("generation") or {}
    archive_path = generation.get("archive_path") or ""
    expected_root = os.path.realpath(os.path.join(profile["output_dir"], str(session_id)))
    if not archive_path or not os.path.isfile(archive_path) or not os.path.realpath(archive_path).startswith(expected_root + os.sep):
        abort(404, description="Aucun dossier d'examen généré n'est disponible.")
    return send_file(archive_path, mimetype="application/zip", as_attachment=True, download_name=f"Dossiers examen {training}.zip")


@app.get("/admin/sessions/<session_id>/tshirt-list")
@admin_login_required
def admin_tshirt_list(session_id: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        abort(404)

    training_type = (_session_get(s, "training_type", "") or "").strip().upper()
    if training_type != "A3P":
        return redirect(url_for("admin_trainees", session_id=session_id))

    session_view = {
        "id": s.get("id"),
        "name": _session_get(s, "name", ""),
        "training_type": _session_get(s, "training_type", ""),
        "date_start": _session_get(s, "date_start", ""),
        "date_end": _session_get(s, "date_end", ""),
    }

    trainees = _session_trainees_list(s)
    trainees_out = []
    for t in trainees:
        tshirt_size = (t.get("tshirt_size") or "").strip().upper()
        trainees_out.append({
            "last_name": normalize_last_name(t.get("last_name") or ""),
            "first_name": normalize_first_name(t.get("first_name") or ""),
            "email": (t.get("email") or "").strip(),
            "phone": format_phone_fr_for_display((t.get("phone") or "").strip()),
            "tshirt_size": tshirt_size if tshirt_size in TSHIRT_SIZES else "",
        })

    trainees_out.sort(key=lambda t: (
        (t.get("tshirt_size") or "ZZZ"),
        (t.get("last_name") or "").upper(),
        (t.get("first_name") or "").upper(),
    ))

    return render_template(
        "admin_tshirt_list.html",
        session=session_view,
        trainees=trainees_out,
    )


@app.get("/admin/sessions/<session_id>/trainees")
@admin_login_required
def admin_trainees(session_id: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        abort(404)
    if _is_wedof_leads_session(s):
        abort(404)

    # normalize session view
    session_view = {
        "id": s.get("id"),
        "name": _session_get(s, "name", ""),
        "training_type": _session_get(s, "training_type", ""),
        "date_start": _session_get(s, "date_start", ""),
        "date_end": _session_get(s, "date_end", ""),
        "exam_date": _session_get(s, "exam_date", ""),
        "exam_theory_date": _session_get(s, "exam_theory_date", ""),
        "exam_practice_date": _session_get(s, "exam_practice_date", ""),
        "practice_training_date": _session_get(s, "practice_training_date", ""),
        "ssiap_exam_date": _session_get(s, "ssiap_exam_date", ""),
        "aps_elearning_enabled": bool(s.get("aps_elearning_enabled")),
        "prospects_comment": _session_get(s, "prospects_comment", ""),
    }

    trainees = _session_trainees_list(s)
    training_type = session_view["training_type"]

    auto_refresh_external = (request.args.get("refresh_external") or "").strip() == "1"

    # normalize trainees (and optionally refresh external statuses)
    for t in trainees:
        ln = normalize_last_name(t.get("last_name") or "")
        fn = normalize_first_name(t.get("first_name") or "")
        email = (t.get("email") or "").strip().lower()
        unread_summary = _scotia_unread_thread_summary(t)
        t["scotia_unread_thread_count"] = int(unread_summary.get("count") or 0) if unread_summary else 0

        if ln:
            t["last_name"] = ln
        if fn:
            t["first_name"] = fn

        _sync_trainee_afc_medical_requirement(t, session_view["name"])
        ensure_documents_schema_for_trainee(t, training_type)
        _sync_convention_status_from_yousign(t)
        t["dossier_status"] = "complete" if dossier_is_complete_total(t, training_type, _session_get(s, "date_start", "")) else "incomplete"
        _sync_financement_status_from_manual_validation(t)

        current_cnaps = t.get("cnaps") or ""

        # ✅ si déjà validé manuellement, on ne touche pas
        if _normalize_cnaps_status(current_cnaps) != "CARTE PROFESSIONNELLE OK" and auto_refresh_external:
            if ln and fn:
                cn = fetch_cnaps_status_by_name(ln, fn)

                # ✅ n'écrase jamais avec INCONNU
                if cn:
                    cn_u = str(cn).strip().upper()
                    if cn_u not in ("INCONNU", "UNKNOWN", ""):
                        if _normalize_cnaps_status(cn_u) != _normalize_cnaps_status(current_cnaps):
                            t["cnaps"] = cn_u
                            record_cnaps_status_change(t, cn_u)

        # valeur par défaut si vide
        if not (t.get("cnaps") or "").strip():
            t["cnaps"] = "INCONNU"
            record_cnaps_status_change(t, t["cnaps"])

        # hosting only for A3P
        if session_view["training_type"] == "A3P":
            # ✅ règle anti-bug : on ne downgrade JAMAIS "reserved"
            current = (t.get("hosting_status") or "unknown").strip().lower()
            should_refresh_hosting = current != "reserved"
            _log_charles_hebergement_trace(
                "admin_trainees",
                "état local avant rendu",
                email=email,
                last_name=ln,
                first_name=fn,
                session_name=session_view["name"],
                session_date_start=session_view["date_start"],
                session_date_end=session_view["date_end"],
                current_hosting_status=current,
                auto_refresh_external=auto_refresh_external,
                should_refresh_hosting_on_render=should_refresh_hosting,
            )

            if should_refresh_hosting:
                _log_charles_hebergement_trace(
                    "admin_trainees",
                    "appel fetch_hebergement_status depuis le rendu serveur",
                    email=email,
                    last_name=ln,
                    first_name=fn,
                    session_name=session_view["name"],
                    session_date_start=session_view["date_start"],
                    session_date_end=session_view["date_end"],
                )
                hb = fetch_hebergement_status(
                    email,
                    last_name=ln,
                    first_name=fn,
                    session_name=session_view["name"],
                    session_date_start=session_view["date_start"],
                    session_date_end=session_view["date_end"],
                )
            else:
                hb = None
                _log_charles_hebergement_trace(
                    "admin_trainees",
                    "fetch_hebergement_status non appelé au rendu serveur",
                    email=email,
                    last_name=ln,
                    first_name=fn,
                    session_name=session_view["name"],
                    session_date_start=session_view["date_start"],
                    session_date_end=session_view["date_end"],
                    reason="status_local_deja_reserved",
                )

            _log_charles_hebergement_trace(
                "admin_trainees",
                "résultat fetch_hebergement_status au rendu serveur",
                email=email,
                last_name=ln,
                first_name=fn,
                session_name=session_view["name"],
                session_date_start=session_view["date_start"],
                session_date_end=session_view["date_end"],
                fetch_result=hb,
                current_hosting_status=current,
            )

            if hb == "reserved":
                t["hosting_status"] = "reserved"
            elif current == "reserved":
                # on garde reserved quoi qu'il arrive
                t["hosting_status"] = "reserved"
            else:
                # sinon on garde l'ancien si on n'a pas mieux
                t["hosting_status"] = current if current else "unknown"
            _log_charles_hebergement_trace(
                "admin_trainees",
                "valeur finale sauvegardée avant template",
                email=email,
                last_name=ln,
                first_name=fn,
                session_name=session_view["name"],
                session_date_start=session_view["date_start"],
                session_date_end=session_view["date_end"],
                final_hosting_status=t.get("hosting_status"),
            )
        else:
            t.pop("hosting_status", None)

    show_vae = (session_view["training_type"] == "DIRIGEANT VAE")
    vae_dashboard_counts = {}
    if show_vae:
        now_utc = datetime.datetime.now(datetime.timezone.utc)
        vae_dashboard_counts = {
            "no_login": 0,
            "new_vae_request_72h": 0,
            "l1_pending_transmission": 0,
            "non_recevable": 0,
        }
        for t in trainees:
            if not isinstance(t.get("vae_action_dates"), dict):
                t["vae_action_dates"] = {}
            _sync_vae_status_with_actions(t)
            created_at = _parse_iso_datetime(t.get("created_at") or "")
            if created_at and created_at.tzinfo is None:
                created_at = created_at.replace(tzinfo=datetime.timezone.utc)
            if created_at:
                created_at = created_at.astimezone(datetime.timezone.utc)
            t["is_vae_new_request_72h"] = bool(
                created_at
                and datetime.timedelta(0) <= (now_utc - created_at) <= datetime.timedelta(hours=72)
            )

            status_key = vae_status_view(t.get("vae_status") or t.get("vae_status_label"))["key"]
            livret_1_transmitted = bool(
                t["vae_action_dates"].get("livret_1_transmitted_scotia")
                or t.get("livret_1_transmitted_scotia")
                or t.get("livret_1_transmitted_scotia_at")
            )
            count_status_key = "livret_2_validated" if status_key == "financement_l2_validated" else status_key
            if status_key != "livret_1_analysis" or livret_1_transmitted:
                count_key = f"status:{count_status_key}"
                vae_dashboard_counts[count_key] = vae_dashboard_counts.get(count_key, 0) + 1
            if status_key == "livret_1_analysis" and not livret_1_transmitted:
                vae_dashboard_counts["l1_pending_transmission"] += 1
            if (t.get("scotia_status") or "").strip() == "non_recevable":
                vae_dashboard_counts["non_recevable"] += 1
            if not t.get("public_has_logged_in"):
                vae_dashboard_counts["no_login"] += 1
            if t.get("is_vae_new_request_72h"):
                vae_dashboard_counts["new_vae_request_72h"] += 1
            unread_summary = _scotia_unread_thread_summary(t)
            t["scotia_unread_thread_count"] = int(unread_summary.get("count") or 0) if unread_summary else 0

        scotia_items = _all_scotia_items(data, include_archived=True)
        for t in trainees:
            t["scotia_admin_status"] = _scotia_admin_status_for_trainee(
                scotia_items, session_view["id"], t.get("id"),
            )

    if session_view["training_type"] in {"APS", "A3P"}:
        _hydrate_missing_trainee_nubs_from_cnaps_tracking(trainees)

    # persist normalized trainees back into storage
    s["trainees"] = trainees
    s.pop("stagiaires", None)
    save_data(data)
    stats = compute_stats(s)
    show_hosting = (session_view["training_type"] == "A3P")
    is_vtc = ("VTC" in (session_view["training_type"] or "").upper())
    is_aps = _is_aps_session(session_view)
    is_dirigeant = ("DIRIGEANT" in (session_view["training_type"] or "").upper())

    # ✅ docs fin de formation par stagiaire (pour surlignage + n/3 + étiquettes)
    for t in trainees:
        t.setdefault("deliverables", {})
        d_done, d_total, d_ok = deliverables_progress(t)
        t["deliverables_done"] = d_done
        t["deliverables_total"] = d_total
        t["deliverables_ok"] = d_ok
        t["deliverables_text"] = f"{d_done}/{d_total}"
        t["convention_signature_label"] = _convention_signature_admin_label(_yousign_state(t))
        t["convocation_signature_label"] = t["convention_signature_label"]

        # ✅ étiquettes ligne (admin_trainees.html)
        dv = t.get("deliverables") or {}
        t["has_sst"] = bool((dv.get("carte_sst") or "").strip())
        t["has_attestation"] = bool((dv.get("attestation_fin_formation") or "").strip())
        t["has_diplome"] = bool((dv.get("diplome") or "").strip())

        badges = []
        if t["has_sst"]:
            badges.append("SST")
        if t["has_attestation"]:
            badges.append("ATTESTATIONS")
        if t["has_diplome"]:
            badges.append("DIPLÔME")
        t["badges"] = badges

    for t in trainees:
        if session_view["training_type"] != "A3P":
            continue
        _log_charles_hebergement_trace(
            "admin_trainees",
            "valeur envoyée au template",
            email=(t.get("email") or "").strip().lower(),
            last_name=t.get("last_name") or "",
            first_name=t.get("first_name") or "",
            session_name=session_view["name"],
            session_date_start=session_view["date_start"],
            session_date_end=session_view["date_end"],
            template_hosting_status=t.get("hosting_status"),
        )

    if show_vae:
        trainees.sort(
            key=lambda t: (
                _parse_iso_datetime(t.get("created_at") or "") or datetime.datetime.min,
                _trainee_alpha_sort_key(t),
            ),
            reverse=True,
        )
    else:
        trainees.sort(key=_trainee_alpha_sort_key)

    return render_template(
        "admin_trainees.html",
        session=session_view,
        trainees=trainees,
        stats=stats,
        show_hosting=show_hosting,
        show_vae=show_vae,
        is_vtc=is_vtc,
        is_aps=is_aps,
        is_dirigeant=is_dirigeant,
        is_desp_initial=_is_desp_initial_session(s),
        finance_summary=_admin_trainees_finance_summary(session_view, trainees),
        vae_dashboard_counts=vae_dashboard_counts,
        enums=ENUMS,
        is_adef=_is_adef_training(session_view["training_type"]),
    )


