@app.post("/api/sessions/<session_id>/trainees/create")
@admin_login_required
@admin_write_required
def api_create_trainee(session_id: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        return jsonify({"ok": False, "error": "session_not_found"}), 404

    payload = request.get_json(silent=True) or {}
    crm_prefill_id = str(payload.get("crm_prefill") or "").strip()
    crm_transfer = None
    if crm_prefill_id:
        now = datetime.datetime.now(datetime.timezone.utc)
        crm_transfer = next((item for item in data.get("crm_prefill_transfers", [])
                             if hmac.compare_digest(str(item.get("id") or ""), crm_prefill_id)), None)
        if not crm_transfer:
            return jsonify({"ok": False, "error": "crm_prefill_not_found"}), 410
        try:
            expires_at = datetime.datetime.fromisoformat(str(crm_transfer.get("expires_at") or ""))
            if expires_at.tzinfo is None: expires_at = expires_at.replace(tzinfo=datetime.timezone.utc)
        except (TypeError, ValueError):
            expires_at = now
        if expires_at <= now:
            return jsonify({"ok": False, "error": "crm_prefill_expired"}), 410
        if crm_transfer.get("matched_session_id") != session_id:
            return jsonify({"ok": False, "error": "crm_session_mismatch"}), 409
    last_name = normalize_last_name(payload.get("last_name") or "")
    first_name = normalize_first_name(payload.get("first_name") or "")
    birth_date = (payload.get("birth_date") or "").strip()
    birth_city = (payload.get("birth_city") or "").strip()
    email = (payload.get("email") or "").strip()
    phone = (payload.get("phone") or "").strip()
    address = (payload.get("address") or "").strip()
    zip_code = (payload.get("zip_code") or "").strip()
    city = (payload.get("city") or "").strip()
    cpf_amount = (payload.get("cpf_amount") or "").strip()
    personal_amount = (payload.get("personal_amount") or "").strip()
    other_amount = (payload.get("other_amount") or "").strip()
    carte_pro_ok = bool(payload.get("carte_pro_ok"))
    vtc_real_training_dates = (payload.get("vtc_real_training_dates") or "").strip()
    afc_candidate_id = (payload.get("afc_candidate_id") or "").strip()

    # ✅ nouveau : choisir si on envoie l'accès tout de suite
    send_access = payload.get("send_access", True)
    send_access = True if send_access in (True, "true", "1", 1, "yes", "on") else False

    if not last_name or not first_name:
        return jsonify({"ok": False, "error": "missing_name"}), 400

    trainee_id = "TRN-" + uuid.uuid4().hex[:8].upper()

    training_type = _session_get(s, "training_type", "")
    show_hosting = (training_type == "A3P")
    show_vae = (training_type == "DIRIGEANT VAE")
    default_price = default_training_price(training_type)

    public_token = uuid.uuid4().hex

    t = {
        "id": trainee_id,
        "personal_id": trainee_id,
        "last_name": last_name,
        "first_name": first_name,
        "birth_date": birth_date,
        "birth_city": birth_city,
        "email": email,
        "phone": phone,
        "vtc_cmar_id": "",
        "address": address,
        "zip_code": zip_code,
        "city": city,
        "comment": "",
        "cnaps": "CARTE PROFESSIONNELLE OK" if carte_pro_ok else "INCONNU",
        "convention_status": "soon",
        "test_fr_status": "soon",
        "dossier_status": "incomplete",
        "financement_status": "soon",
        "training_price": default_price if default_price is not None else "",
        "exclude_from_sales_tracking": False,
        "sales_tracking_amount": "",
        "cpf_amount": cpf_amount,
        "personal_amount": personal_amount,
        "other_amount": other_amount,
        "vae_status": "soon" if show_vae else "",
        "hosting_status": "unknown" if show_hosting else "",
        "public_token": public_token,
        "tshirt_size": "",
        "no_permis": False,
        "no_bac_diploma": False,
        "force_dossier_complete": False,
        "professional_experience_sheet_required": True,
        "vtc_cm_login": "",
        "vtc_cm_password": "",
        "vtc_cm_submitted_at": "",
        "vtc_cm_reminder_sent_at": "",
        "vtc_cm_reminder_email_ok": False,
        "vtc_cm_reminder_sms_ok": False,
        "vtc_cm_reminder_copy_email_ok": False,
        "exam_fees_paid": False,
        "vtc_cmar_manual_ok": False,
        "exam_fees_paid_at": "",
        "elearning_link": "",
        "vtc_elearning_manual_ok": False,
        "elearning_link_sent_at": "",
        "elearning_link_email_ok": False,
        "elearning_link_sms_ok": False,
        "vtc_book_sent_at": "",
        "vtc_book_manual_ok": False,
        "vtc_exam_center": "",
        "vtc_real_training_dates": vtc_real_training_dates,
        "documents": [],
        "created_at": _now_iso(),
        "phone_followups": [],
        "public_hide_popup": False,
        "ssiap_exam_date": "",
        "ypareo_statut": "Non envoyé",
        "ypareo_id": "",
        "ypareo_erreur": "",
        "ypareo_cursus_statut": "Non envoyé",
        "ypareo_cursus_id": "",
        "ypareo_cursus_erreur": "",
    }
    if crm_transfer:
        crm_payload = crm_transfer.get("payload") or {}
        t["crm_contact_id"] = str(crm_payload.get("crm_contact_id") or "")
        t["crm_source"] = str(crm_payload.get("source") or "")
        t["crm_parcours"] = str(crm_payload.get("parcours") or "")
        t["comment"] = str(crm_payload.get("commentaires") or "")

    _sync_trainee_afc_medical_requirement(t, _session_get(s, "name", ""))
    ensure_documents_schema_for_trainee(t, training_type)
    t["dossier_status"] = "complete" if dossier_is_complete_total(t, training_type, _session_get(s, "date_start", "")) else "incomplete"

    trainees = _session_trainees_list(s)
    trainees.insert(0, t)

    enrolled_at = ""
    if afc_candidate_id:
        afc_bucket = _afc_bucket(data)
        afc_candidate = next(
            (candidate for candidate in (afc_bucket.get("candidates") or []) if str(candidate.get("id") or "") == afc_candidate_id),
            None,
        )
        if afc_candidate is not None:
            enrolled_at = str(afc_candidate.get("enrolled_at") or "").strip() or _now_iso()
            afc_candidate["enrolled_at"] = enrolled_at

    _apply_pending_cnaps_imports_for_trainee(data, s, t)

    s["trainees"] = trainees
    s.pop("stagiaires", None)
    if crm_transfer:
        data["crm_prefill_transfers"] = [item for item in data.get("crm_prefill_transfers", [])
                                           if not hmac.compare_digest(str(item.get("id") or ""), crm_prefill_id)]
