def _token_belongs_to_trainee(t: dict, file_token: str) -> bool:
    file_token = (file_token or "").strip()
    if not file_token:
        return False

    # Deliverables (diplôme / SST / attestation)
    dv = t.get("deliverables") or {}
    for k in ("diplome", "carte_sst", "attestation_fin_formation", "attestation_recevabilite", "livret_2", "parchemin"):
        if (dv.get(k) or "").strip() == file_token:
            return True

    # Documents (mono + multi fichiers)
    for d in (t.get("documents") or []):
        if (d.get("file") or "").strip() == file_token:
            return True
        files = d.get("files")
        if isinstance(files, list) and file_token in [x.strip() for x in files if isinstance(x, str)]:
            return True

    # Photo identité (optionnel mais utile)
    if (t.get("identity_photo") or "").strip() == file_token:
        return True

    conv_sig = t.get("convention_signature") if isinstance(t.get("convention_signature"), dict) else {}
    for key in ("signed_pdf_token", "unsigned_pdf_token"):
        if (conv_sig.get(key) or "").strip() == file_token:
            return True
    for key in ("convocation_aps_pdf_token", "attestation_entree_aps_pdf_token", "attestation_fin_aps_pdf_token"):
        if (t.get(key) or "").strip() == file_token:
            return True

    return False


def _private_documents(t: dict) -> List[Dict[str, str]]:
    """Return the admin-only documents attached to a trainee, cleaning legacy data."""
    documents = t.get("private_documents")
    if not isinstance(documents, list):
        documents = []

    cleaned = []
    for document in documents:
        if not isinstance(document, dict):
            continue
        file_token = str(document.get("file") or "").strip()
        if not file_token:
            continue
        cleaned.append({
            "id": str(document.get("id") or uuid.uuid4().hex),
            "name": str(document.get("name") or "Document sans nom").strip()[:120] or "Document sans nom",
            "file": file_token,
            "original_name": str(document.get("original_name") or "").strip(),
            "uploaded_at": str(document.get("uploaded_at") or "").strip(),
        })
    t["private_documents"] = cleaned
    return cleaned


@app.post("/admin/sessions/<session_id>/stagiaires/<trainee_id>/private-documents/upload")
@admin_login_required
@admin_write_required
def admin_upload_private_document(session_id: str, trainee_id: str):
    data = load_data()
    session_obj = find_session(data, session_id)
    if not session_obj:
        abort(404)
    trainee = next((item for item in _session_trainees_list(session_obj) if item.get("id") == trainee_id), None)
    if not trainee:
        abort(404)

    display_name = " ".join((request.form.get("display_name") or "").split())[:120]
    incoming_file = request.files.get("file")
    if not display_name or not incoming_file or not incoming_file.filename:
        flash("Choisissez un fichier et indiquez le nom à afficher.", "error")
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id, private_documents=1) + "#miscDocumentsSection")

    try:
        stored_path = _store_file(session_id, trainee_id, "private_documents", incoming_file)
    except ValueError:
        flash("Ce type de fichier n’est pas autorisé.", "error")
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id, private_documents=1) + "#miscDocumentsSection")

    _private_documents(trainee).append({
        "id": uuid.uuid4().hex,
        "name": display_name,
        "file": _tokenize_path(stored_path),
        "original_name": secure_filename(incoming_file.filename),
        "uploaded_at": _now_iso(),
    })
    trainee["updated_at"] = _now_iso()
    append_trainee_history_event(trainee, "Document divers ajouté", display_name, "action")
    save_data(data)
    flash(f"Le document « {display_name} » a été ajouté.", "success")
    return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id, private_documents=1) + "#miscDocumentsSection")


@app.post("/admin/sessions/<session_id>/stagiaires/<trainee_id>/private-documents/<document_id>/delete")
@admin_login_required
@admin_write_required
def admin_delete_private_document(session_id: str, trainee_id: str, document_id: str):
    data = load_data()
    session_obj = find_session(data, session_id)
    if not session_obj:
        abort(404)
    trainee = next((item for item in _session_trainees_list(session_obj) if item.get("id") == trainee_id), None)
    if not trainee:
        abort(404)

    documents = _private_documents(trainee)
    document = next((item for item in documents if item.get("id") == document_id), None)
    if not document:
        abort(404)
    documents.remove(document)
    full_path = _detokenize_path(document.get("file") or "")
    if os.path.isfile(full_path):
        os.remove(full_path)
    trainee["updated_at"] = _now_iso()
    append_trainee_history_event(trainee, "Document divers supprimé", document.get("name") or "", "action")
    save_data(data)
    flash("Le document privé a été supprimé.", "success")
    return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id, private_documents=1) + "#miscDocumentsSection")


@app.get("/admin/sessions/<session_id>/stagiaires/<trainee_id>/private-documents/<document_id>")
@admin_login_required
def admin_view_private_document(session_id: str, trainee_id: str, document_id: str):
    data = load_data()
    session_obj = find_session(data, session_id)
    if not session_obj:
        abort(404)
    trainee = next((item for item in _session_trainees_list(session_obj) if item.get("id") == trainee_id), None)
    if not trainee:
        abort(404)
    document = next((item for item in _private_documents(trainee) if item.get("id") == document_id), None)
    if not document:
        abort(404)

    full_path = _detokenize_path(document.get("file") or "")
    if not os.path.isfile(full_path):
        abort(404)
    extension = _safe_ext(document.get("original_name") or full_path)
    download_name = secure_filename(document.get("name") or "document") + extension
    return send_file(full_path, as_attachment=False, download_name=download_name)


@app.get("/espace/<token>/download/<path:file_token>")
def public_download_file(token: str, file_token: str):
    data = load_data()
    s, t = find_session_and_trainee_by_token(data, token)
    if not s or not t:
        abort(404)

    # Sécurité : le fichier doit appartenir à CE stagiaire
    if not _token_belongs_to_trainee(t, file_token):
        abort(403)

    full = _detokenize_path(file_token)
    if not os.path.exists(full):
        abort(404)

    return send_file(full, as_attachment=False)


@app.get("/espace/<token>/factures/<line_id>")
def public_trainee_invoice_pdf(token: str, line_id: str):
    data = load_data()
    session_obj, trainee = find_session_and_trainee_by_token(data, token)
    if not session_obj or not trainee:
        abort(404)
    if not _public_is_authed(token):
        return redirect(url_for("public_trainee_login", token=token))

    line = _find_billing_line(data, line_id)
    if not line:
        abort(404)
    if str(line.get("sessionId") or "") != str(session_obj.get("id") or ""):
        abort(403)
    if str(line.get("traineeId") or "") != str(trainee.get("id") or trainee.get("trainee_id") or ""):
        abort(403)

    invoice_id = str(line.get("qontoInvoiceId") or line.get("qontoDraftId") or "").strip()
    if not invoice_id:
        abort(404)
    status = _normalize_billing_invoice_status(line.get("invoiceStatus"))
    if status not in {"draft", "finalized", "sent", "paid"}:
        abort(404)

    try:
        pdf_content, filename = fetch_qonto_client_invoice_pdf(invoice_id)
    except QontoConfigurationError:
        abort(503)
    except QontoNotFoundError:
        abort(404)
    except QontoPdfUnavailableError as exc:
        abort(getattr(exc, "status_code", 502), str(exc))

    safe_filename = secure_filename(filename) or f"facture-qonto-{secure_filename(invoice_id) or 'facture'}.pdf"
    return Response(
        pdf_content,
        mimetype="application/pdf",
        headers={
            "Content-Disposition": f'inline; filename="{safe_filename}"',
            "Cache-Control": "private, no-store",
        },
    )


def _public_trainee_last_names(trainee: Dict[str, Any]) -> set[str]:
    names = {
        _norm_lastname(trainee.get("last_name", "")),
        _norm_lastname(trainee.get("nom", "")),
        _norm_lastname(trainee.get("birth_name", "")),
        _norm_lastname(trainee.get("nom_naissance", "")),
        _norm_lastname(trainee.get("nom_usage", "")),
        _norm_lastname(trainee.get("name", "")),
    }
    return {name for name in names if name}


def _public_trainee_birth_dates(trainee: Dict[str, Any]) -> set[str]:
    dates = {
        _birth_to_ddmmyyyy(trainee.get("birth_date", "")),
        _birth_to_ddmmyyyy(trainee.get("date_naissance", "")),
        _birth_to_ddmmyyyy(trainee.get("dateNaissance", "")),
        _birth_to_ddmmyyyy(trainee.get("date_de_naissance", "")),
        _birth_to_ddmmyyyy(trainee.get("birthdate", "")),
        _birth_to_ddmmyyyy(trainee.get("dob", "")),
    }
    return {date for date in dates if date}


def _public_trainee_identity_matches(trainee: Dict[str, Any], last_name: str, birth: str) -> bool:
    expected_last = _norm_lastname(last_name)
    expected_birth = _birth_to_ddmmyyyy(birth)
    if not expected_last or not expected_birth:
        return False
    return expected_last in _public_trainee_last_names(trainee) and expected_birth in _public_trainee_birth_dates(trainee)


def _find_public_trainee_matches_by_identity(data: Dict[str, Any], last_name: str, birth: str) -> list[tuple[Dict[str, Any], Dict[str, Any]]]:
    """Retourne toutes les correspondances exactes nom normalisé + date normalisée."""
    expected_last = _norm_lastname(last_name)
    expected_birth = _birth_to_ddmmyyyy(birth)
    if not expected_last or not expected_birth:
        return []

    matches: list[tuple[Dict[str, Any], Dict[str, Any]]] = []
    for session_obj in data.get("sessions", []) or []:
        for trainee in _session_trainees_list(session_obj):
            trainee_token = (trainee.get("public_token") or trainee.get("token") or "").strip()
            if trainee_token and _public_trainee_identity_matches(trainee, last_name, birth):
                matches.append((session_obj, trainee))
    return matches


def _find_public_trainee_by_identity(data: Dict[str, Any], last_name: str, birth: str):
    """Retourne l'unique stagiaire correspondant au nom + date, sinon (None, None)."""
    matches = _find_public_trainee_matches_by_identity(data, last_name, birth)
    if len(matches) == 1:
        return matches[0]
    return None, None

def _public_login_debug_summary(
    data: Dict[str, Any], last_name: str, birth: str, *, limit: int = 8
) -> Dict[str, Any]:
    expected_last = _norm_lastname(last_name)
    expected_birth = _birth_to_ddmmyyyy(birth)
    summary: Dict[str, Any] = {
        "input_last_norm": expected_last,
        "input_birth_norm": expected_birth,
        "sessions_count": len(data.get("sessions", []) or []),
        "trainees_count": 0,
        "name_matches_count": 0,
        "birth_matches_count": 0,
        "name_birth_matches_count": 0,
        "matched_trainee_id": "",
        "matched_session_id": "",
        "matched_token_present": False,
        "near_matches": [],
    }

    near_matches = summary["near_matches"]
    for session_obj in data.get("sessions", []) or []:
        session_id = session_obj.get("id") or session_obj.get("name") or ""
        for trainee in _session_trainees_list(session_obj):
            summary["trainees_count"] += 1
            names = sorted(_public_trainee_last_names(trainee))
            dates = sorted(_public_trainee_birth_dates(trainee))
            name_match = bool(expected_last and expected_last in names)
            birth_match = bool(expected_birth and expected_birth in dates)
            if name_match:
                summary["name_matches_count"] += 1
            if birth_match:
                summary["birth_matches_count"] += 1
            if name_match and birth_match:
                summary["name_birth_matches_count"] += 1
                if not summary["matched_trainee_id"]:
                    summary["matched_trainee_id"] = trainee.get("id") or ""
                    summary["matched_session_id"] = session_id
                    summary["matched_token_present"] = bool((trainee.get("public_token") or trainee.get("token") or "").strip())
            if name_match or birth_match:
                if len(near_matches) < limit:
                    near_matches.append({
                        "session_id": session_id,
                        "trainee_id": trainee.get("id") or "",
                        "token_present": bool((trainee.get("public_token") or trainee.get("token") or "").strip()),
                        "name_match": name_match,
                        "birth_match": birth_match,
                        "names_norm": names,
                        "births_norm": dates,
                        "raw_last_name": trainee.get("last_name") or trainee.get("nom") or "",
                        "raw_birth_date": (
                            trainee.get("birth_date")
                            or trainee.get("date_naissance")
                            or trainee.get("dateNaissance")
                            or ""
                        ),
                    })
    return summary


