@app.post("/espace/<token>/login")
def public_trainee_login_post(token: str):
    # ✅ si admin connecté, bypass
    if session.get("admin_logged_in"):
        return redirect(url_for("public_trainee_space", token=token))

    data = load_data()
    s, t = find_session_and_trainee_by_token(data, token)
    if not s or not t:
        abort(404)

    last_in = (request.form.get("last_name") or "").strip()
    birth_in = (request.form.get("birth") or "").strip()

    app.logger.debug(
        "[PUBLIC_TOKEN_LOGIN_ATTEMPT] trainee_id=%s session_id=%s token_present=%s",
        t.get("id") or "",
        s.get("id") or s.get("name") or "",
        bool(token),
    )

    # 🔒 contrôle strict
    if _public_trainee_identity_matches(t, last_in, birth_in):
        session[f"public_auth_{token}"] = True
        _stamp_authenticated_session()
        session.permanent = True  # cookie persistant (comme admin)
        _mark_public_login(data, s, t)
        return redirect(url_for("public_trainee_space", token=token))

    app.logger.warning(
        "[PUBLIC_TOKEN_LOGIN_FAIL] token=%s trainee_id=%s last_name=%r birth_input=%r debug=%s",
        token,
        t.get("id") or "",
        last_in,
        birth_in,
        _public_login_debug_summary(
            {"sessions": [{"id": s.get("id") or s.get("name") or "", "trainees": [t]}]},
            last_in,
            birth_in,
        ),
    )
    return redirect(url_for("public_trainee_login", token=token, error="1"))



@app.post("/admin/sessions/<session_id>/stagiaires/<trainee_id>/documents/<doc_key>/upload")
@admin_login_required
@admin_write_required
def admin_upload_doc_file(session_id: str, trainee_id: str, doc_key: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        abort(404)

    trainees = _session_trainees_list(s)
    t = next((x for x in trainees if x.get("id") == trainee_id), None)
    if not t:
        abort(404)

    training_type = _session_get(s, "training_type", "")

    # ✅ s'assure que la liste de documents correspond à la formation (et supprime dom)
    ensure_documents_schema_for_trainee(t, training_type)
    if (training_type or "").strip().upper() == "DIRIGEANT VAE":
        _ensure_livret2_document_entry(t)
        _ensure_complementary_documents_entry(t)

    # ✅ refuse les doc_key inconnus pour cette formation
    if doc_key not in allowed_doc_keys_for_training(training_type, t):
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    f = request.files.get("file")
    if not f or not f.filename:
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    try:
        stored = _store_file(session_id, trainee_id, "documents", f)
    except Exception:
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    token = _tokenize_path(stored)

    docs = t.get("documents") or []
    target_doc = next((d for d in docs if isinstance(d, dict) and d.get("key") == doc_key), None)
    if target_doc is None:
        target_doc = {
            "key": doc_key,
            "label": doc_key.replace("_", " ").title(),
            "accept": "",
            "status": "NON DÉPOSÉ",
            "comment": "",
            "file": "",
            "files": [],
        }
        docs.append(target_doc)

    cur_files = target_doc.get("files")
    if not isinstance(cur_files, list):
        cur_files = []

    old = (target_doc.get("file") or "").strip()
    if old and old not in cur_files:
        cur_files.append(old)

    cur_files.append(token)

    target_doc["files"] = [x for x in cur_files if x]
    target_doc["file"] = target_doc["files"][0] if target_doc["files"] else ""

    cur = (target_doc.get("status") or "").strip().upper()
    if cur in ("", "NON DÉPOSÉ", "NON DEPOSE", "NON_DEPOSE"):
        target_doc["status"] = "A CONTRÔLER"
    if target_doc.get("status") == "A CONTROLER":
        target_doc["status"] = "A CONTRÔLER"

    t["updated_at"] = _now_iso()
    append_trainee_history_event(t, "Document ajouté", f"{doc_key} · fichier ajouté", "action")

    if doc_key == "complementary_documents":
        if not isinstance(t.get("vae_action_dates"), dict):
            t["vae_action_dates"] = {}
        t["vae_action_dates"]["complementary_documents_received"] = _now_paris_label()
        _mark_complementary_documents_to_control(t)
        target_doc["status"] = "A CONTRÔLER"
        _sync_complementary_document_tokens_from_document(t, target_doc)
        trainee_display_name = _format_trainee_name(t.get("first_name", ""), t.get("last_name", ""))
        add_admin_notification(
            data,
            f"VAE complément déposé par {trainee_display_name}",
            meta={
                "type": "vae_complementary_documents_upload",
                "session_id": s.get("id"),
                "trainee_id": t.get("id"),
            },
        )
        _notify_scotia_complementary_documents(t, s, 1, "l'espace administrateur")
        save_data(data)

    if doc_key == "livret_2":
        if not isinstance(t.get("vae_action_dates"), dict):
            t["vae_action_dates"] = {}
        t["vae_action_dates"]["livret_2_received"] = datetime.date.today().strftime("%d/%m/%Y")

        view = vae_status_view("livret_2_analysis")
        previous_status = (t.get("vae_status") or "").strip()
        t["vae_status"] = view["key"]
        t["vae_status_label"] = view["label"]

        if previous_status != view["key"]:
            _notify_vae_status_change(t, "livret_2_analysis")

        trainee_display_name = _format_trainee_name(t.get("first_name", ""), t.get("last_name", ""))
        add_admin_notification(
            data,
            f"VAE Livret 2️⃣ Importé pour {trainee_display_name}",
            meta={
                "type": "vae_livret_2_upload_admin",
                "session_id": s.get("id"),
                "trainee_id": t.get("id"),
            },
        )

    # ✅ recalcul dossier_status
    t["dossier_status"] = "complete" if dossier_is_complete_total(t, training_type, _session_get(s, "date_start", "")) else "incomplete"

    s["trainees"] = trainees
    s.pop("stagiaires", None)
    save_data(data)

    return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))


@app.post("/admin/sessions/<session_id>/stagiaires/<trainee_id>/test-fr/import")
@admin_login_required
@admin_write_required
def admin_import_test_fr_pdf(session_id: str, trainee_id: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        abort(404)

    trainees = _session_trainees_list(s)
    t = next((x for x in trainees if x.get("id") == trainee_id), None)
    if not t:
        abort(404)

    training_type = (s.get("training_type") or "").upper()
    if "APS" not in training_type and "A3P" not in training_type:
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    uploaded = request.files.get("file")
    if not uploaded or not uploaded.filename:
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    if not (uploaded.filename or "").lower().endswith(".pdf"):
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    try:
        stored = _store_file(session_id, trainee_id, "test_fr", uploaded)
    except Exception:
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    t["test_fr_file_token"] = _tokenize_path(stored)
    t["test_fr_imported_at"] = datetime.date.today().strftime("%Y-%m-%d")
    t["test_fr_status"] = "validated"
    t["updated_at"] = _now_iso()

    s["trainees"] = trainees
    s.pop("stagiaires", None)
    save_data(data)

    return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

@app.post("/admin/sessions/<session_id>/stagiaires/<trainee_id>/documents/<doc_key>/delete")
@admin_login_required
@admin_write_required
def admin_delete_doc_file(session_id: str, trainee_id: str, doc_key: str):
    data = load_data()
    _force_backup_snapshot(DATA_FILE)
    s = find_session(data, session_id)
    if not s:
        abort(404)

    trainees = _session_trainees_list(s)
    t = next((x for x in trainees if x.get("id") == trainee_id), None)
    if not t:
        abort(404)

    training_type = _session_get(s, "training_type", "")
    ensure_documents_schema_for_trainee(t, training_type)

    # sécurité: n'accepte que les doc_key requis
    if doc_key not in allowed_doc_keys_for_training(training_type, t):
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    docs = t.get("documents") or []
    target = next((d for d in docs if d.get("key") == doc_key), None)
    if not target:
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    file_token = (request.args.get("file_token") or "").strip()
    existing_files = [x for x in (target.get("files") or []) if x]
    if not existing_files:
        tok = (target.get("file") or "").strip()
        existing_files = [tok] if tok else []

    if file_token:
        tokens = [file_token] if file_token in existing_files else []
    else:
        tokens = list(existing_files)

    # suppression fichiers sur disque
    for tok in tokens:
        try:
            fp = _detokenize_path(tok)
            if os.path.exists(fp):
                _safe_remove_file(fp)
        except Exception:
            pass

    # reset du doc
    remaining = [x for x in existing_files if x not in tokens]
    target["files"] = remaining
    target["file"] = remaining[0] if remaining else ""
    if not remaining:
        target["status"] = "NON DÉPOSÉ"
    # on garde le commentaire (pratique), ou tu peux le vider si tu préfères

    t["updated_at"] = _now_iso()
    append_trainee_history_event(t, "Document supprimé", f"{doc_key} · {len(tokens)} fichier(s) supprimé(s)", "action")

    # recalcul dossier_status
    t["dossier_status"] = "complete" if dossier_is_complete_total(t, training_type, _session_get(s, "date_start", "")) else "incomplete"

    s["trainees"] = trainees
    s.pop("stagiaires", None)
    save_data(data)

    return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))




