@app.post("/admin/sessions/<session_id>/stagiaires/<trainee_id>/transfer")
@admin_login_required
@admin_write_required
def admin_transfer_trainee(session_id: str, trainee_id: str):
    data = load_data()
    _force_backup_snapshot(DATA_FILE)

    source_session = find_session(data, session_id)
    if not source_session:
        abort(404)

    target_session_id = (request.form.get("target_session_id") or "").strip()
    if not target_session_id:
        flash("Merci de sélectionner une session de destination.", "error")
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    if target_session_id == session_id:
        flash("La session de destination doit être différente de la session actuelle.", "error")
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    target_session = find_session(data, target_session_id)
    if not target_session or bool(target_session.get("archived")):
        flash("Session de destination introuvable ou archivée.", "error")
        return redirect(url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id))

    source_trainees = _session_trainees_list(source_session)
    trainee = next((x for x in source_trainees if x.get("id") == trainee_id), None)
    if not trainee:
        abort(404)

    source_session["trainees"] = [x for x in source_trainees if x.get("id") != trainee_id]
    source_session.pop("stagiaires", None)

    target_trainees = _session_trainees_list(target_session)
    target_trainees.insert(0, trainee)
    target_session["trainees"] = target_trainees
    target_session.pop("stagiaires", None)

    transferred_billing_lines = _transfer_trainee_billing_lines(
        data, trainee_id, session_id, target_session_id
    )

    target_training_type = _session_get(target_session, "training_type", "")
    ensure_documents_schema_for_trainee(trainee, target_training_type)
    trainee["dossier_status"] = "complete" if dossier_is_complete_total(trainee, target_training_type, _session_get(target_session, "date_start", "")) else "incomplete"
    trainee["updated_at"] = _now_iso()

    save_data(data)
    finance_message = (
        f" Les informations de facturation et de prélèvement ont été conservées ({transferred_billing_lines} ligne(s))."
        if transferred_billing_lines
        else ""
    )
    flash(f"Stagiaire transféré avec succès.{finance_message}", "success")
    return redirect(url_for("admin_trainees", session_id=target_session_id))

def _replace_in_docx(doc: Document, replacements: dict) -> None:
    def replace_in_paragraph(p):
        # Remplace dans les runs pour garder le style
        for run in p.runs:
            for k, v in replacements.items():
                if k in run.text:
                    run.text = run.text.replace(k, v)

    def replace_in_table(table):
        for row in table.rows:
            for cell in row.cells:
                for p in cell.paragraphs:
                    replace_in_paragraph(p)
                for t2 in cell.tables:
                    replace_in_table(t2)

    # Corps du document
    for p in doc.paragraphs:
        replace_in_paragraph(p)

    for table in doc.tables:
        replace_in_table(table)

    # ⚠️ Ne pas parcourir systématiquement section.header/footer ici.
    # Avec python-docx, le simple accès à ces propriétés peut créer des
    # parties header/footer absentes du template, et modifier la mise en page
    # (cas observé sur les étiquettes Word qui basculaient à 2 pages).


def _etiquette_template_name(training_type: str) -> Optional[str]:
    template_map = {
        "A3P": "etiquette_a3p.docx",
        "APS": "etiquette_aps.docx",
        "CHAUFFEUR VTC": "etiquette_vtc.docx",
        "VTC": "etiquette_vtc.docx",
        "DIRIGEANT": "etiquette_dirigeant_initial.docx",
        "DIRIGEANT INITIAL": "etiquette_dirigeant_initial.docx",
        "DIRIGEANT VAE": "etiquette_dirigeant.docx",
    }
    return template_map.get((training_type or "").strip().upper())


def _build_etiquette_docx_bytes(session_obj: Dict[str, Any], trainee: Dict[str, Any]) -> bytes:
    training_type = (_session_get(session_obj, "training_type", "") or "").strip().upper()
    template_name = _etiquette_template_name(training_type)
    if not template_name:
        abort(400, f"Aucun modèle Word prévu pour la formation : {training_type}")

    template_path = os.path.join("templates_word", template_name)
    if not os.path.exists(template_path):
        abort(500, f"Fichier Word manquant : {template_name} (dans /templates_word)")

    doc = Document(template_path)
    replacements = {
        "{{NOM}}": (trainee.get("last_name", "") or "").upper(),
        "{{PRENOM}}": (trainee.get("first_name", "") or "").upper(),
        "{{FORMATION}}": _session_get(session_obj, "name", ""),
        "{{TYPE_FORMATION}}": training_type,
        "{{DATES}}": f"{fr_date(_session_get(session_obj,'date_start',''))} → {fr_date(_session_get(session_obj,'date_end',''))}",
    }
    _replace_in_docx(doc, replacements)
    _enforce_etiquette_paper_source(doc)

    photo_token = (trainee.get("identity_photo") or "").strip()
    if photo_token:
        photo_path = _detokenize_path(photo_token)
        _insert_label_photo(doc, "{{PHOTO}}", photo_path, width_cm=5.41, height_cm=6.41)
    else:
        _replace_in_docx(doc, {"{{PHOTO}}": ""})

    _shrink_docx_trailing_empty_paragraphs(doc)

    buf = BytesIO()
    doc.save(buf)
    return buf.getvalue()


def _enforce_etiquette_paper_source(doc: Document) -> None:
    """
    Force la source papier Word en mode "étiquette" afin que l'impression
    cible le bac latéral par défaut quand l'imprimante est configurée ainsi.
    """
    # Valeur utilisée dans les modèles Word d'étiquette actuels.
    # On l'applique explicitement à chaque section pour éviter toute perte
    # de ce réglage lors de la génération python-docx.
    etiquette_tray_code = "261"

    for section in doc.sections:
        sect_pr = section._sectPr
        paper_src_nodes = sect_pr.xpath("./w:paperSrc")
        paper_src = paper_src_nodes[0] if paper_src_nodes else None
        if paper_src is None:
            paper_src = OxmlElement("w:paperSrc")
            sect_pr.append(paper_src)
        paper_src.set(qn("w:first"), etiquette_tray_code)
        paper_src.set(qn("w:other"), etiquette_tray_code)


def _shrink_docx_trailing_empty_paragraphs(doc: Document) -> None:
    """
    Les modèles d'étiquette remplissent quasiment toute la page.
    Word impose un paragraphe final après un tableau ; s'il garde sa mise en
    forme par défaut, il peut provoquer une 2e page vide après sauvegarde.
    """
    for paragraph in reversed(doc.paragraphs):
        if paragraph.text.strip():
            break

        paragraph.paragraph_format.space_before = Pt(0)
        paragraph.paragraph_format.space_after = Pt(0)
        paragraph.paragraph_format.line_spacing = 1
        paragraph.paragraph_format.left_indent = Pt(0)
        paragraph.paragraph_format.right_indent = Pt(0)
        paragraph.paragraph_format.first_line_indent = Pt(0)

        if not paragraph.runs:
            paragraph.add_run("")
        for run in paragraph.runs:
            run.text = ""
            run.font.size = Pt(1)




