VAE_ACTION_STATUS_ORDER = [
    ("livret_1_received", "livret_1_analysis"),
    ("livret_1_validated", "livret_1_validated"),
    ("financement_validated", "livret_2_todo"),
    ("livret_2_received", "livret_2_analysis"),
    ("livret_2_validated", "livret_2_validated"),
    ("financement_l2_validated", "financement_l2_validated"),
    ("jury_date", "jury"),
    ("diplome_obtenu", "certified"),
]
VAE_STATUS_RANK = {key: idx for idx, key in enumerate(VAE_STATUS_STEPS.keys())}


def _infer_vae_status_from_action_dates(action_dates: Any) -> Optional[str]:
    if not isinstance(action_dates, dict):
        return None
    inferred = None
    for action_key, status_key in VAE_ACTION_STATUS_ORDER:
        if action_dates.get(action_key):
            inferred = status_key
    return inferred


def _sync_vae_status_with_actions(trainee: Dict[str, Any]) -> None:
    """Maintient un statut VAE cohérent avec la dernière action validée."""
    current_key = vae_status_view(trainee.get("vae_status") or trainee.get("vae_status_label"))["key"]
    inferred_key = _infer_vae_status_from_action_dates(trainee.get("vae_action_dates"))
    chosen_key = current_key
    if inferred_key is not None and VAE_STATUS_RANK.get(inferred_key, -1) > VAE_STATUS_RANK.get(current_key, -1):
        chosen_key = inferred_key
    view = vae_status_view(chosen_key)
    trainee["vae_status"] = view["key"]
    trainee["vae_status_label"] = view["label"]


def _normalize_vae_status_text(value: Any) -> str:
    return " ".join(_normalized_token(str(value or "")).replace("_", " ").replace("-", " ").split())


def _sync_financement_status_from_manual_validation(trainee: Dict[str, Any]) -> None:
    """Aligne la pastille financement quand le statut financier manuel est validé."""
    manual_mode = (trainee.get("financing_validation_manual_mode") or "").strip().lower()
    manual_status = (trainee.get("financing_validation_manual_status") or "").strip().lower()
    if manual_mode == "manual" and manual_status == "validated":
        trainee["financement_status"] = "validated"


def vae_status_view(status_key: Optional[str]) -> Dict[str, str]:
    key = (status_key or "").strip()
    if key not in VAE_STATUS_STEPS:
        normalized_label = _normalize_vae_status_text(key)
        legacy_aliases = {
            "valide": "livret_1_validated",
            "validated": "livret_1_validated",
            "validation": "livret_1_validated",
            "livret 1 valide": "livret_1_validated",
            "non recevable": "non_recevable",
            "non receivable": "non_recevable",
            "financement valide": "financement_validated",
            "livret 2 a completer": "livret_2_todo",
            "certification obtenue": "certified",
            "certifie": "certified",
            "certifiee": "certified",
        }
        key = legacy_aliases.get(normalized_label) or next(
            (candidate_key for candidate_key, step in VAE_STATUS_STEPS.items() if _normalize_vae_status_text(step["label"]) == normalized_label),
            "livret_1_todo",
        )
    step = VAE_STATUS_STEPS[key]
    return {"key": key, "label": step["label"], "pill": step["pill"]}


