def _automation_has_end_attestation(session_obj: Dict[str, Any]) -> bool:
    return bool(_automation_document_config(session_obj).get("end_template"))


# =========================
# Yousign integration (server-side only)
# =========================
YOUSIGN_BASE_URL_DEFAULT = "https://api-sandbox.yousign.app/v3"

YOUSIGN_SMART_ANCHOR_PATTERN = re.compile(r"\{\{\s*s(\d+)\|signature\|(\d+)\|(\d+)\s*\}\}")
YOUSIGN_TECHNICAL_ANCHOR_PATTERN = re.compile(r"\{\{\s*s(\d+)\|([A-Za-z0-9_\-]+)\|([^{}]*)\}\}")
YOUSIGN_SMART_ANCHOR_MISSING_MESSAGE = "Aucune zone de signature trouvée dans le modèle Word. Ajoutez {{s1|signature|160|60}} à l’endroit souhaité."
YOUSIGN_SMART_ANCHOR_PLACEHOLDER_PREFIX = "__YOUSIGN_SMART_ANCHOR_"
YOUSIGN_SMS_AUTHENTICATION_MODE = "otp_sms"
YOUSIGN_SMS_PHONE_ERROR_MESSAGE = "Impossible d’envoyer la convention : numéro de téléphone manquant ou invalide pour l’authentification SMS Yousign."


def _docx_xml_names(zf: zipfile.ZipFile) -> List[str]:
    return [name for name in zf.namelist() if name.startswith("word/") and name.endswith(".xml")]


def _docx_yousign_smart_anchors(docx_path: str, signer_index: Optional[int] = None) -> List[str]:
    anchors: List[str] = []
    seen = set()
    expected_signer = str(signer_index) if signer_index is not None else ""

    def collect(text: str) -> None:
        for match in YOUSIGN_SMART_ANCHOR_PATTERN.finditer(text):
            if expected_signer and match.group(1) != expected_signer:
                continue
            anchor = match.group(0)
            if anchor not in seen:
                seen.add(anchor)
                anchors.append(anchor)

    try:
        with zipfile.ZipFile(docx_path) as zf:
            for name in _docx_xml_names(zf):
                xml_text = zf.read(name).decode("utf-8", errors="ignore")
                collect(xml_text)
                try:
                    plain_text = "".join(ET.fromstring(xml_text).itertext())
                    collect(plain_text)
                except Exception:
                    pass
    except zipfile.BadZipFile:
        return []
    return anchors


def _docx_text_contains_yousign_smart_anchor(docx_path: str, signer_index: int = 1) -> bool:
    return bool(_docx_yousign_smart_anchors(docx_path, signer_index=signer_index))


def _rewrite_docx_xml(docx_path: str, rewrite) -> None:
    tmp_path = docx_path + ".tmp"
    with zipfile.ZipFile(docx_path, "r") as zin, zipfile.ZipFile(tmp_path, "w") as zout:
        for item in zin.infolist():
            data = zin.read(item.filename)
            if item.filename.startswith("word/") and item.filename.endswith(".xml"):
                text = data.decode("utf-8", errors="ignore")
                data = rewrite(text).encode("utf-8")
            zout.writestr(item, data)
    os.replace(tmp_path, docx_path)


def _protect_yousign_smart_anchors_in_docx(docx_path: str) -> Dict[str, str]:
    replacements: Dict[str, str] = {}

    def rewrite(xml_text: str) -> str:
        def replace(match: re.Match) -> str:
            anchor = match.group(0)
            token = f"{YOUSIGN_SMART_ANCHOR_PLACEHOLDER_PREFIX}{len(replacements)}__"
            replacements[token] = anchor
            return token
        return YOUSIGN_SMART_ANCHOR_PATTERN.sub(replace, xml_text)

    _rewrite_docx_xml(docx_path, rewrite)
    return replacements


def _restore_yousign_smart_anchors_in_docx(docx_path: str, replacements: Dict[str, str]) -> None:
    if not replacements:
        return

    def rewrite(xml_text: str) -> str:
        for token, anchor in replacements.items():
            xml_text = xml_text.replace(token, anchor)
        return xml_text

    _rewrite_docx_xml(docx_path, rewrite)


def _is_production_environment() -> bool:
    markers = (
        os.environ.get("FLASK_ENV"),
        os.environ.get("APP_ENV"),
        os.environ.get("ENV"),
        os.environ.get("RENDER_ENV"),
    )
    return any(str(value or "").strip().lower() == "production" for value in markers)


def _yousign_configured_environment() -> str:
    configured = (os.environ.get("YOUSIGN_ENV") or os.environ.get("YOUSIGN_ENVIRONMENT") or "").strip().lower()
    if configured in {"prod", "production", "live"}:
        return "production"
    if configured in {"sandbox", "test", "testing"}:
        return "sandbox"
    return ""


def _yousign_expected_environment() -> str:
    configured_environment = _yousign_configured_environment()
    if configured_environment:
        return configured_environment
    api_key = _yousign_api_key().lower()
    if "sandbox" in api_key:
        return "sandbox"
    if "production" in api_key or "prod" in api_key or "live" in api_key:
        return "production"
    return "production" if _is_production_environment() else ""


def _yousign_environment_from_base_url(base_url: str) -> str:
    return "sandbox" if "api-sandbox.yousign.app" in base_url else "production"


def _yousign_base_url() -> str:
    base_url = (os.environ.get("YOUSIGN_BASE_URL") or YOUSIGN_BASE_URL_DEFAULT).strip().rstrip("/")
    allowed_urls = {"https://api-sandbox.yousign.app/v3", "https://api.yousign.app/v3"}
    if base_url not in allowed_urls:
        raise RuntimeError("Configuration Yousign invalide : utilisez https://api.yousign.app/v3 en production ou https://api-sandbox.yousign.app/v3 en test.")
    url_environment = _yousign_environment_from_base_url(base_url)
    expected_environment = _yousign_expected_environment()
    if expected_environment and url_environment != expected_environment:
        raise RuntimeError(f"Configuration Yousign invalide : l’URL API {base_url} ne correspond pas à l’environnement {expected_environment}.")
    if _is_production_environment() and url_environment == "sandbox":
        raise RuntimeError("Configuration Yousign invalide : l’URL sandbox est interdite en production.")
    return base_url


def _yousign_environment() -> str:
    return _yousign_environment_from_base_url(_yousign_base_url())


def _yousign_api_key() -> str:
    return (os.environ.get("YOUSIGN_API_KEY") or "").strip()


def _yousign_is_configured() -> bool:
    return bool(_yousign_api_key() and (os.environ.get("YOUSIGN_WEBHOOK_SECRET") or "").strip())


def _yousign_headers() -> Dict[str, str]:
    api_key = _yousign_api_key()
    if not api_key:
        raise RuntimeError("Yousign n’est pas configuré : variable Render YOUSIGN_API_KEY manquante.")
    _yousign_base_url()
    return {"Authorization": f"Bearer {api_key}", "Accept": "application/json"}


def _sanitize_yousign_error(message: Any) -> str:
    text = str(message or "Erreur Yousign inconnue")
    api_key = _yousign_api_key()
    if api_key:
        text = text.replace(api_key, "***")
    text = re.sub(r"https://[^\\s\"'<>]+", "[lien masqué]", text)
    return text[:800]



def _normalize_yousign_sms_phone(raw_phone: Any) -> str:
    raw = str(raw_phone or "").strip()
    if not raw:
        return ""
    compact = re.sub(r"[\s.()\-]", "", raw)
    if compact.startswith("00"):
        compact = "+" + compact[2:]
    elif compact.startswith("0") and re.fullmatch(r"0[67]\d{8}", compact):
        compact = "+33" + compact[1:]
    if not re.fullmatch(r"\+[1-9]\d{7,14}", compact):
        return ""
    return compact


def _mask_phone_for_logs(phone: Any) -> str:
    value = str(phone or "")
    if len(value) <= 5:
        return "***" if value else ""
    return f"{value[:3]}***{value[-2:]}"

def make_yousign_external_id(session_id: str, trainee_id: str) -> str:
    raw = f"convocation_{session_id}_{trainee_id}"
    return re.sub(r"[^A-Za-z0-9_\-@.%+ ]", "_", raw)


YOUSIGN_RATE_LIMIT_MAX_RETRIES = 2
YOUSIGN_RATE_LIMIT_RETRY_DELAY_SECONDS = 1.0


def _yousign_rate_limit_retry_delay(response: requests.Response, retry_number: int) -> float:
    """Return a bounded delay while honoring Yousign's Retry-After header."""
    retry_after = str(response.headers.get("Retry-After") or "").strip()
    try:
        if retry_after:
            return min(10.0, max(0.0, float(retry_after)))
    except (TypeError, ValueError):
        pass
    return YOUSIGN_RATE_LIMIT_RETRY_DELAY_SECONDS * retry_number


def _yousign_request(method: str, path: str, **kwargs) -> requests.Response:
    url = f"{_yousign_base_url()}/{path.lstrip('/')}"
    headers = dict(_yousign_headers())
    headers.update(kwargs.pop("headers", {}) or {})
    response = None
    for attempt in range(YOUSIGN_RATE_LIMIT_MAX_RETRIES + 1):
        response = requests.request(method.upper(), url, headers=headers, timeout=30, **kwargs)
        if response.status_code != 429:
            break
        if attempt == YOUSIGN_RATE_LIMIT_MAX_RETRIES:
            raise RuntimeError("Yousign limite temporairement les demandes. Réessayez dans quelques instants.")
        delay = _yousign_rate_limit_retry_delay(response, attempt + 1)
        app.logger.warning(
            "[YOUSIGN] rate limited method=%s path=%s retry=%s delay_seconds=%.1f",
            method.upper(), path, attempt + 1, delay,
        )
        time.sleep(delay)
    assert response is not None
    if response.status_code >= 400:
        try:
            detail = response.json()
        except Exception:
            detail = response.text
        raise RuntimeError(f"Erreur Yousign HTTP {response.status_code}: {_sanitize_yousign_error(detail)}")
    return response


def _yousign_json(method: str, path: str, **kwargs) -> Dict[str, Any]:
    response = _yousign_request(method, path, **kwargs)
    if not response.content:
        return {}
    return response.json()


def _parse_yousign_anchor(anchor_text: str) -> Dict[str, Any]:
    match = YOUSIGN_TECHNICAL_ANCHOR_PATTERN.fullmatch(str(anchor_text or "").strip())
    if not match:
        return {}
    args = [part.strip() for part in (match.group(3) or "").split("|")]
    width = int(args[0]) if len(args) >= 1 and args[0].isdigit() else 160
    height = int(args[1]) if len(args) >= 2 and args[1].isdigit() else 60
    return {"signer_index": int(match.group(1)), "type": match.group(2).strip().lower(), "width": width, "height": height}


def _detect_yousign_pdf_anchors(pdf_path: str, signer_index: int = 1) -> List[Dict[str, Any]]:
    """Detect Yousign technical tags in the generated PDF before cleaning it."""
    anchors: List[Dict[str, Any]] = []
    pattern = YOUSIGN_TECHNICAL_ANCHOR_PATTERN
    reader = PdfReader(pdf_path)
    for page_number, page in enumerate(reader.pages, start=1):
        page_height = float(page.mediabox.height)

        def visitor(text: str, cm: Any, tm: Any, font_dict: Any, font_size: Any) -> None:
            if not text or "{{" not in text:
                return
            for match in pattern.finditer(text):
                parsed = _parse_yousign_anchor(match.group(0))
                if not parsed or parsed["signer_index"] != signer_index:
                    continue
                x = float(tm[4] if len(tm) > 4 else 0) + float(cm[4] if len(cm) > 4 else 0)
                baseline_y = float(tm[5] if len(tm) > 5 else 0) + float(cm[5] if len(cm) > 5 else 0)
                height = parsed["height"]
                anchors.append({
                    **parsed,
                    "raw": match.group(0),
                    "page": page_number,
                    "x": max(0, int(round(x))),
                    "pdf_y": max(0, float(baseline_y) - 2),
                    "y": max(0, int(round(page_height - baseline_y - height))),
                })

        page.extract_text(visitor_text=visitor)
    return anchors


def _clean_yousign_pdf_anchors(pdf_path: str, anchors: List[Dict[str, Any]]) -> str:
    """Create a clean PDF by masking every detected technical Yousign tag."""
    if not anchors:
        return pdf_path
    from reportlab.pdfgen import canvas
    from pypdf.generic import ContentStream, NameObject

    clean_path = os.path.splitext(pdf_path)[0] + "_clean.pdf"
    reader = PdfReader(pdf_path)
    writer = PdfWriter()
    anchors_by_page: Dict[int, List[Dict[str, Any]]] = {}
    for anchor in anchors:
        anchors_by_page.setdefault(int(anchor.get("page") or 1), []).append(anchor)
    for page_number, page in enumerate(reader.pages, start=1):
        page_width = float(page.mediabox.width)
        page_height = float(page.mediabox.height)
        packet = BytesIO()
        overlay = canvas.Canvas(packet, pagesize=(page_width, page_height))
        overlay.setFillColorRGB(1, 1, 1)
        for anchor in anchors_by_page.get(page_number, []):
            # Mask the visible marker text, not the future signature area.
            text_width = max(80, min(page_width - float(anchor["x"]), len(anchor["raw"]) * 7))
            overlay.rect(float(anchor["x"]) - 1, float(anchor["pdf_y"]) - 1, text_width + 2, 16, stroke=0, fill=1)
        overlay.save()
        packet.seek(0)
        overlay_page = PdfReader(packet).pages[0]
        page.merge_page(overlay_page)
        raw_anchors = {str(anchor.get("raw") or "") for anchor in anchors_by_page.get(page_number, [])}
        if raw_anchors:
            try:
                content = ContentStream(page.get_contents(), reader)
                filtered_operations = []
                for operands, operator in content.operations:
                    operand_text = "".join(str(operand) for operand in operands)
                    if any(raw_anchor and raw_anchor in operand_text for raw_anchor in raw_anchors):
                        continue
                    filtered_operations.append((operands, operator))
                content.operations = filtered_operations
                page[NameObject("/Contents")] = content
            except Exception:
                app.logger.warning("[YOUSIGN] impossible de retirer le texte d’ancre du flux PDF, masquage visuel conservé", exc_info=True)
        writer.add_page(page)
    with open(clean_path, "wb") as fh:
        writer.write(fh)
    return clean_path


def _prepare_yousign_pdf_and_fields(pdf_path: str, signer_index: int = 1) -> Tuple[str, List[Dict[str, Any]]]:
    anchors = _detect_yousign_pdf_anchors(pdf_path, signer_index=signer_index)
    if not anchors:
        return pdf_path, []
    clean_path = _clean_yousign_pdf_anchors(pdf_path, anchors)
    return clean_path, anchors


def _yousign_state(trainee: Dict[str, Any]) -> Dict[str, Any]:
    """Return the Yousign convention state, keeping legacy convocation data readable."""
    state = trainee.get("convention_signature") if isinstance(trainee.get("convention_signature"), dict) else None
    legacy_state = trainee.get("convocation_signature") if isinstance(trainee.get("convocation_signature"), dict) else None
    if state is None:
        state = legacy_state or {}
    trainee["convention_signature"] = state
    # Compatibility: old production records and older code paths still read this key.
    trainee["convocation_signature"] = state
    return state


def _extract_yousign_signature_link(payload: Dict[str, Any], signer_id: str = "") -> str:
    candidates = []
    if isinstance(payload, dict):
        candidates.append(payload)
        candidates.extend(payload.get("signers") or [])
    for item in candidates:
        if not isinstance(item, dict):
            continue
        if signer_id and str(item.get("id") or "") not in {"", signer_id}:
            continue
        for key in ("signature_link", "signature_link_url", "signing_url", "signature_url"):
            if item.get(key):
                return str(item.get(key))
        link = item.get("link") if isinstance(item.get("link"), dict) else {}
        if link.get("url"):
            return str(link.get("url"))
    return ""


def _aps_session_dates_label(session_obj: Dict[str, Any]) -> str:
    date_start = fr_date(_session_get(session_obj, "date_start", ""))
    date_end = fr_date(_session_get(session_obj, "date_end", ""))
    if date_start and date_end and date_end != date_start:
        return f"{date_start} au {date_end}"
    return date_start or date_end or "—"


YOUSIGN_PENDING_STATUSES = {"ongoing", "activated", "pending", "en_attente", "en attente", "en attente de signature"}
YOUSIGN_FINAL_STATUSES = {"done", "signed"}
YOUSIGN_STOP_REMINDER_STATUSES = {"declined", "expired", "canceled", "cancelled", "error", "download_error"}


def _normalize_yousign_status(status: Any) -> str:
    return str(status or "").strip().lower().replace("-", "_")


def _is_yousign_signature_pending(state: Dict[str, Any]) -> bool:
    return _normalize_yousign_status(state.get("status")) in YOUSIGN_PENDING_STATUSES


def _is_yousign_signature_done(state: Dict[str, Any]) -> bool:
    return _normalize_yousign_status(state.get("status")) in YOUSIGN_FINAL_STATUSES


def _has_legacy_signed_convention(trainee: Dict[str, Any]) -> bool:
    return bool(trainee.get("convention_legacy_signed") or trainee.get("legacy_convention_signed"))


def _sync_convention_status_from_yousign(trainee: Dict[str, Any]) -> bool:
    """Keep the admin trainees convention dot aligned with the Yousign automation state."""
    state = _yousign_state(trainee)
    signed_at = state.get("signed_at") or trainee.get("convention_aps_signed_at") or trainee.get("convention_legacy_signed_at") or ""
    if not (_is_yousign_signature_done(state) or signed_at or _has_legacy_signed_convention(trainee)):
        return False
    if trainee.get("convention_status") == "signed":
        return False
    trainee["convention_status"] = "signed"
    return True


def _yousign_payload_signature_request(payload: Dict[str, Any]) -> Dict[str, Any]:
    data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
    signature_request = data.get("signature_request") if isinstance(data.get("signature_request"), dict) else {}
    if signature_request:
        return signature_request
    return payload if isinstance(payload, dict) else {}


def _yousign_signature_request_status(payload: Dict[str, Any]) -> str:
    signature_request = _yousign_payload_signature_request(payload)
    return _normalize_yousign_status(signature_request.get("status"))


def _is_yousign_signature_stopped(state: Dict[str, Any]) -> bool:
    return _normalize_yousign_status(state.get("status")) in YOUSIGN_STOP_REMINDER_STATUSES


def _yousign_signature_link_is_expired(state: Dict[str, Any]) -> bool:
    expires_at = _parse_iso_datetime(state.get("signature_link_expires_at"))
    return bool(expires_at and expires_at <= datetime.datetime.utcnow())


def _convention_signature_admin_label(state: Dict[str, Any]) -> str:
    if not state or not state.get("signature_request_id"):
        return "Non envoyée"
    if _is_yousign_signature_done(state):
        return "Signée"
    if _is_yousign_signature_stopped(state) or _yousign_signature_link_is_expired(state):
        return "Expirée / refusée / erreur"
    if _is_yousign_signature_pending(state):
        count = int(state.get("reminder_count") or 0)
        if count:
            return f"{count} rappel{'s' if count > 1 else ''} envoyé{'s' if count > 1 else ''}"
        return "En attente de signature"
    return "Non envoyée"


def _build_yousign_signature_reminder_email(session_obj: Dict[str, Any], trainee: Dict[str, Any], signature_link: str) -> Tuple[str, str, str]:
    first_name = str(trainee.get("first_name") or "").strip() or "Madame, Monsieur"
    training_name = _signature_email_training_label(session_obj)
    dates_session = _aps_session_dates_label(session_obj)
    subject = "Rappel : votre convention de formation est en attente de signature"
    text_body = f"""Bonjour {first_name},

Nous vous rappelons que votre convention de formation est toujours en attente de signature.

Merci de la signer électroniquement en cliquant sur le lien ci-dessous :

{signature_link}

Formation : {training_name}
Session : {dates_session}

Cette signature concerne votre convention de formation.

Cordialement,

Intégrale Academy
54 chemin du Carreou
83480 Puget-sur-Argens
04 22 47 07 68"""
    html_body = build_signature_email_html(first_name, training_name, dates_session, signature_link, reminder=True)
    return subject, html_body, text_body


def _convention_reminders_allowed_now(now_utc: Optional[datetime.datetime] = None) -> bool:
    """Keep all convention reminders inside the 08:00-20:00 Europe/Paris window."""
    current = now_utc or datetime.datetime.now(datetime.timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=datetime.timezone.utc)
    paris_hour = current.astimezone(ZoneInfo("Europe/Paris")).hour
    return 8 <= paris_hour < 20


def _find_trainee_by_convocation_signature_id(data: Dict[str, Any], signature_id: str):
    wanted = str(signature_id or "").strip()
    for sess in data.get("sessions", []):
        trainees = _session_trainees_list(sess)
        for trainee in trainees:
            state = _yousign_state(trainee)
            if wanted in {str(trainee.get("id") or ""), str(state.get("signature_request_id") or ""), str(state.get("external_id") or "")}:
                return sess, trainees, trainee, state
    return None, None, None, None


def send_convocation_signature_reminder(signature_id: str) -> Tuple[bool, str]:
    if not _convention_reminders_allowed_now():
        return False, "Les rappels sont envoyés uniquement entre 8 h et 20 h (heure française)."
    data = load_data()
    sess, trainees, trainee, state = _find_trainee_by_convocation_signature_id(data, signature_id)
    if not trainee or not state:
        return False, "Signature introuvable."
    state = _yousign_state(trainee)
    if _is_yousign_signature_done(state):
        state["next_reminder_at"] = ""
        save_data(data)
        return False, "Convention déjà signée, aucun rappel nécessaire."
    if _is_yousign_signature_stopped(state):
        state["next_reminder_at"] = ""
        save_data(data)
        return False, "Convention expirée, refusée ou en erreur."
    if not _is_yousign_signature_pending(state):
        return False, "Convention non en attente de signature."
    signature_link = str(state.get("signature_link") or "").strip()
    if not signature_link:
        return False, "Aucun lien de signature disponible."
    if _yousign_signature_link_is_expired(state):
        state["status"] = "expired"
        state["next_reminder_at"] = ""
        state["last_email_error"] = "Lien de signature expiré : recréez une demande Yousign."
        trainee["updated_at"] = _now_iso()
        sess["trainees"] = trainees
        sess.pop("stagiaires", None)
        save_data(data)
        return False, "Lien de signature expiré : recréez une demande Yousign."
    if not str(trainee.get("email") or "").strip():
        return False, "Adresse e-mail stagiaire manquante."
    reminder_count = int(state.get("reminder_count") or 0)
    subject, html_body, text_body = _build_yousign_signature_reminder_email(sess, trainee, signature_link)
    now = _now_iso()
    try:
        phone = str(trainee.get("phone") or "").strip()
        if not phone:
            raise RuntimeError("Numéro de téléphone stagiaire manquant, rappel non envoyé")
        ok = brevo_send_email(str(trainee.get("email") or "").strip(), subject, html_body, trainee=trainee, text_content=text_body)
        if not ok:
            raise RuntimeError("Échec d’envoi e-mail")
        training_name = _signature_email_training_label(sess)
        sms = (
            f"Intégrale Academy : rappel, votre convention de formation {training_name} "
            f"est toujours à signer. Signez-la ici : {signature_link}"
        )
        if not brevo_send_sms(phone, sms):
            raise RuntimeError("Échec d’envoi SMS")
        new_count = reminder_count + 1
        state["reminder_count"] = new_count
        state["last_reminder_sent_at"] = now
        state[f"reminder_{new_count}_sent_at"] = now
        state["last_email_error"] = ""
        state["next_reminder_at"] = _add_days_iso(now, 1)
        trainee["updated_at"] = now
        sess["trainees"] = trainees
        sess.pop("stagiaires", None)
        save_data(data)
        return True, "Rappel envoyé au stagiaire."
    except Exception as exc:
        message = _sanitize_yousign_error(str(exc) or "Échec d’envoi e-mail")
        state["last_email_error"] = message
        trainee["updated_at"] = now
        sess["trainees"] = trainees
        sess.pop("stagiaires", None)
        save_data(data)
        return False, message


def _run_convocation_signature_reminders(
    now_utc: Optional[datetime.datetime] = None,
) -> Dict[str, int]:
    current = now_utc or datetime.datetime.utcnow()
    if current.tzinfo is not None:
        current = current.astimezone(datetime.timezone.utc).replace(tzinfo=None)
    if not _convention_reminders_allowed_now(current):
        return {"checked": 0, "sent": 0, "failed": 0}
    data = load_data()
    due_ids = []
    for sess in data.get("sessions", []):
        for trainee in _session_trainees_list(sess):
            state = _yousign_state(trainee)
            due_at = _parse_iso_datetime(state.get("next_reminder_at"))
            if _is_yousign_signature_pending(state) and due_at and due_at <= current:
                due_ids.append(str(trainee.get("id") or state.get("signature_request_id") or ""))
    sent = failed = 0
    for signature_id in due_ids:
        ok, _ = send_convocation_signature_reminder(signature_id)
        if ok:
            sent += 1
        else:
            failed += 1
    return {"checked": len(due_ids), "sent": sent, "failed": failed}


def run_convocation_signature_reminders(
    now_utc: Optional[datetime.datetime] = None,
) -> Dict[str, Any]:
    """Run due Yousign signature reminders once, whichever scheduler called it."""
    if not _convention_signature_reminders_lock.acquire(blocking=False):
        app.logger.info("[CONVENTION_SIGNATURE_REMINDERS] already_running")
        return {"status": "already_running", "checked": 0, "sent": 0, "failed": 0}
    try:
        return _run_convocation_signature_reminders(now_utc)
    finally:
        _convention_signature_reminders_lock.release()


