def _remove_automation_generated_file(path: Any) -> None:
    """Remove a generated automation file without ever deleting an arbitrary path."""
    raw_path = str(path or "").strip()
    if not raw_path:
        return
    try:
        real_path = os.path.realpath(raw_path)
        allowed_dirs = (APS_CONVOCATION_DIR, APS_ENTRY_ATTESTATION_DIR, APS_END_ATTESTATION_DIR, YOUSIGN_CONVENTION_DIR, YOUSIGN_SIGNED_DIR)
        if any(os.path.commonpath((real_path, os.path.realpath(directory))) == os.path.realpath(directory) for directory in allowed_dirs) and os.path.isfile(real_path):
            os.remove(real_path)
    except (OSError, ValueError):
        app.logger.warning("[AUTOMATIONS] impossible de supprimer le fichier généré %s", raw_path, exc_info=True)


def _reset_trainee_automations(trainee: Dict[str, Any]) -> None:
    """Return one trainee's document automations to their initial state."""
    state = _yousign_state(trainee)
    request_id = str(state.get("signature_request_id") or "").strip()
    if request_id and _is_yousign_signature_pending(state) and _yousign_is_configured():
        _yousign_json("POST", f"/signature_requests/{request_id}/cancel", json={
            "reason": "other",
            "custom_note": "Remise à zéro des automatisations depuis la fiche stagiaire.",
        })

    generated_paths = [
        state.get("unsigned_pdf_path"), state.get("source_pdf_with_anchors_path"), state.get("unsigned_docx_path"), state.get("signed_pdf_path"),
        *(trainee.get(key) for key in AUTOMATION_TRAINEE_FIELDS if key.endswith(("_pdf_path", "_docx_path"))),
    ]
    for path in generated_paths:
        _remove_automation_generated_file(path)
    for key in AUTOMATION_TRAINEE_FIELDS:
        trainee.pop(key, None)
    trainee["updated_at"] = _now_iso()


def create_yousign_convention_signature(session_obj: Dict[str, Any], trainee: Dict[str, Any], session_id: str, trainee_id: str, force_new: bool = False) -> Dict[str, Any]:
    existing_state = _yousign_state(trainee)
    has_existing_request = bool(existing_state.get("signature_request_id"))
    has_active_link = bool(existing_state.get("signature_link"))
    existing_status = _normalize_yousign_status(existing_state.get("status"))
    if has_existing_request and has_active_link and existing_status in {"ongoing", "activated"} and not force_new:
        return existing_state
    if force_new and has_existing_request:
        _cancel_yousign_convention_signature(trainee, "other")
    if not _yousign_is_configured():
        raise RuntimeError("Yousign Sandbox n’est pas configuré : vérifiez YOUSIGN_API_KEY et YOUSIGN_WEBHOOK_SECRET dans Render.")
    email = str(trainee.get("email") or "").strip()
    first_name = str(trainee.get("first_name") or "").strip()
    last_name = str(trainee.get("last_name") or "").strip()
    sms_phone = _normalize_yousign_sms_phone(trainee.get("phone"))
    if not email:
        raise RuntimeError("Adresse e-mail stagiaire manquante, impossible d’envoyer le lien de signature.")
    if not first_name or not last_name:
        raise RuntimeError("Prénom et nom du stagiaire sont obligatoires pour créer la signature Yousign.")
    if not sms_phone:
        raise RuntimeError(YOUSIGN_SMS_PHONE_ERROR_MESSAGE)

    docx_path, pdf_path = _generate_aps_convention_files(session_obj, trainee, session_id, trainee_id)
    if not os.path.exists(pdf_path) or os.path.getsize(pdf_path) <= 0:
        raise RuntimeError("Le PDF de convention de formation n’a pas été généré.")
    yousign_pdf_path, pdf_anchors = _prepare_yousign_pdf_and_fields(pdf_path, signer_index=1)
    if not os.path.exists(yousign_pdf_path) or os.path.getsize(yousign_pdf_path) <= 0:
        raise RuntimeError("Le PDF nettoyé pour Yousign n’a pas été généré.")

    training_label = str(_session_get(session_obj, "training_type", "") or _session_get(session_obj, "name", "") or "Formation").strip()
    request_name = f"Convention formation - {training_label} - {first_name} {last_name}".strip()
    external_id = make_yousign_external_id(session_id, trainee_id)
    yousign_environment = _yousign_environment()
    app.logger.info("[YOUSIGN] create signature request trainee_id=%s environment=%s", trainee_id, yousign_environment)
    signature_request = _yousign_json("POST", "/signature_requests", json={
        "name": request_name,
        "delivery_mode": "none",
        "timezone": "Europe/Paris",
        "external_id": external_id,
    })
    signature_request_id = signature_request.get("id")
    if not signature_request_id:
        raise RuntimeError("Yousign n’a pas renvoyé d’identifiant de demande de signature.")

    with open(yousign_pdf_path, "rb") as fh:
        document = _yousign_json(
            "POST",
            f"/signature_requests/{signature_request_id}/documents",
            files={"file": (os.path.basename(yousign_pdf_path), fh, "application/pdf")},
            data={"nature": "signable_document", "parse_anchors": "false"},
        )
    document_id = document.get("id")
    if not document_id:
        raise RuntimeError("Yousign n’a pas renvoyé d’identifiant de document.")

    signer_payload = {
        "info": {"first_name": first_name, "last_name": last_name, "email": email, "phone_number": sms_phone, "locale": "fr"},
        "signature_level": "electronic_signature",
        "signature_authentication_mode": YOUSIGN_SMS_AUTHENTICATION_MODE,
    }
    fields: List[Dict[str, Any]] = []
    for anchor in pdf_anchors:
        if anchor.get("type") == "signature":
            fields.append({
                "document_id": document_id,
                "type": "signature",
                "page": anchor["page"],
                "x": anchor["x"],
                "y": anchor["y"],
                "width": anchor["width"],
                "height": max(80, int(anchor["height"])),
                "layout": "detailed",
                "date_time_format": "dd/MM/yyyy",
                "show_timezone": False,
            })
        elif anchor.get("type") in {"date", "signature_date"}:
            # Yousign v3 no longer accepts a dedicated "signature_date" field type.
            # The detailed signature field already carries the signing date through
            # its date_time_format option, so date-only anchors are only cleaned from
            # the PDF and must not be sent as signer fields.
            continue
    if not fields:
        fields.append({
            "document_id": document_id,
            "type": "signature",
            "page": _pdf_page_count(yousign_pdf_path),
            "x": 360,
            "y": 650,
            "layout": "detailed",
            "date_time_format": "dd/MM/yyyy",
            "show_timezone": False,
        })
    signer_payload["fields"] = fields
    signer = _yousign_json("POST", f"/signature_requests/{signature_request_id}/signers", json=signer_payload)
    signer_id = signer.get("id")
    app.logger.info(
        "[YOUSIGN] signer created signature_request_id=%s signer_id=%s signature_authentication_mode=%s phone=%s environment=%s",
        signature_request_id, signer_id or "", signer_payload["signature_authentication_mode"], _mask_phone_for_logs(sms_phone), yousign_environment,
    )
    signer_fresh = _yousign_json("GET", f"/signature_requests/{signature_request_id}/signers/{signer_id}") if signer_id else {}
    app.logger.info(
        "[YOUSIGN] signer verification signature_request_id=%s signer_id=%s returned_signature_authentication_mode=%s environment=%s",
        signature_request_id, signer_id or "", signer_fresh.get("signature_authentication_mode") or "", yousign_environment,
    )
    activated = _yousign_json("POST", f"/signature_requests/{signature_request_id}/activate", json={})
    signature_link = _extract_yousign_signature_link(activated, signer_id) or _extract_yousign_signature_link(signer, signer_id)
    if not signature_link and signer_id:
        signature_link = _extract_yousign_signature_link(signer_fresh, signer_id)
    if not signature_link:
        raise RuntimeError("Demande Yousign créée, mais le lien de signature est introuvable. Vérifiez le mode de livraison Yousign.")

    now = _now_iso()
    state = _yousign_state(trainee)
    state.update({
        "status": "ongoing",
        "signature_request_id": signature_request_id,
        "external_id": external_id,
        "document_id": document_id,
        "signer_id": signer_id or "",
        "signature_link": signature_link,
        "signature_link_expires_at": activated.get("signature_link_expiration_date") or signer.get("signature_link_expiration_date") or "",
        "unsigned_pdf_path": yousign_pdf_path,
        "source_pdf_with_anchors_path": pdf_path,
        "unsigned_docx_path": docx_path,
        "created_at": now,
        "activated_at": now,
        "signed_at": "",
        "signed_pdf_path": "",
        "last_error": "",
        "reminder_count": 0,
        "last_reminder_sent_at": "",
        "next_reminder_at": _add_days_iso(now, 1),
        "reminder_1_sent_at": "",
        "reminder_2_sent_at": "",
        "reminder_3_sent_at": "",
        "last_email_error": "",
    })
    trainee["convention_aps_status"] = "signature_ongoing"
    trainee["convention_aps_signed_at"] = ""
    if trainee.get("convention_status") == "signed":
        trainee["convention_status"] = "soon"
    trainee["convention_aps_pdf_path"] = yousign_pdf_path
    trainee["convention_aps_docx_path"] = docx_path
    trainee["updated_at"] = now
    app.logger.info("[YOUSIGN] signature request activated trainee_id=%s request_id=%s", trainee_id, signature_request_id)
    return state


def _find_trainee_by_yousign_request_id(data: Dict[str, Any], request_id: str):
    for sess in data.get("sessions", []):
        trainees = _session_trainees_list(sess)
        for trainee in trainees:
            state = _yousign_state(trainee)
            if str(state.get("signature_request_id") or "") == str(request_id):
                return sess, trainees, trainee
    return None, None, None


def _download_yousign_signed_pdf(signature_request_id: str, trainee_id: str) -> str:
    response = _yousign_request("GET", f"/signature_requests/{signature_request_id}/documents/download", params={"version": "completed", "archive": "false"}, headers={"Accept": "application/pdf"})
    path = os.path.join(YOUSIGN_SIGNED_DIR, f"convention_formation_aps_{_safe_filename_part(trainee_id)}_signee.pdf")
    with open(path, "wb") as fh:
        fh.write(response.content)
    if not os.path.exists(path) or os.path.getsize(path) <= 0:
        raise RuntimeError("Téléchargement du PDF signé Yousign vide.")
    return path


APS_CONVOCATION_AUTO_SEND_DELAY_SECONDS = 5 * 60
APS_CONVOCATION_REMINDER_DAYS_BEFORE_START = 7
_aps_convocation_auto_send_timers: Set[str] = set()
_aps_convocation_auto_send_timers_lock = threading.Lock()


def _send_scheduled_convocation_after_convention_signed(session_id: str, trainee_id: str) -> None:
    """Run the timer callback with the Flask context used by request handlers.

    ``threading.Timer`` executes in a separate thread, so Flask does not copy
    the application context from the webhook request that scheduled it.
    Several helpers used below rely on that context (configuration, logging,
    and URL/file helpers), and otherwise Flask raises ``Working outside of
    application context`` before the convocation can be generated.
    """
    with app.app_context():
        _send_scheduled_convocation_after_convention_signed_in_context(session_id, trainee_id)


def _send_scheduled_convocation_after_convention_signed_in_context(session_id: str, trainee_id: str) -> None:
    data = load_data()
    sess, trainees, trainee = _find_session_trainee(data, session_id, trainee_id)
    if not sess or not trainee:
        app.logger.warning("[CONVOCATION] scheduled send skipped: trainee not found session_id=%s trainee_id=%s", session_id, trainee_id)
        return
    try:
        _send_convocation_after_convention_signed(sess, trainee, session_id, trainee_id)
    except Exception as conv_exc:
        trainee["convocation_auto_last_error"] = str(conv_exc)
        app.logger.exception("[CONVOCATION] scheduled send after convention signature failed trainee_id=%s", trainee_id)
    finally:
        trainee["updated_at"] = _now_iso()
        sess["trainees"] = trainees
        sess.pop("stagiaires", None)
        save_data(data)
        key = f"{session_id}:{trainee_id}"
        with _aps_convocation_auto_send_timers_lock:
            _aps_convocation_auto_send_timers.discard(key)


def _schedule_convocation_after_convention_signed(session_obj: Dict[str, Any], trainee: Dict[str, Any], session_id: str, trainee_id: str) -> None:
    """Planifie l’envoi automatique de la convocation 5 minutes après signature."""
    if not _is_aps_session(session_obj) or trainee.get("convocation_aps_sent_at"):
        return
    key = f"{session_id}:{trainee_id}"
    with _aps_convocation_auto_send_timers_lock:
        if key in _aps_convocation_auto_send_timers:
            return
        _aps_convocation_auto_send_timers.add(key)
    scheduled_at = datetime.datetime.utcnow() + datetime.timedelta(seconds=APS_CONVOCATION_AUTO_SEND_DELAY_SECONDS)
    trainee["convocation_auto_scheduled_at"] = scheduled_at.replace(microsecond=0).isoformat() + "Z"
    trainee["convocation_auto_last_error"] = ""
    timer = threading.Timer(
        APS_CONVOCATION_AUTO_SEND_DELAY_SECONDS,
        _send_scheduled_convocation_after_convention_signed,
        args=(session_id, trainee_id),
    )
    timer.daemon = True
    timer.start()


def _process_due_convocation_after_convention_signed(data: Dict[str, Any]) -> bool:
    """Rattrape les envois de convocation planifiés si le timer en mémoire a été perdu."""
    now = datetime.datetime.utcnow()
    changed = False
    for sess in data.get("sessions", []):
        if not _is_aps_session(sess):
            continue
        trainees = _session_trainees_list(sess)
        session_changed = False
        for trainee in trainees:
            if trainee.get("convocation_aps_sent_at"):
                continue
            scheduled_at = _parse_iso_datetime(trainee.get("convocation_auto_scheduled_at"))
            if not scheduled_at or scheduled_at > now:
                continue
            try:
                sent = _send_convocation_after_convention_signed(sess, trainee, str(sess.get("id") or ""), str(trainee.get("id") or ""))
            except Exception as conv_exc:
                sent = False
                trainee["convocation_auto_last_error"] = str(conv_exc)
                app.logger.exception("[CONVOCATION] due scheduled send failed trainee_id=%s", trainee.get("id"))
            if sent:
                trainee["convocation_auto_scheduled_at"] = ""
            trainee["updated_at"] = _now_iso()
            session_changed = True
            changed = True
        if session_changed:
            sess["trainees"] = trainees
            sess.pop("stagiaires", None)
    return changed


def _resend_convocation_before_training(
    session_obj: Dict[str, Any], trainee: Dict[str, Any], session_id: str, trainee_id: str
) -> bool:
    """Regenerate and resend a previously issued convocation before training."""
    docx_path, pdf_path = _generate_aps_convocation_files(session_obj, trainee, session_id, trainee_id)
    with open(pdf_path, "rb") as fh:
        encoded_pdf = base64.b64encode(fh.read()).decode("ascii")
    subject, html_content = _build_aps_convocation_email(
        str(trainee.get("first_name") or ""),
        _session_get(session_obj, "date_start", ""),
        _session_get(session_obj, "date_end", ""),
        session_obj,
    )
    if not brevo_send_email(
        str(trainee.get("email") or "").strip(),
        subject,
        html_content,
        trainee=trainee,
        attachments=[{"name": os.path.basename(pdf_path), "content": encoded_pdf}],
    ):
        raise RuntimeError("Impossible de renvoyer la convocation : échec d’envoi email")
    now = _now_iso()
    trainee["convocation_aps_pdf_path"] = pdf_path
    trainee["convocation_aps_docx_path"] = docx_path
    trainee["convocation_aps_pdf_token"] = _store_public_file_token(pdf_path)
    trainee["convocation_aps_reminder_sent_at"] = now
    trainee["convocation_aps_reminder_last_error"] = ""
    trainee["updated_at"] = now
    return True


def run_training_convocation_reminders(data: Optional[Dict[str, Any]] = None) -> Dict[str, int]:
    """Resend each already-issued convocation exactly seven days before training."""
    owns_data = data is None
    data = data if data is not None else load_data()
    today = datetime.datetime.utcnow().date()
    due_date = today + datetime.timedelta(days=APS_CONVOCATION_REMINDER_DAYS_BEFORE_START)
    checked = sent = failed = 0
    changed = False
    for sess in data.get("sessions", []):
        if not _is_aps_session(sess):
            continue
        start_date = _session_start_date(sess)
        if start_date != due_date:
            continue
        trainees = _session_trainees_list(sess)
        session_changed = False
        for trainee in trainees:
            if not trainee.get("convocation_aps_sent_at") or trainee.get("convocation_aps_reminder_sent_at"):
                continue
            checked += 1
            try:
                _resend_convocation_before_training(
                    sess, trainee, str(sess.get("id") or ""), str(trainee.get("id") or "")
                )
                sent += 1
            except Exception as exc:
                failed += 1
                trainee["convocation_aps_reminder_last_error"] = str(exc)
                trainee["updated_at"] = _now_iso()
                app.logger.exception("[CONVOCATION] seven-day reminder failed trainee_id=%s", trainee.get("id"))
            changed = True
            session_changed = True
        if session_changed:
            sess["trainees"] = trainees
            sess.pop("stagiaires", None)
    if owns_data and changed:
        save_data(data)
    return {"checked": checked, "sent": sent, "failed": failed}


def _mark_yousign_convention_signed(data: Dict[str, Any], sess: Dict[str, Any], trainees: List[Dict[str, Any]], trainee: Dict[str, Any], request_id: str, event_id: str = "") -> None:
    state = _yousign_state(trainee)
    if _is_yousign_signature_done(state) and state.get("signed_pdf_path"):
        return
    signed_path = _download_yousign_signed_pdf(request_id, str(trainee.get("id") or ""))
    now = _now_iso()
    state.update({
        "status": "done",
        "signed_at": state.get("signed_at") or now,
        "next_reminder_at": "",
        "signed_pdf_path": signed_path,
        "signed_pdf_token": _store_public_file_token(signed_path),
        "last_error": "",
        "last_event_id": event_id or state.get("last_event_id") or "",
    })
    trainee["convention_aps_status"] = "signed"
    trainee["convention_aps_signed_at"] = state.get("signed_at") or now
    _sync_convention_status_from_yousign(trainee)
    _schedule_convocation_after_convention_signed(sess, trainee, str(sess.get("id") or ""), str(trainee.get("id") or ""))
    trainee["updated_at"] = now
    sess["trainees"] = trainees
    sess.pop("stagiaires", None)


def _refresh_yousign_convention_status_if_pending(data: Dict[str, Any], sess: Dict[str, Any], trainees: List[Dict[str, Any]], trainee: Dict[str, Any]) -> bool:
    state = _yousign_state(trainee)
    request_id = str(state.get("signature_request_id") or "").strip()
    if not request_id or not _is_yousign_signature_pending(state) or not _yousign_is_configured():
        return False
    try:
        signature_request = _yousign_json("GET", f"/signature_requests/{request_id}")
    except Exception as exc:
        state["last_status_sync_error"] = _sanitize_yousign_error(str(exc))
        app.logger.warning("[YOUSIGN] status refresh failed request_id=%s error=%s", request_id, state["last_status_sync_error"])
        return False
    status = _yousign_signature_request_status(signature_request)
    if not status:
        return False
    if status in YOUSIGN_FINAL_STATUSES:
        _mark_yousign_convention_signed(data, sess, trainees, trainee, request_id)
        return True
    if status != _normalize_yousign_status(state.get("status")):
        state["status"] = status
        trainee["updated_at"] = _now_iso()
        sess["trainees"] = trainees
        sess.pop("stagiaires", None)
        return True
    return False


def _pdf_page_count(pdf_path: str) -> int:
    try:
        return max(1, len(PdfReader(pdf_path).pages))
    except Exception:
        return 1


def _verify_yousign_webhook_signature(raw_body: bytes) -> bool:
    secret = (os.environ.get("YOUSIGN_WEBHOOK_SECRET") or "").strip()
    signature = request.headers.get("x-yousign-signature-256", "")
    if not secret or not signature:
        return False
    digest = hmac.new(secret.encode("utf-8"), raw_body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(signature, f"sha256={digest}")


def _safe_filename_part(value: Any) -> str:
    normalized = unicodedata.normalize("NFKD", str(value or "")).encode("ascii", "ignore").decode("ascii")
    normalized = re.sub(r"[^A-Za-z0-9_-]+", "-", normalized).strip("-").lower()
    return normalized or "stagiaire"


def _format_long_fr_date(value: str) -> str:
    value = (value or "").strip()
    if not value:
        return ""
    months = ["", "janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre", "novembre", "décembre"]
    try:
        dt = datetime.datetime.strptime(value[:10], "%Y-%m-%d").date()
        return f"{dt.day} {months[dt.month]} {dt.year}"
    except Exception:
        return value


def _certificate_realization_nature(session_obj: Dict[str, Any], trainee: Dict[str, Any]) -> str:
    text = " ".join(
        str(value or "")
        for value in (
            _session_get(session_obj, "training_type", ""),
            _session_get(session_obj, "name", ""),
            trainee.get("contract_type"),
            trainee.get("training_contract_type"),
            trainee.get("status"),
        )
    ).upper()
    if "VAE" in text:
        return "vae"
    if "APPRENT" in text or "ALTERNANCE" in text:
        return "apprenticeship"
    if "BILAN DE COMP" in text:
        return "skills_assessment"
    return "training"


def _certificate_realization_quantity(value: Any, unit: str) -> str:
    if value in (None, "") or isinstance(value, bool):
        return ""
    match = re.search(r"\d+(?:[.,]\d+)?", str(value).replace("\u202f", " "))
    if not match:
        return ""
    try:
        quantity = float(match.group(0).replace(",", "."))
    except ValueError:
        return ""
    if quantity <= 0:
        return ""
    rendered = str(int(quantity)) if quantity.is_integer() else (f"{quantity:.2f}".rstrip("0").rstrip(".").replace(".", ","))
    singular = "heure" if unit == "hours" else "mois"
    plural = "heures" if unit == "hours" else "mois"
    return f"{rendered} {singular if quantity == 1 else plural}"


def _certificate_realization_months(session_obj: Dict[str, Any], trainee: Dict[str, Any]) -> str:
    month_keys = (
        "certificate_realization_months", "realized_months", "duration_months",
        "training_duration_months", "apprenticeship_months", "nombre_mois_realises",
    )
    for source in (trainee, session_obj):
        for key in month_keys:
            rendered = _certificate_realization_quantity(source.get(key), "months")
            if rendered:
                return rendered

    start = _parse_iso_date(str(_session_get(session_obj, "date_start", "") or ""))
    end = _parse_iso_date(str(_session_get(session_obj, "date_end", "") or ""))
    if start and end and end >= start:
        months = max(1, ((end.year - start.year) * 12) + end.month - start.month + (1 if end.day >= start.day else 0))
        return _certificate_realization_quantity(months, "months")
    return "Non renseignée"


def _certificate_realization_duration(session_obj: Dict[str, Any], trainee: Dict[str, Any], nature: str) -> str:
    if nature == "apprenticeship":
        return _certificate_realization_months(session_obj, trainee)

    hour_keys = (
        "certificate_realization_hours", "realized_training_hours", "realised_training_hours",
        "hours_completed", "training_duration_hours", "duration_hours", "total_hours",
        "h_total", "heures_realisees", "duree_heures",
    )
    for source in (trainee, session_obj):
        for key in hour_keys:
            rendered = _certificate_realization_quantity(source.get(key), "hours")
            if rendered:
                return rendered

    training_text = _automation_training_text(session_obj)
    if "AFC" in training_text and "APS" in training_text and "SSIAP" in training_text:
        return "393 heures"
    slug = str(_automation_document_config(session_obj).get("slug") or "")
    hours = CERTIFICATE_REALIZATION_DEFAULT_HOURS.get(slug)
    return _certificate_realization_quantity(hours, "hours") if hours else "Non renseignée"


def _certificate_realization_dates(session_obj: Dict[str, Any], trainee: Dict[str, Any]) -> Tuple[str, str]:
    start = str(
        trainee.get("certificate_realization_start_date")
        or trainee.get("actual_training_start_date")
        or trainee.get("real_training_start_date")
        or _session_get(session_obj, "date_start", "")
        or ""
    ).strip()
    end = str(
        trainee.get("certificate_realization_end_date")
        or trainee.get("actual_training_end_date")
        or trainee.get("real_training_end_date")
        or _session_get(session_obj, "date_end", "")
        or ""
    ).strip()
    vtc_dates = str(trainee.get("vtc_real_training_dates") or "").strip()
    if vtc_dates:
        matches = re.findall(r"\b\d{1,2}[/-]\d{1,2}[/-]\d{4}\b", vtc_dates)
        if len(matches) >= 2:
            start, end = matches[0], matches[-1]
    return fr_date(start), fr_date(end)


def _certificate_realization_training_title(session_obj: Dict[str, Any], trainee: Dict[str, Any]) -> str:
    for value in (
        trainee.get("certificate_realization_title"), trainee.get("formation_nom"), trainee.get("training_name"),
        _session_get(session_obj, "training_title", ""), _session_get(session_obj, "nom_pedagogique", ""),
    ):
        if str(value or "").strip():
            return str(value).strip()

    training_type = str(_session_get(session_obj, "training_type", "") or "").strip()
    session_name = str(_session_get(session_obj, "name", "") or "").strip()
    if session_name and ("AFC" in session_name.upper() or ("APS" in session_name.upper() and "SSIAP" in session_name.upper())):
        return session_name
    long_label = formation_label(training_type)
    return str(long_label or session_name or training_type or "Formation").strip()


def _certificate_realization_employer(trainee: Dict[str, Any], billing_lines: Optional[List[Dict[str, Any]]] = None) -> str:
    def usable_company_name(value: Any) -> str:
        candidate = re.sub(r"\s+", " ", str(value or "")).strip()
        normalized = unicodedata.normalize("NFKD", candidate).encode("ascii", "ignore").decode("ascii").upper()
        if normalized in {"", "-", "N/A", "NA", "NC", "NEANT", "NON RENSEIGNE", "NON RENSEIGNEE"}:
            return ""
        return candidate

    for key in ("employer_name", "company_name", "employer", "entreprise", "raison_sociale", "qonto_company_name"):
        value = usable_company_name(trainee.get(key))
        if value:
            return value
    for line in billing_lines or []:
        financing = str(line.get("financingType") or line.get("typeFinanceur") or line.get("financeurName") or "").upper()
        if financing not in {"ENTREPRISE", "COMPANY"}:
            continue
        value = usable_company_name(line.get("companyName") or line.get("company_name"))
        if value:
            return value
    return ""


def _build_certificate_realization_context(
    session_obj: Dict[str, Any],
    trainee: Dict[str, Any],
    billing_lines: Optional[List[Dict[str, Any]]] = None,
    employer_override: str = "",
) -> Dict[str, str]:
    first_name = str(trainee.get("first_name") or trainee.get("prenom") or "").strip()
    last_name = str(trainee.get("last_name") or trainee.get("nom") or "").strip().upper()
    beneficiary = f"{first_name} {last_name}".strip()
    start_date, end_date = _certificate_realization_dates(session_obj, trainee)
    if not beneficiary:
        raise ValueError("Impossible de générer le certificat de réalisation : nom du stagiaire manquant.")
    if not start_date or not end_date:
        raise ValueError("Impossible de générer le certificat de réalisation : dates de formation manquantes.")
    employer = _certificate_realization_employer({"company_name": employer_override}) or _certificate_realization_employer(trainee, billing_lines)
    if not employer:
        raise ValueError("Impossible de générer le certificat de réalisation : nom de l’entreprise manquant.")
    nature = _certificate_realization_nature(session_obj, trainee)
    return {
        "signatory": CERTIFICATE_REALIZATION_SIGNATORY,
        "provider": CERTIFICATE_REALIZATION_PROVIDER,
        "beneficiary": beneficiary,
        "employer": employer,
        "training_title": _certificate_realization_training_title(session_obj, trainee),
        "nature": nature,
        "start_date": start_date,
        "end_date": end_date,
        "duration": _certificate_realization_duration(session_obj, trainee, nature),
        "place": "Puget-sur-Argens",
        "issued_date": datetime.datetime.now(ZoneInfo("Europe/Paris")).strftime("%d/%m/%Y"),
    }


def _draw_certificate_realization_value(
    pdf_canvas: Any,
    value: str,
    x: float,
    y: float,
    max_width: float,
    *,
    font_size: float = 10.2,
    min_font_size: float = 7.2,
) -> None:
    from reportlab.pdfbase.pdfmetrics import stringWidth

    value = str(value or "")
    word_spacing = 0.9

    def rendered_width(candidate_size: float) -> float:
        return stringWidth(value, "Helvetica-Bold", candidate_size) + (value.count(" ") * word_spacing)

    size = font_size
    while size > min_font_size and rendered_width(size) > max_width:
        size = max(min_font_size, size - 0.4)
    text_object = pdf_canvas.beginText(x, y)
    text_object.setFont("Helvetica-Bold", size)
    text_object.setFillColorRGB(15 / 255, 23 / 255, 42 / 255)
    text_object.setWordSpace(word_spacing)
    text_object.textOut(value)
    pdf_canvas.drawText(text_object)


def _draw_certificate_realization_label(
    pdf_canvas: Any,
    value: str,
    x: float,
    y: float,
    *,
    font_name: str = "Helvetica",
    font_size: float = 10.2,
    color: Tuple[float, float, float] = (15 / 255, 23 / 255, 42 / 255),
) -> None:
    text_object = pdf_canvas.beginText(x, y)
    text_object.setFont(font_name, font_size)
    text_object.setFillColorRGB(*color)
    text_object.setWordSpace(0.2)
    text_object.textOut(value)
    pdf_canvas.drawText(text_object)


def _certificate_realization_wrapped_lines(value: str, max_width: float, max_lines: int = 2) -> List[str]:
    from reportlab.pdfbase.pdfmetrics import stringWidth

    words = str(value or "").split()
    lines: List[str] = []
    current = ""
    index = 0
    while index < len(words):
        word = words[index]
        candidate = f"{current} {word}".strip()
        if not current or stringWidth(candidate, "Helvetica-Bold", 9.4) <= max_width:
            current = candidate
            index += 1
            continue
        lines.append(current)
        current = ""
        if len(lines) == max_lines - 1:
            break
    remaining = " ".join(([current] if current else []) + words[index:]).strip()
    if remaining and len(lines) < max_lines:
        original = remaining
        while remaining and stringWidth(remaining, "Helvetica-Bold", 9.4) > max_width:
            remaining = remaining[:-1].rstrip()
        if remaining != original and len(remaining) > 3:
            remaining = remaining[:-3].rstrip() + "..."
        lines.append(remaining)
    return lines or [""]


def _build_certificate_realization_pdf(context: Dict[str, str]) -> BytesIO:
    if not (PYPDF_LIBRARY_AVAILABLE and REPORTLAB_LIBRARY_AVAILABLE):
        raise RuntimeError("Le moteur PDF nécessaire au certificat de réalisation est indisponible.")
    if not os.path.exists(CERTIFICATE_REALIZATION_TEMPLATE):
        raise FileNotFoundError("Modèle PDF obligatoire manquant : templates_word/certificatrealisation.pdf")

    from reportlab.pdfgen import canvas

    reader = PdfReader(CERTIFICATE_REALIZATION_TEMPLATE)
    if not reader.pages:
        raise RuntimeError("Le modèle du certificat de réalisation ne contient aucune page.")
    page = reader.pages[0]
    width = float(page.mediabox.width)
    height = float(page.mediabox.height)
    packet = BytesIO()
    overlay = canvas.Canvas(packet, pagesize=(width, height), pageCompression=1)

    def mask(x: float, y: float, mask_width: float, mask_height: float) -> None:
        overlay.setFillColorRGB(1, 1, 1)
        overlay.rect(x, y, mask_width, mask_height, stroke=0, fill=1)

    mask(69, 595, 464, 20)
    mask(69, 552, 350, 18)
    mask(69, 495, 464, 19)
    mask(69, 477, 464, 18)
    mask(69, 447, 464, 29)
    mask(69, 333, 322, 18)
    mask(69, 319, 226, 14)
    mask(69, 182, 164, 18)
    mask(69, 164, 164, 18)

    _draw_certificate_realization_label(overlay, "Je soussigné(e) :", 71, 603.5)
    _draw_certificate_realization_value(overlay, context["signatory"], 155, 603.5, 370, font_size=10.4)
    _draw_certificate_realization_label(
        overlay,
        "interne),",
        71,
        560.3,
        font_name="Helvetica-Oblique",
        color=(0, 24 / 255, 122 / 255),
    )
    _draw_certificate_realization_value(overlay, context["provider"], 114, 560.3, 296, font_size=10.2)
    _draw_certificate_realization_label(overlay, "Mme/M.", 71, 503.5)
    _draw_certificate_realization_value(overlay, context["beneficiary"], 114, 503.5, 410, font_size=10.2)
    _draw_certificate_realization_label(overlay, "salarié(e) de l’entreprise :", 71, 485.1)
    _draw_certificate_realization_value(overlay, context["employer"], 192, 485.1, 332, font_size=9.8)
    _draw_certificate_realization_label(overlay, "a suivi l’action :", 71, 465.8)
    for index, line in enumerate(_certificate_realization_wrapped_lines(context["training_title"], 382)):
        _draw_certificate_realization_value(overlay, line, 146 if index == 0 else 71, 465.8 - (index * 12), 378 if index == 0 else 453, font_size=9.4)
    _draw_certificate_realization_label(overlay, "qui s’est déroulée du", 71, 340.9)
    _draw_certificate_realization_value(overlay, context["start_date"], 173, 340.9, 91, font_size=9.2, min_font_size=8)
    _draw_certificate_realization_label(overlay, "au", 280, 340.9)
    _draw_certificate_realization_value(overlay, context["end_date"], 298, 340.9, 88, font_size=9.2, min_font_size=8)
    _draw_certificate_realization_label(overlay, "pour une durée de", 71, 321.7)
    _draw_certificate_realization_value(overlay, context["duration"], 161, 321.7, 130, font_size=9.2, min_font_size=7.8)
    _draw_certificate_realization_label(overlay, "Fait à :", 71, 190.3)
    _draw_certificate_realization_value(overlay, context["place"], 108, 190.3, 120, font_size=8.5, min_font_size=7)
    _draw_certificate_realization_label(overlay, "Le :", 71, 171.9)
    _draw_certificate_realization_value(overlay, context["issued_date"], 94, 171.9, 133, font_size=9.2, min_font_size=8)

    checkbox_y = {
        "training": 416.4,
        "skills_assessment": 401.97,
        "vae": 386.77,
        "apprenticeship": 372.35,
    }.get(context.get("nature"), 416.4)
    overlay.setFillColorRGB(0, 24 / 255, 122 / 255)
    overlay.rect(78.5, checkbox_y, 9.2, 9.2, stroke=0, fill=1)
    overlay.setStrokeColorRGB(1, 1, 1)
    overlay.setLineWidth(1.4)
    overlay.line(80.1, checkbox_y + 4.4, 82.6, checkbox_y + 1.8)
    overlay.line(82.6, checkbox_y + 1.8, 86.3, checkbox_y + 7.2)
    overlay.save()
    packet.seek(0)
    page.merge_page(PdfReader(packet).pages[0])

    writer = PdfWriter()
    writer.add_page(page)
    for remaining_page in reader.pages[1:]:
        writer.add_page(remaining_page)
    writer.add_metadata({"/Title": f"Certificat de réalisation - {context['beneficiary']}"})
    output = BytesIO()
    writer.write(output)
    output.seek(0)
    return output





def _aps_entry_attestation_template_path(session_obj: Optional[Dict[str, Any]] = None) -> str:
    template_name = (_automation_document_config(session_obj or {}).get("entry_template") or "attestationentreeaps.docx")
    return os.path.join(app.root_path, "templates_word", template_name)


def _aps_entry_attestation_base_filename(trainee: Dict[str, Any], trainee_id: str = "") -> str:
    last_name = _safe_filename_part(trainee.get("last_name") or trainee.get("nom") or trainee_id)
    first_name = _safe_filename_part(trainee.get("first_name") or trainee.get("prenom") or "")
    suffix = f"_{first_name}" if first_name else ""
    return f"attestation_entree_formation_aps_{last_name}{suffix}"


def _build_aps_entry_attestation_context(session_obj: Dict[str, Any], trainee: Dict[str, Any]) -> Dict[str, str]:
    first_name = str(trainee.get("first_name") or trainee.get("prenom") or "").strip()
    last_name = str(trainee.get("last_name") or trainee.get("nom") or "").strip().upper()
    full_name = f"{last_name} {first_name}".strip()
    date_start = str(_session_get(session_obj, "date_start", "") or "").strip()
    if not full_name:
        raise ValueError("Impossible de générer l’attestation d’entrée APS : nom du stagiaire manquant")
    if not date_start:
        raise ValueError("Impossible de générer l’attestation d’entrée APS : date de début de formation manquante")
    return {
        "nom_complet": full_name,
        "date_debut_formation": fr_date(date_start),
        "date_jour": datetime.datetime.utcnow().strftime("%d/%m/%Y"),
    }


def _generate_aps_entry_attestation_files(session_obj: Dict[str, Any], trainee: Dict[str, Any], session_id: str = "", trainee_id: str = "") -> Tuple[str, str]:
    template_path = _aps_entry_attestation_template_path(session_obj)
    template_name = os.path.basename(template_path)
    if not template_name or not os.path.exists(template_path):
        raise FileNotFoundError(f"Modèle Word obligatoire manquant : gestionstagiaires/templates_word/{template_name or 'attestation d’entrée'}")
    os.makedirs(APS_ENTRY_ATTESTATION_DIR, exist_ok=True)
    base = _aps_entry_attestation_base_filename(trainee, trainee_id)
    final_docx_path = os.path.join(APS_ENTRY_ATTESTATION_DIR, base + ".docx")
    final_pdf_path = os.path.join(APS_ENTRY_ATTESTATION_DIR, base + ".pdf")
    shutil.copyfile(template_path, final_docx_path)
    _replace_docx_xml_placeholders(final_docx_path, _build_aps_entry_attestation_context(session_obj, trainee))
    _assert_docx_has_no_unresolved_variables(final_docx_path)
    lo_binary = _find_libreoffice_binary()
    if os.path.exists(final_pdf_path):
        os.remove(final_pdf_path)
    command = [lo_binary, "--headless", "--convert-to", "pdf", "--outdir", APS_ENTRY_ATTESTATION_DIR, final_docx_path]
    try:
        subprocess.run(command, check=True, capture_output=True, text=True, timeout=120)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Conversion LibreOffice impossible : {(exc.stderr or exc.stdout or '').strip()}") from exc
    if not os.path.exists(final_pdf_path) or os.path.getsize(final_pdf_path) <= 0:
        raise RuntimeError("Le PDF final de l’attestation d’entrée APS est introuvable ou vide après conversion LibreOffice.")
    return final_docx_path, final_pdf_path



