def _store_public_file_token(path: str) -> str:
    try:
        return _tokenize_path(path)
    except Exception:
        return path


def _send_convocation_after_convention_signed(session_obj: Dict[str, Any], trainee: Dict[str, Any], session_id: str, trainee_id: str) -> bool:
    """Generate, send by email, and expose the convocation once the convention is signed."""
    if str(_automation_document_config(session_obj).get("slug") or "") == "vtc":
        # En VTC, seule la réussite à la théorie déclenche la convocation.
        return False
    automation = _build_trainee_automation_status(session_obj, trainee, session_id, trainee_id)
    if (automation.get("convention") or {}).get("status") != "signed":
        trainee["convocation_auto_last_error"] = "En attente de signature de la convention"
        return False
    if not _is_aps_session(session_obj):
        trainee["convocation_auto_last_error"] = "Envoi automatique de convocation configuré uniquement pour APS."
        return False
    if trainee.get("convocation_aps_sent_at"):
        return True
    docx_path, pdf_path = _generate_aps_convocation_files(session_obj, trainee, session_id, trainee_id)
    with open(pdf_path, "rb") as fh:
        encoded_pdf = base64.b64encode(fh.read()).decode("ascii")
    subject, html_content = _build_aps_convocation_email(str(trainee.get("first_name") or ""), _session_get(session_obj, "date_start", ""), _session_get(session_obj, "date_end", ""), session_obj)
    if not brevo_send_email(str(trainee.get("email") or "").strip(), subject, html_content, trainee=trainee, attachments=[{"name": os.path.basename(pdf_path), "content": encoded_pdf}]):
        raise RuntimeError("Impossible d’envoyer la convocation : échec d’envoi email")
    now = _now_iso()
    trainee["convocation_aps_status"] = "sent"
    trainee["convocation_aps_generated_at"] = trainee.get("convocation_aps_generated_at") or now
    trainee["convocation_aps_sent_at"] = now
    trainee["convocation_aps_pdf_path"] = pdf_path
    trainee["convocation_aps_docx_path"] = docx_path
    trainee["convocation_aps_pdf_token"] = _store_public_file_token(pdf_path)
    trainee["convocation_aps_last_error"] = ""
    trainee["convocation_auto_last_error"] = ""
    trainee["convocation_auto_scheduled_at"] = ""
    return True



def _format_automation_datetime(value: Any) -> str:
    """Affiche les horodatages d'automatisation au format français, heure de Paris."""
    if not value:
        return ""
    return fr_datetime(str(value))


def _has_generated_yousign_convention(trainee: Dict[str, Any]) -> bool:
    """Return True once a convention document or Yousign request exists."""
    state = _yousign_state(trainee)
    return bool(
        _has_legacy_signed_convention(trainee)
        or state.get("signature_request_id")
        or state.get("unsigned_pdf_path")
        or state.get("signed_pdf_path")
        or trainee.get("convention_aps_pdf_path")
        or trainee.get("convention_aps_docx_path")
    )


def _build_trainee_automation_status(session_obj: Dict[str, Any], trainee: Dict[str, Any], session_id: str, trainee_id: str) -> Dict[str, Any]:
    """Centralise l'état des documents automatisés affiché sur la fiche stagiaire."""
    state = _yousign_state(trainee)
    raw_status = _normalize_yousign_status(state.get("status"))
    generated_at_raw = state.get("created_at") or trainee.get("convention_aps_generated_at") or ""
    sent_at_raw = state.get("signature_email_sent_at") or state.get("activated_at") or ""
    signed_at_raw = state.get("signed_at") or trainee.get("convention_aps_signed_at") or trainee.get("convention_legacy_signed_at") or ""
    generated_at = _format_automation_datetime(generated_at_raw)
    sent_at = _format_automation_datetime(sent_at_raw)
    signed_at = _format_automation_datetime(signed_at_raw)
    has_generated_convention = _has_generated_yousign_convention(trainee)
    has_signature_request = bool(state.get("signature_request_id"))
    convention_error = state.get("last_error") or state.get("signature_email_last_error") or state.get("last_email_error") or state.get("last_status_sync_error") or ""
    if raw_status in {"error", "download_error"}:
        convention_status = "error"
    elif raw_status in {"declined", "refused"}:
        convention_status = "refused"
    elif raw_status in {"expired", "canceled", "cancelled"} or _yousign_signature_link_is_expired(state):
        convention_status = "expired"
    elif _is_yousign_signature_done(state) or signed_at or _has_legacy_signed_convention(trainee):
        convention_status = "signed"
    elif has_signature_request and _is_yousign_signature_pending(state):
        convention_status = "waiting_signature"
    elif has_signature_request:
        convention_status = "sent"
    elif has_generated_convention:
        convention_status = "generated"
    else:
        convention_status = "not_generated"

    convention_signed = convention_status == "signed"
    convention_sent = convention_status in {"sent", "waiting_signature", "signed"}
    convocation_sent_at_raw = trainee.get("convocation_aps_sent_at") or ""
    convocation_error = trainee.get("convocation_aps_last_error") or ""
    if not convocation_error and not convocation_sent_at_raw:
        convocation_error = trainee.get("convocation_auto_last_error") or ""
    if not convention_signed and convocation_error == "En attente de signature de la convention":
        convocation_error = ""
    convocation_sent_at = _format_automation_datetime(convocation_sent_at_raw)
    has_convocation_file = bool(trainee.get("convocation_aps_pdf_path") or trainee.get("convocation_aps_docx_path"))
    convocation_generated_at_raw = trainee.get("convocation_aps_generated_at") or (convocation_sent_at_raw if has_convocation_file else "")
    convocation_generated_at = _format_automation_datetime(convocation_generated_at_raw)
    if convocation_error:
        convocation_status = "error"
    elif convocation_sent_at or trainee.get("convocation_aps_status") == "sent":
        convocation_status = "sent"
    elif has_convocation_file:
        convocation_status = "generated"
    else:
        convocation_status = "not_generated"

    config = _automation_document_config(session_obj)
    automation_slug = str(config.get("slug") or "")
    is_vtc_automation = automation_slug == "vtc"
    theory_succeeded = bool(trainee.get("vtc_theory_exam_sent_at"))
    if is_vtc_automation and not theory_succeeded:
        convocation_block_reason = "En attente de réussite à l’examen théorique"
    elif is_vtc_automation:
        convocation_block_reason = ""
    elif not has_generated_convention:
        convocation_block_reason = "En attente de génération de la convention"
    elif not convention_sent:
        convocation_block_reason = "En attente d’envoi de la convention"
    elif not convention_signed:
        convocation_block_reason = "En attente signature convention"
    else:
        convocation_block_reason = ""

    is_vae_automation = automation_slug == "vae"
    is_aps_automation = _is_aps_session(session_obj)
    can_send_convocation_without_signed_convention = _can_send_convocation_without_signed_convention(session_obj)
    has_entry_attestation = bool(config.get("entry_template"))
    has_end_attestation = bool(config.get("end_template"))
    entry_sent = bool(trainee.get("attestation_entree_aps_sent_at"))
    end_sent = bool(trainee.get("attestation_fin_aps_sent_at"))
    convention_sent_step = {"label": "Convention envoyée", "state": "complete" if convention_sent else ("error" if convention_status == "error" else "pending" if has_generated_convention else "blocked")}
    convention_signed_step = {"label": "Convention signée", "state": "complete" if convention_signed else ("error" if convention_status in {"error", "refused", "expired"} else "pending" if has_signature_request else "blocked")}
    if is_vtc_automation:
        timeline = [
            convention_sent_step,
            convention_signed_step,
            {"label": "Convocation", "state": "complete" if convocation_status == "sent" else ("error" if convocation_status == "error" else "blocked" if not theory_succeeded else "pending")},
        ]
    elif is_vae_automation:
        timeline = [convention_sent_step, convention_signed_step]
    else:
        timeline = [
            convention_sent_step,
            convention_signed_step,
            {"label": "Convocation", "state": "complete" if convocation_status == "sent" else ("error" if convocation_status == "error" else "blocked" if ((is_vtc_automation and not theory_succeeded) or (not is_vtc_automation and not convention_signed)) else "pending")} if is_aps_automation else {"label": "Documents", "state": "complete" if convention_signed else "pending"},
            {"label": "Attestation entrée", "state": "complete" if entry_sent else ("blocked" if not convention_signed else "pending")} if has_entry_attestation else {"label": "Documents", "state": "complete" if convention_signed else "pending"},
            {"label": "Attestation sortie", "state": "complete" if end_sent else ("blocked" if not convention_signed else "pending")} if has_end_attestation else {"label": "Documents", "state": "complete" if convention_signed else "pending"},
        ]
    if convention_status == "error" or (is_aps_automation and convocation_status == "error"):
        global_status = "error"
    elif convention_signed and (not is_aps_automation or convocation_status == "sent") and (not has_entry_attestation or entry_sent) and (not has_end_attestation or end_sent):
        global_status = "complete"
    elif convention_status == "waiting_signature":
        global_status = "in_progress"
    elif not convention_signed:
        global_status = "blocked" if has_generated_convention or has_signature_request else "action_required"
    else:
        global_status = "action_required"
    if is_vae_automation:
        ready_documents = int(convention_sent) + int(convention_signed)
    else:
        ready_documents = int(convention_sent) + int(convention_signed) + int(is_aps_automation and convocation_status == "sent") + int(has_entry_attestation and entry_sent) + int(has_end_attestation and end_sent)

    convention_labels = {
        "not_generated": ("Non générée", "file", "pending", "pending", "Générer la convention"),
        "generated": ("Générée", "file", "pending", "ready", "Envoyer pour signature"),
        "sent": ("Envoyée", "send", "pending", "pending", "Voir le statut Yousign"),
        "waiting_signature": ("Signature attendue", "hourglass", "waiting", "pending", "Voir le statut Yousign"),
        "signed": ("Signée", "check", "complete", "done", "Convention signée"),
        "refused": ("Refusée", "alert", "error", "blocked", "Créer une nouvelle demande"),
        "expired": ("Expirée", "alert", "error", "blocked", "Créer une nouvelle demande"),
        "error": ("Erreur", "alert", "error", "blocked", "Réessayer"),
    }
    c_label, c_icon, c_tone, c_card_tone, c_primary_action = convention_labels.get(convention_status, convention_labels["error"])
    convocation_labels = {
        "blocked_waiting_convention": (convocation_block_reason or "Bloquée", "hourglass" if has_signature_request else "lock", "blocked", "blocked"),
        "not_generated": ("Prêt", "file", "pending", "ready"),
        "generated": ("Générée", "file", "pending", "ready"),
        "sent": ("Envoyée", "check", "complete", "done"),
        "error": ("Erreur", "alert", "error", "blocked"),
    }
    v_label, v_icon, v_tone, v_card_tone = convocation_labels.get(convocation_status, convocation_labels["error"])

    total_documents = 2 if is_vae_automation else 2 + int(is_aps_automation) + int(has_entry_attestation) + int(has_end_attestation)
    progress_percent = round((ready_documents / total_documents) * 100) if total_documents else 0

    planned_automations = []
    if not has_generated_convention:
        planned_automations.append("Convention")
    if is_aps_automation and convocation_status not in {"sent", "generated"}:
        planned_automations.append("Convocation")
    if has_entry_attestation and not entry_sent:
        planned_automations.append("Attestation d’entrée")
    if has_end_attestation and not end_sent:
        planned_automations.append("Attestation de sortie")

    return {
        "has_convocation": is_aps_automation,
        "has_entry_attestation": has_entry_attestation,
        "has_end_attestation": has_end_attestation,
        "planned_automations": planned_automations,
        "global_status": global_status,
        "ready_documents": ready_documents,
        "total_documents": total_documents,
        "progress_percent": progress_percent,
        "convention": {
            "status": convention_status, "label": c_label, "icon": c_icon, "icon_class": "automation-icon--hourglass" if c_icon == "hourglass" else "", "tone": c_tone, "card_tone": c_card_tone,
            "primary_action": c_primary_action, "can_send": True, "can_download": bool(has_generated_convention or state.get("signed_pdf_path")),
            "generated_at": generated_at, "sent_at": sent_at, "signed_at": signed_at,
            "recipient_email": trainee.get("email") or "", "signature_request_id": state.get("signature_request_id") or "",
            "download_url": url_for("admin_view_signed_convention" if convention_signed and state.get("signed_pdf_path") else "admin_view_original_convention", session_id=session_id, trainee_id=trainee_id) if (has_generated_convention or state.get("signed_pdf_path")) else "",
            "error": convention_error,
            "timeline_steps": [
                {"label": "Générée", "value": generated_at or "Pas encore effectué", "state": "done" if generated_at else "blocked"},
                {"label": "Envoyée", "value": sent_at or "Pas encore effectué", "state": "done" if sent_at else ("pending" if has_generated_convention else "blocked")},
                {"label": "Signature", "value": ("Signée le " + signed_at) if signed_at else ("En attente de signature" if has_signature_request else "Pas encore effectué"), "state": "done" if signed_at else ("blocked" if convention_status in {"refused", "expired"} else "pending" if has_signature_request else "blocked")},
            ],
        },
        "convocation": {
            "status": convocation_status, "label": v_label, "icon": v_icon, "icon_class": "automation-icon--hourglass" if v_icon == "hourglass" else "", "tone": v_tone, "card_tone": v_card_tone,
            "can_generate": theory_succeeded if is_vtc_automation else True, "can_send": (theory_succeeded if is_vtc_automation else (convention_signed or can_send_convocation_without_signed_convention)) and convocation_status in {"generated", "sent", "error"}, "block_reason": "" if (is_vtc_automation and theory_succeeded) or can_send_convocation_without_signed_convention else convocation_block_reason,
            "generated_at": convocation_generated_at_raw, "generated_at_label": convocation_generated_at, "sent_at": convocation_sent_at,
            "download_url": url_for("admin_view_aps_convocation", session_id=session_id, trainee_id=trainee_id) if has_convocation_file else "",
            "preview_url": url_for("admin_preview_aps_convocation", session_id=session_id, trainee_id=trainee_id),
            "error": convocation_error,
            "timeline_steps": [
                {"label": "Examen théorique" if is_vtc_automation else "Convention validée", "value": ("Réussi" if theory_succeeded else convocation_block_reason) if is_vtc_automation else ("Signée" if convention_signed else ("Non requise pour l’envoi" if can_send_convocation_without_signed_convention else (convocation_block_reason or "Pas encore effectué"))), "state": "done" if (theory_succeeded if is_vtc_automation else (convention_signed or can_send_convocation_without_signed_convention)) else "blocked"},
                {"label": "Génération", "value": convocation_generated_at or "Pas encore effectué", "state": "done" if convocation_generated_at_raw else "pending"},
                {"label": "Envoi", "value": ("Envoyée le " + convocation_sent_at) if convocation_sent_at else "Pas encore effectué", "state": "done" if convocation_sent_at else ("pending" if has_convocation_file else "blocked")},
            ],
        },
        "timeline": timeline,
    }

# =========================
# ✅ Remplace ta page JSON par une vraie page HTML
# =========================
@app.get("/admin/sessions/<session_id>/stagiaires/<trainee_id>")
@admin_login_required
def admin_trainee_page(session_id: str, trainee_id: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        abort(404)
    if _is_wedof_leads_session(s):
        abort(404)

    session_view = {
        "id": s.get("id"),
        "name": _session_get(s, "name", ""),
        "training_type": _session_get(s, "training_type", ""),
        "date_start": _session_get(s, "date_start", ""),
        "date_end": _session_get(s, "date_end", ""),
        "exam_date": _session_get(s, "exam_date", ""),
        "exam_theory_date": _session_get(s, "exam_theory_date", ""),
        "exam_practice_date": _session_get(s, "exam_practice_date", ""),
        "practice_training_date": _session_get(s, "practice_training_date", ""),
        "ssiap_exam_date": _session_get(s, "ssiap_exam_date", ""),
        "aps_elearning_enabled": bool(s.get("aps_elearning_enabled")),
    }

    trainees = _session_trainees_list(s)
    # Keep the individual trainee sheet consistent with the session roster: a
    # NUB recovered by the CNAPS tracking page must also enable the live title
    # badges when the sheet is opened directly (without visiting the roster
    # first).
    if session_view["training_type"] in {"APS", "A3P"}:
        _hydrate_missing_trainee_nubs_from_cnaps_tracking(trainees)
    t = next((x for x in trainees if x.get("id") == trainee_id), None)
    if not t:
        abort(404)

    _refresh_trainee_hebergement_status(s, t)

    # Le suivi CPF doit refléter WEDOF dès l'ouverture de la fiche. Le bouton
    # d'actualisation reste utile pour relancer manuellement une API indisponible,
    # mais il ne doit pas être nécessaire pour voir une transition d'état.
    if has_cpf_financing(t):
        cpf_link = _cpf_active_link(data, session_id=session_id, trainee_id=trainee_id)
        if cpf_link:
            try:
                _refresh_cpf_link_from_wedof(data, cpf_link)
            except (WedofApiError, WedofConfigurationError):
                cpf_link["cpf_sync_error"] = "Synchronisation momentanément indisponible"

    _remember_admin_trainee_consultation(session_id, trainee_id)

    training_type = session_view["training_type"]
    _sync_trainee_afc_medical_requirement(t, session_view["name"])
    default_price = default_training_price(training_type)

    # ✅ IMPORTANT : on impose la liste de documents selon la formation (et supprime dom)
    ensure_documents_schema_for_trainee(t, training_type)
    if (training_type or "").strip().upper() == "DIRIGEANT VAE":
        _ensure_livret2_document_entry(t)
        _ensure_complementary_documents_entry(t)

    # ✅ deliverables
    t.setdefault("deliverables", {})
    _private_documents(t)

    # file tokens for template links (documents)
    for d in (t.get("documents") or []):
        # compat: 1 fichier
        token = d.get("file") or ""
        d["file_token"] = token

        # ✅ multi-fichiers
        files = d.get("files")
        file_tokens = [x for x in files if x] if isinstance(files, list) else []
        if token and token not in file_tokens:
            file_tokens.insert(0, token)
        d["file_tokens"] = file_tokens

    # deliverables view
    deliverables_view = []
    for k, label in DELIVERABLE_LABELS.items():
        token = (t.get("deliverables", {}) or {}).get(k, "")
        deliverables_view.append({
            "key": k,
            "label": label,
            "file": token,
            "file_token": token,
        })

    show_vae = (training_type == "DIRIGEANT VAE")
    show_candidate_sheet = _is_dirigeant_candidate_sheet_training(training_type)
    vae_steps = [{"key": k, "label": v["label"], "pill": v["pill"]} for k, v in VAE_STATUS_STEPS.items()]
    vae_dossier = _vae_find_latest_for_trainee(str(t.get('id') or '')) if show_vae else None
    if not isinstance(t.get("vae_action_dates"), dict):
        t["vae_action_dates"] = {}
    _sync_vae_status_with_actions(t)
    ensure_vae_relances_state(t)
    refresh_vae_relance_schedule(t)
    _refresh_vtc_cm_reminder_schedule(t)

    # ✅ s'assure que les booléens dossiers sont cohérents
    t["no_permis"] = bool(t.get("no_permis"))
    t["no_bac_diploma"] = bool(t.get("no_bac_diploma"))
    t["force_dossier_complete"] = bool(t.get("force_dossier_complete"))
    if not (str(t.get("training_price") or "").strip()) and default_price is not None:
        t["training_price"] = default_price

    # ✅ dossier_status cohérent avec les docs requis
    dossier_complete = dossier_is_complete_total(t, training_type, _session_get(s, "date_start", ""))
    t["dossier_status"] = "complete" if dossier_complete else "incomplete"
    planned_relance_date = _docs_relance_planned_date(s)
    t["docs_relance_auto_planned_date"] = "" if dossier_complete else (planned_relance_date.isoformat() if planned_relance_date else "")
    if dossier_complete:
        t["docs_relance_auto_sent_at"] = ""
    t["updated_at"] = _now_iso()
    ensure_cnaps_history(t)
    _refresh_yousign_convention_status_if_pending(data, s, trainees, t)

    # ✅ persistance
    s["trainees"] = trainees
    s.pop("stagiaires", None)
    save_data(data)

    trainee_history = build_trainee_history_entries(t)
    trainee_email_history = build_trainee_email_history_entries(t)
    transfer_sessions = []
    for sess in data.get("sessions", []):
        sid = str(sess.get("id") or "").strip()
        if not sid or sid == session_id or bool(sess.get("archived")):
            continue
        transfer_sessions.append({
            "id": sid,
            "name": _session_get(sess, "name", ""),
            "training_type": _session_get(sess, "training_type", ""),
            "date_start": _session_get(sess, "date_start", ""),
            "date_end": _session_get(sess, "date_end", ""),
        })

    transfer_sessions.sort(key=lambda x: ((x.get("date_start") or "9999-99-99"), (x.get("name") or "").upper()))
    brevo_no_credit_notice = session.pop("brevo_no_credit_notice", None)

    return render_template(
        "admin_trainee.html",
        session=session_view,
        trainee=t,
        show_vae=show_vae,
        show_professional_experience_sheet=_professional_experience_sheet_is_required(training_type, _session_get(s, "date_start", "")),
        show_candidate_sheet=show_candidate_sheet,
        vae_steps=vae_steps,
        vae_dossier=vae_dossier,
        vae_relances=(t.get("vae_relances") or {}),
        dossier_is_complete=dossier_complete,
        deliverables_view=deliverables_view,
        default_training_price=default_price,
        trainee_history=trainee_history,
        trainee_email_history=trainee_email_history,
        transfer_sessions=transfer_sessions,
        PUBLIC_STUDENT_PORTAL_BASE=PUBLIC_STUDENT_PORTAL_BASE,
        fr_date=fr_date,
        brevo_no_credit_notice=brevo_no_credit_notice,
        automation_status=_build_trainee_automation_status(s, t, session_id, trainee_id) if _automation_document_config(s).get("enabled") else None,
        automation_module_locked=bool(_automation_document_config(s).get("enabled")) and not _automation_partner_module_enabled(),
        financing_module_locked=not _financing_partner_module_enabled(),
        cpf_tracking=build_cpf_view(t, s, data),
        cpf_association_preview=(session.get("cpf_association_preview") or {})
            if (session.get("cpf_association_preview") or {}).get("trainee_id") == trainee_id else None,
        docs_relance_planned_fr=fr_date(t.get("docs_relance_auto_planned_date") or ""),
        ssiap_medical_from_date=fr_date(_subtract_months(t.get("ssiap_exam_date") or "", 3)),
    )


def _cpf_local_registration(data: Dict[str, Any], session_id: str, trainee_id: str):
    local_session = find_session(data, session_id)
    if not local_session:
        return None, None
    trainee = next((x for x in _session_trainees_list(local_session)
                    if str(x.get("id")) == str(trainee_id)), None)
    return local_session, trainee


def _cpf_identity_mismatches(remote: Dict[str, Any], local_session: Dict[str, Any], trainee: Dict[str, Any]) -> List[str]:
    mismatches = []
    pairs = (("prénom", remote.get("first_name"), trainee.get("first_name") or trainee.get("prenom"), normalize_name),
             ("nom", remote.get("last_name"), trainee.get("last_name") or trainee.get("nom"), normalize_name),
             ("adresse e-mail", remote.get("email"), trainee.get("email") or trainee.get("mail"), normalize_email))
    for label, remote_value, local_value, normalizer in pairs:
        if remote_value and local_value and normalizer(remote_value) != normalizer(local_value):
            mismatches.append(label)
    remote_dates = (normalize_date(remote.get("start_date")), normalize_date(remote.get("end_date")))
    local_dates = (normalize_date(_session_get(local_session, "date_start", "")), normalize_date(_session_get(local_session, "date_end", "")))
    if all(remote_dates) and all(local_dates) and remote_dates != local_dates:
        mismatches.append("dates de session")
    return mismatches


def _cpf_public_snapshot(remote: Dict[str, Any]) -> Dict[str, Any]:
    now = _now_iso()
    allowed = ("external_id", "state", "type", "first_name", "last_name", "email", "start_date", "end_date",
               "training_title", "total_amount", "cpf_amount", "france_travail_amount", "candidate_amount",
               "created_at", "updated_at", "waiting_reason", "step_dates", "qonto_invoice_id",
               "qonto_invoice_number", "invoice_number", "billing_state", "invoice_status",
               "invoice_paid_at")
    snapshot = {key: remote.get(key) for key in allowed if remote.get(key) not in (None, "")}
    url = str(remote.get("wedof_url") or "").strip()
    parsed = urlparse(url)
    if parsed.scheme == "https" and (parsed.hostname or "").casefold().endswith("wedof.fr"):
        snapshot["wedof_url"] = url
    snapshot["synced_at"] = now
    return snapshot


def _refresh_cpf_link_from_wedof(data: Dict[str, Any], link: Dict[str, Any]) -> Dict[str, Any]:
    """Actualise en lecture seule le cache d'un lien CPF depuis WEDOF."""
    remote_folder = WedofClient().get_registration_folder_interactive(str(link.get("external_id") or ""))
    remote = extract_folder(remote_folder)
    if str(remote.get("type") or "").casefold() != "cpf":
        raise WedofApiError("Le dossier retourné n’est pas un dossier CPF.")
    link["cpf_snapshot"] = _cpf_public_snapshot(remote)
    link["wedof_state"] = remote.get("state") or link.get("wedof_state")
    link["last_seen_at"] = _now_iso()
    link.pop("cpf_sync_error", None)
    sync_folder_automation_status(data, remote_folder)
    return remote


CPF_ASSOCIATION_STATES = (
    "accepted", "inTraining", "serviceDoneDeclared", "serviceDoneValidated",
)


def _cpf_fetch_matchable_folders() -> List[Dict[str, Any]]:
    """Relit les dossiers CPF associables sans effectuer de mutation WEDOF."""
    client = WedofClient()
    folders_by_id: Dict[str, Dict[str, Any]] = {}
    for state in CPF_ASSOCIATION_STATES:
        for folder in client.list_registration_folders(state):
            if not isinstance(folder, dict):
                continue
            external_id = str(extract_folder(folder).get("external_id") or "").strip()
            if external_id:
                folders_by_id[external_id] = folder
    return list(folders_by_id.values())


def _cpf_active_link(data: Dict[str, Any], *, session_id: str, trainee_id: str) -> Optional[Dict[str, Any]]:
    return next((
        item for item in data.get("wedof_links", [])
        if isinstance(item, dict) and item.get("active") is True
        and str(item.get("session_id") or "") == str(session_id)
        and str(item.get("trainee_id") or "") == str(trainee_id)
    ), None)


def _cpf_candidate_payload(
    candidate: Dict[str, Any], data: Dict[str, Any], *, session_id: str, trainee_id: str
) -> Dict[str, Any]:
    external_id = str(candidate.get("external_id") or "")
    linked = next((
        item for item in data.get("wedof_links", [])
        if isinstance(item, dict) and item.get("active") is True
        and str(item.get("external_id") or "") == external_id
    ), None)
    linked_here = bool(
        linked
        and str(linked.get("session_id") or "") == str(session_id)
        and str(linked.get("trainee_id") or "") == str(trainee_id)
    )
    return {
        "external_id": external_id,
        "state": str(candidate.get("state") or ""),
        "first_name": str(candidate.get("first_name") or ""),
        "last_name": str(candidate.get("last_name") or ""),
        "email": str(candidate.get("email") or ""),
        "phone": str(candidate.get("phone") or ""),
        "training_title": str(candidate.get("training_title") or ""),
        "start_date": candidate.get("start_date"),
        "end_date": candidate.get("end_date"),
        "match_reasons": list(candidate.get("match_reasons") or []),
        "mismatches": list(candidate.get("mismatches") or []),
        "all_fields_match": bool(candidate.get("all_fields_match")),
        "automatic_match": bool(candidate.get("automatic_match")),
        "can_associate": linked is None or linked_here,
        "linked_elsewhere": bool(linked and not linked_here),
    }


def _persist_trainee_cpf_match(
    remote_folder: Dict[str, Any], *, session_id: str, trainee_id: str, automatic: bool
) -> Dict[str, Any]:
    """Enregistre atomiquement une suggestion vérifiée côté serveur."""
    remote_external_id = str(extract_folder(remote_folder).get("external_id") or "").strip()

    def mutate(canonical: Dict[str, Any]) -> Dict[str, Any]:
        local_session, trainee = _cpf_local_registration(canonical, session_id, trainee_id)
        if not local_session or not trainee or not has_cpf_financing(trainee):
            return {"status": "not_found", "message": "Stagiaire CPF introuvable."}

        candidates = find_trainee_cpf_candidates(
            [remote_folder], local_session, trainee, allowed_states=CPF_ASSOCIATION_STATES,
        )
        if not candidates or str(candidates[0].get("external_id") or "") != remote_external_id:
            return {
                "status": "contact_mismatch",
                "message": (
                    "Le dossier ne correspond plus suffisamment au nom, au prénom, "
                    "aux coordonnées ou à la session du stagiaire."
                ),
            }
        candidate = candidates[0]
        if automatic and not candidate.get("automatic_match"):
            return {
                "status": "manual_confirmation_required",
                "message": "Une confirmation administrateur reste nécessaire pour ce dossier.",
            }

        existing_registration = _cpf_active_link(
            canonical, session_id=session_id, trainee_id=trainee_id,
        )
        if existing_registration and str(existing_registration.get("external_id") or "") != remote_external_id:
            return {
                "status": "conflict",
                "message": "Ce stagiaire possède déjà une autre association CPF active.",
            }

        if automatic:
            summary = sync_exact_wedof_links(canonical, [{
                "status": "exact_match",
                "external_id": remote_external_id,
                "session_id": str(session_id),
                "trainee_id": str(trainee_id),
                "type": "cpf",
                "state": str(candidate.get("state") or ""),
                "rule": str(candidate.get("matching_rule") or "identity_dates_contact"),
                "start_date": candidate.get("start_date"),
                "end_date": candidate.get("end_date"),
            }])
            if summary.get("conflicts"):
                return {
                    "status": "conflict",
                    "message": "Ce dossier CPF est déjà associé à une autre inscription.",
                }
            outcome = "created" if summary.get("created") else "already_linked"
            history_source = "automatic_identity_dates_contact"
        else:
            outcome = save_manual_wedof_link(
                canonical,
                external_id=remote_external_id,
                session_id=session_id,
                trainee_id=trainee_id,
                state=str(candidate.get("state") or ""),
                date_start=normalize_date(candidate.get("start_date")),
                date_end=normalize_date(candidate.get("end_date")),
            )
            if outcome == "conflict":
                return {
                    "status": "conflict",
                    "message": "Ce dossier CPF est déjà associé à une autre inscription.",
                }
            history_source = "manual_contact_suggestion"

        link = next((
            item for item in canonical.get("wedof_links", [])
            if isinstance(item, dict) and item.get("active") is True
            and str(item.get("external_id") or "") == remote_external_id
            and str(item.get("session_id") or "") == str(session_id)
            and str(item.get("trainee_id") or "") == str(trainee_id)
        ), None)
        if link is None:
            return {
                "status": "conflict",
                "message": "L’association n’a pas pu être enregistrée en toute sécurité.",
            }

        link["cpf_snapshot"] = _cpf_public_snapshot(candidate)
        link["wedof_state"] = candidate.get("state") or link.get("wedof_state")
        link["last_seen_at"] = _now_iso()
        sync_folder_automation_status(canonical, remote_folder)
        if outcome == "created":
            link.setdefault("association_history", []).append({
                "at": _now_iso(),
                "admin": session.get("admin_username") or "admin",
                "old_external_id": None,
                "new_external_id": remote_external_id,
                "source": history_source,
            })
        return {
            "status": "associated",
            "outcome": outcome,
            "external_id": remote_external_id,
            "automatic": automatic,
        }

    return _atomic_update_data(mutate)


def _cpf_match_json_error(message: str, status_code: int):
    return jsonify({"ok": False, "status": "error", "message": message}), status_code


@app.post("/admin/sessions/<session_id>/stagiaires/<trainee_id>/cpf/auto-match")
@admin_login_required
@admin_write_required
def admin_trainee_cpf_auto_match(session_id: str, trainee_id: str):
    data = load_data(run_background_tasks=False)
    local_session, trainee = _cpf_local_registration(data, session_id, trainee_id)
    if not trainee or not has_cpf_financing(trainee):
        abort(404)

    existing = _cpf_active_link(data, session_id=session_id, trainee_id=trainee_id)
    redirect_url = url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id) + "#cpfTracking"
    if existing:
        session.pop("cpf_association_preview", None)
        return jsonify({
            "ok": True, "status": "associated", "automatic": False,
            "external_id": existing.get("external_id"), "redirect_url": redirect_url,
        })

    try:
        folders = _cpf_fetch_matchable_folders()
    except (WedofConfigurationError, WedofApiError):
        return _cpf_match_json_error(
            "La recherche WEDOF est momentanément indisponible. Vous pouvez la relancer ou saisir le numéro du dossier.",
            503,
        )

    candidates = find_trainee_cpf_candidates(
        folders, local_session, trainee, allowed_states=CPF_ASSOCIATION_STATES,
    )
    automatic_candidates = [item for item in candidates if item.get("automatic_match")]
    # Un dossier peut être associé sans reprendre exactement le même e-mail,
    # mais jamais si un autre dossier partage lui aussi un signal fort sur les
    # mêmes dates. Dans ce cas, l'administrateur doit choisir explicitement.
    credible_on_session_dates = [
        item for item in candidates
        if item.get("dates_match") and (
            item.get("identity_match") or item.get("email_match") or item.get("phone_match")
        )
    ]
    if len(automatic_candidates) == 1 and len(credible_on_session_dates) == 1:
        remote_folder = next(
            folder for folder in folders
            if str(extract_folder(folder).get("external_id") or "")
            == str(automatic_candidates[0].get("external_id") or "")
        )
        result = _persist_trainee_cpf_match(
            remote_folder, session_id=session_id, trainee_id=trainee_id, automatic=True,
        )
        if result.get("status") == "associated":
            session.pop("cpf_association_preview", None)
            return jsonify({
                "ok": True, **result, "redirect_url": redirect_url,
                "message": (
                    "Dossier CPF associé automatiquement : le nom, le prénom, les dates "
                    "et au moins une coordonnée concordent."
                ),
            })
        if result.get("status") != "conflict":
            return _cpf_match_json_error(
                str(result.get("message") or "L’association automatique n’a pas pu être enregistrée."), 409,
            )
        # Une autre requête a pu créer le lien pendant la lecture WEDOF.
        # Relire l'état canonique permet de désactiver correctement la suggestion.
        data = load_data(run_background_tasks=False)

    public_candidates = [
        _cpf_candidate_payload(item, data, session_id=session_id, trainee_id=trainee_id)
        for item in candidates
    ]
    status = "suggestions" if public_candidates else "no_match"
    message = (
        "Un dossier probable a été trouvé grâce à l’identité, aux coordonnées ou aux dates. "
        "Vérifiez-le puis cliquez sur « Associer ce dossier »."
        if len(public_candidates) == 1
        else f"{len(public_candidates)} dossiers possibles ont été trouvés. Choisissez le bon dossier."
        if public_candidates
        else (
            "Aucun dossier WEDOF ne correspond suffisamment au nom, au prénom, "
            "aux coordonnées ou aux dates de formation du stagiaire."
        )
    )
    return jsonify({
        "ok": True, "status": status, "message": message,
        "candidates": public_candidates,
    })


@app.post("/admin/sessions/<session_id>/stagiaires/<trainee_id>/cpf/associate-match")
@admin_login_required
@admin_write_required
def admin_trainee_cpf_associate_match(session_id: str, trainee_id: str):
    external_id = str(request.form.get("external_id") or "").strip()
    if not external_id:
        return _cpf_match_json_error("Le numéro du dossier CPF est obligatoire.", 400)
    data = load_data(run_background_tasks=False)
    local_session, trainee = _cpf_local_registration(data, session_id, trainee_id)
    if not trainee or not has_cpf_financing(trainee):
        abort(404)
    try:
        remote_folder = WedofClient().get_registration_folder_interactive(external_id)
    except (WedofConfigurationError, WedofApiError):
        return _cpf_match_json_error(
            "WEDOF est momentanément indisponible. L’association n’a pas été modifiée.", 503,
        )
    remote = extract_folder(remote_folder)
    if str(remote.get("external_id") or "") != external_id:
        return _cpf_match_json_error("Le dossier retourné par WEDOF ne correspond pas au numéro demandé.", 409)

    result = _persist_trainee_cpf_match(
        remote_folder, session_id=session_id, trainee_id=trainee_id, automatic=False,
    )
    if result.get("status") != "associated":
        code = 409 if result.get("status") in {
            "contact_mismatch", "conflict", "manual_confirmation_required",
        } else 404
        return _cpf_match_json_error(
            str(result.get("message") or "Le dossier CPF n’a pas pu être associé."), code,
        )
    session.pop("cpf_association_preview", None)
    return jsonify({
        "ok": True, **result,
        "message": "Dossier CPF associé au stagiaire.",
        "redirect_url": url_for("admin_trainee_page", session_id=session_id, trainee_id=trainee_id) + "#cpfTracking",
    })


