def _billing_lines_for_session(data: Dict[str, Any], session_id: str) -> List[Dict[str, Any]]:
    return [l for l in _billing_lines(data) if str(l.get('sessionId')) == str(session_id)]


def _billing_lines_for_trainee_session(data: Dict[str, Any], trainee_id: str, session_id: str) -> List[Dict[str, Any]]:
    return [l for l in _billing_lines_for_session(data, session_id) if str(l.get('traineeId')) == str(trainee_id)]


def _billing_line_qonto_sync_due(line: Dict[str, Any], now: Optional[datetime.datetime] = None) -> bool:
    last_synced_at = _parse_iso_datetime(
        line.get('qontoLastSyncedAt') or line.get('qonto_last_synced_at') or ''
    )
    if last_synced_at is None:
        return True
    current = now or datetime.datetime.now(datetime.timezone.utc).replace(tzinfo=None)
    if current.tzinfo is not None:
        current = current.astimezone(datetime.timezone.utc).replace(tzinfo=None)
    return (current - last_synced_at).total_seconds() >= QONTO_TRAINEE_AUTO_SYNC_TTL_SECONDS


@app.get('/api/billing/session/<session_id>')
@admin_login_required
def api_billing_session(session_id: str):
    data = load_data()
    lines = _billing_lines_for_session(data, session_id)
    _repair_logged_qonto_rejection_retries(data, lines)
    lines = _billing_lines_for_session(data, session_id)
    if _qonto_is_configured():
        changed = False
        for line in lines:
            if line.get('qontoInvoiceId') or line.get('qontoDraftId'):
                try:
                    reset, _ = _sync_billing_line_with_qonto(data, line); changed = changed or reset
                except Exception:
                    line['syncWarning'] = 'Synchronisation Qonto impossible pour le moment'
        if changed:
            save_data(data)
    return jsonify({'ok': True, 'lines': _billing_lines_for_session(data, session_id)})


@app.get('/api/billing/trainee/<trainee_id>/session/<session_id>')
@admin_login_required
def api_billing_trainee_session(trainee_id: str, session_id: str):
    data = load_data()
    session_obj = next(
        (sess for sess in data.get('sessions', []) if str(sess.get('id')) == str(session_id)),
        None,
    )
    trainee = next(
        (
            item
            for item in _session_trainees_list(session_obj or {})
            if str(item.get('id')) == str(trainee_id)
        ),
        None,
    )
    lines = _billing_lines_for_trainee_session(data, trainee_id, session_id)
    _repair_logged_qonto_rejection_retries(data, lines)
    cpf_sync_attempted = False
    data_changed = False
    if _qonto_is_configured():
        has_cpf_invoice = any(
            is_cpf_billing_context(line)
            and bool(line.get('qontoInvoiceId') or line.get('qontoDraftId'))
            for line in lines
        )
        if session_obj and trainee and not has_cpf_invoice:
            _, discovery_changed = _discover_cpf_qonto_invoice(data, session_obj, trainee)
            data_changed = data_changed or discovery_changed
            if discovery_changed:
                lines = _billing_lines_for_trainee_session(data, trainee_id, session_id)
        for line in lines:
            if not is_cpf_billing_context(line) or not (line.get('qontoInvoiceId') or line.get('qontoDraftId')):
                continue
            if not _billing_line_qonto_sync_due(line):
                continue
            cpf_sync_attempted = True
            try:
                _sync_billing_line_with_qonto(data, line)
            except Exception as exc:
                line['syncWarning'] = 'Synchronisation de la facture CPF impossible pour le moment'
                _billing_log(line, 'Synchronisation automatique facture CPF indisponible', 'error', _sanitize_qonto_error(str(exc)), line.get('qontoInvoiceId') or '')
                _save_billing_line(data, line)
        if cpf_sync_attempted or data_changed:
            # Persist the Qonto payment state recovered while the trainee card
            # loads, including a non-blocking warning when Qonto is unavailable.
            save_data(data)
    fresh_lines = (
        _billing_lines_for_trainee_session(data, trainee_id, session_id)
        if cpf_sync_attempted or data_changed
        else lines
    )
    summary = calculate_trainee_financial_summary(trainee or {'id': trainee_id}, fresh_lines)
    cpf_link = _cpf_active_link(data, session_id=str(session_id), trainee_id=str(trainee_id))
    return jsonify({
        'ok': True,
        'lines': fresh_lines,
        'financial_summary': summary,
        'cpf_wedof_invoice': _cpf_wedof_invoice_view(cpf_link),
        'cpf_invoice_discovery': (
            trainee.get('cpf_qonto_invoice_discovery')
            if isinstance((trainee or {}).get('cpf_qonto_invoice_discovery'), dict)
            else {}
        ),
    })


def _line_from_payload(data: Dict[str, Any], payload: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    line_id = str(payload.get('lineId') or payload.get('billingLineId') or '')
    if line_id:
        return _find_billing_line(data, line_id)
    sid, tid, ftype = str(payload.get('sessionId') or ''), str(payload.get('traineeId') or ''), str(payload.get('financingType') or payload.get('typeFinanceur') or '')
    candidates = [l for l in _billing_lines_for_trainee_session(data, tid, sid) if not ftype or l.get('financingType') == ftype]
    return candidates[0] if candidates else None


def _apply_invoice_recipient_payload(line: Dict[str, Any], payload: Dict[str, Any]) -> None:
    """Apply administrator-entered invoice recipient data to an AUTRE line."""
    if 'AUTRE' not in str(line.get('financingType') or line.get('typeFinanceur') or '').upper():
        return
    recipient = payload.get('invoiceRecipient') if isinstance(payload.get('invoiceRecipient'), dict) else {}
    fields = {
        'companyName': 'companyName', 'clientEmail': 'email', 'clientAddress': 'address',
        'clientZipCode': 'zipCode', 'clientCity': 'city', 'siret': 'siret',
        'invoiceNotes': 'invoiceNotes',
    }
    for target, source in fields.items():
        if source in recipient:
            line[target] = str(recipient.get(source) or '').strip()
    if line.get('companyName'):
        line['clientName'] = line['companyName']




def _billing_line_qonto_preview(line: Dict[str, Any]) -> Dict[str, Any]:
    vat_rate = _money(line.get('vatRate'))
    amount_ttc = _money(line.get('amount'))
    amount_ht = round(amount_ttc / (1 + vat_rate / 100), 2) if vat_rate else amount_ttc
    amount_tva = round(amount_ttc - amount_ht, 2)
    label = qonto_invoice_item_label(line)
    client = build_qonto_client_payload(line, line, {'id': line.get('sessionId')}, line.get('financingType') or line.get('financingLabel'))
    errors = validate_qonto_client_payload(client, line if is_cpf_billing_context(line) else line.get('financingType'))
    return {
        'line': line,
        'client': client,
        'validation_errors': errors,
        'invoice': {
            'trainee': f"{line.get('traineeFirstName','')} {line.get('traineeLastName','')}".strip(),
            'session': line.get('sessionName') or line.get('sessionId'),
            'formation': line.get('formationName'),
            'financeur_type': line.get('financingType') or line.get('financingLabel'),
            'amount_ht': amount_ht,
            'vat_rate': vat_rate,
            'amount_tva': amount_tva,
            'amount_ttc': amount_ttc,
            'currency': 'EUR',
            'label': label,
            'issue_date': datetime.date.today().isoformat(),
            'due_date': (datetime.date.today() + datetime.timedelta(days=30)).isoformat(),
        },
    }


def _billing_invoice_fallback_html(line: Dict[str, Any], error_message: str = "") -> str:
    preview = _billing_line_qonto_preview(line)
    invoice = preview.get('invoice') or {}
    client = preview.get('client') or {}
    client_full_name = f"{client.get('first_name','')} {client.get('last_name','')}".strip()
    client_name = html.escape(str(client.get('name') or client_full_name or line.get('clientName') or 'Client'))
    trainee = html.escape(str(invoice.get('trainee') or ''))
    invoice_ref = html.escape(str(line.get('qontoInvoiceNumber') or line.get('qontoInvoiceId') or 'Facture'))
    label = html.escape(str(invoice.get('label') or line.get('formationName') or 'Formation'))
    amount_ht = html.escape(f"{_money(invoice.get('amount_ht')):.2f} €")
    amount_tva = html.escape(f"{_money(invoice.get('amount_tva')):.2f} €")
    amount_ttc = html.escape(f"{_money(invoice.get('amount_ttc')):.2f} €")
    issue_date_raw = str(invoice.get('issue_date') or '')
    due_date_raw = str(invoice.get('due_date') or '')
    issue_date = html.escape(fr_date(issue_date_raw) or issue_date_raw)
    due_date = html.escape(fr_date(due_date_raw) or due_date_raw)
    warning = ''
    if error_message:
        sanitized = html.escape(_sanitize_qonto_error(error_message))
        warning = f'<p class="warning">Affichage local temporaire : le PDF Qonto n’est pas encore disponible ({sanitized}).</p>'
    return f'''<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<title>Facture {invoice_ref}</title>
<style>
body{{font-family:Arial,sans-serif;margin:32px;color:#172033}}
.header{{display:flex;justify-content:space-between;gap:24px;border-bottom:2px solid #111827;padding-bottom:18px}}
h1{{margin:0;font-size:32px}}
.card{{margin-top:24px;padding:18px;border:1px solid #d8dee9;border-radius:12px}}
table{{width:100%;border-collapse:collapse;margin-top:24px}}
th,td{{padding:12px;border-bottom:1px solid #e5e7eb;text-align:left}}
th{{background:#f8fafc}}
.total{{font-weight:700;font-size:18px}}
.warning{{padding:12px;border-radius:8px;background:#fff7ed;color:#9a3412}}
@media print{{button{{display:none}} body{{margin:18mm}}}}
</style>
</head>
<body>
<button onclick="window.print()">Imprimer / enregistrer en PDF</button>
{warning}
<div class="header"><div><h1>Facture</h1><p>Intégrale Academy</p></div><div><strong>{invoice_ref}</strong><br>Émise le {issue_date}<br>Échéance {due_date}</div></div>
<div class="card"><strong>Client</strong><br>{client_name}<br><br><strong>Stagiaire</strong><br>{trainee}</div>
<table><thead><tr><th>Désignation</th><th>HT</th><th>TVA</th><th>TTC</th></tr></thead><tbody><tr><td>{label}</td><td>{amount_ht}</td><td>{amount_tva}</td><td>{amount_ttc}</td></tr></tbody><tfoot><tr><td colspan="3" class="total">Total TTC</td><td class="total">{amount_ttc}</td></tr></tfoot></table>
</body></html>'''


