@app.post("/api/admin/trainees/<trainee_id>/qonto-invoice/create")
@admin_login_required
@admin_write_required
def api_qonto_invoice_create(trainee_id: str):
    data = load_data(); sess, trainees, trainee = _find_trainee_any_session(data, trainee_id)
    if not trainee: return jsonify({"ok": False, "error": "Stagiaire introuvable"}), 404
    inv = _qonto_invoice_state(trainee)
    if inv.get("qonto_invoice_id"): return jsonify({"ok": False, "error": "Facture déjà créée pour ce stagiaire", **_qonto_status_payload(trainee)}), 409
    if not _qonto_is_configured(): return jsonify({"ok": False, "error": "Qonto n’est pas connecté"}), 400
    payload = request.get_json(silent=True) or {}
    client = payload.get("client") or {}; invoice = payload.get("invoice") or {}
    is_cpf_invoice = is_cpf_billing_context(payload) or is_cpf_billing_context(trainee) or _is_cpf_financeur(client.get("name")) or (client.get("name") == CPF_QONTO_CLIENT_NAME)
    if is_cpf_invoice:
        return jsonify({"ok": False, "error": "La facturation CPF est gérée dans un logiciel externe."}), 400
    missing = []
    if not is_cpf_invoice and not (client.get("email") or "").strip(): missing.append("email")
    try:
        billing_address = build_qonto_billing_address_from_modal(client)
    except ValueError as exc:
        billing_message = str(exc)
        missing.extend(_qonto_billing_address_missing_fields(client))
        return jsonify({"ok": False, "message": billing_message, "error": billing_message, "missing_fields": missing}), 400
    if _money(invoice.get("unit_price_ht") or invoice.get("amount_ht")) <= 0: missing.append("montant")
    if missing:
        message = "Champs obligatoires manquants : " + ", ".join(missing)
        return jsonify({"ok": False, "message": message, "error": message, "missing_fields": missing}), 400
    try:
        invoice_iban = get_qonto_invoice_iban()
    except ValueError:
        app.logger.warning("[QONTO] create invoice skipped trainee_id=%s missing_iban=true", trainee_id)
        return jsonify({"ok": False, "error": "IBAN Qonto manquant. Ajoutez QONTO_IBAN dans les variables Render."}), 400
    try:
        app.logger.info(
            "[QONTO] modal client address street=%s zip=%s city=%s country=%s",
            client.get("address") or client.get("street_address"),
            client.get("zip_code") or client.get("postal_code"),
            client.get("city"),
            client.get("country_code") or client.get("country"),
        )
        if is_cpf_invoice:
            q_client = get_or_create_cpf_qonto_client()
        else:
            qonto_client_payload = remove_invalid_qonto_phone(build_qonto_client_payload(client, billing_address))
            q_client = get_or_create_qonto_billing_client(qonto_client_payload)
        q_client_id = (q_client.get("client") or q_client).get("id")
        if not q_client_id: raise RuntimeError("Impossible de créer le client Qonto")
        start = (payload.get("session") or {}).get("date_start") or _session_get(sess, "date_start", "")[:10]
        end = (payload.get("session") or {}).get("date_end") or _session_get(sess, "date_end", "")[:10]
        amount_ht = invoice.get("unit_price_ht") or invoice.get("amount_ht")
        app.logger.info(
            "[QONTO] create invoice payload check client_id=%s has_iban=%s iban_last4=%s amount=%s",
            q_client_id,
            bool(invoice_iban),
            invoice_iban[-4:],
            invoice.get("amount_ht"),
        )
        qonto_invoice_payload = {
            "client_id": q_client_id,
            "issue_date": invoice.get("issue_date"),
            "due_date": invoice.get("due_date"),
            "currency": "EUR",
            "payment_methods": {"iban": invoice_iban},
            "performance_start_date": start,
            "performance_end_date": end,
            "status": "draft",
            "terms_and_conditions": invoice.get("conditions"),
            "items": [{
                "title": invoice.get("label"),
                "description": invoice.get("label"),
                "quantity": "1",
                "unit_price": {
                    "value": str(amount_ht),
                    "currency": "EUR",
                },
                "vat_rate": format_qonto_vat_rate(0 if is_cpf_invoice else (invoice.get("vat_rate") or 20)),
            }],
        }
        safe_payload = dict(qonto_invoice_payload)
        safe_payload["payment_methods"] = {"iban": "***" + invoice_iban[-4:]}
        app.logger.info("[QONTO] invoice payload=%s", safe_payload)
        q_inv = create_qonto_invoice(qonto_invoice_payload)
        qi = q_inv.get("client_invoice") or q_inv.get("invoice") or q_inv
        now = _now_iso(); inv.update({"id": inv.get("id") or str(uuid.uuid4()), "trainee_id": trainee_id, "qonto_client_id": q_client_id, "qonto_invoice_id": qi.get("id"), "qonto_invoice_number": qi.get("number") or qi.get("invoice_number") or "", "qonto_invoice_status": qi.get("status") or "draft", "qonto_invoice_paid_at": qi.get("paid_at") or "", "qonto_invoice_amount_paid": _normalize_qonto_amount(qi.get("amount_paid")), "qonto_invoice_url": qi.get("public_url") or qi.get("url") or "", "client_name": client.get("name"), "client_email": client.get("email"), "billing_address": dict(billing_address), "amount_ht": _money(invoice.get("amount_ht") or invoice.get("unit_price_ht")), "amount_tva": _money(invoice.get("amount_tva")), "amount_ttc": _money(invoice.get("amount_ttc")), "currency": "EUR", "issue_date": invoice.get("issue_date"), "due_date": invoice.get("due_date"), "created_at": now, "last_error": ""})
        if payload.get("save_billing_address"):
            trainee["address"] = billing_address["street_address"]
            trainee["zip_code"] = billing_address["zip_code"]
            trainee["city"] = billing_address["city"]
            trainee["qonto_billing_country_code"] = billing_address["country_code"]
        if not inv.get("qonto_invoice_id"): raise RuntimeError("Impossible de créer la facture Qonto")
        sess["trainees"] = trainees; save_data(data)
        return jsonify({"ok": True, "message": "Facture brouillon Qonto créée", **_qonto_status_payload(trainee)})
    except Exception as exc:
        sanitized_error = _sanitize_qonto_error(str(exc))
        app.logger.exception("[QONTO] create invoice failed: %s", sanitized_error)
        inv["qonto_invoice_status"] = "error"; inv["last_error"] = sanitized_error; sess["trainees"] = trainees; save_data(data)
        if _is_qonto_missing_iban_error(sanitized_error):
            return jsonify({"ok": False, "error": "Impossible de créer la facture Qonto : l’IBAN de paiement Qonto est manquant. Ajoutez QONTO_IBAN dans Render."}), 400
        if "phone" in sanitized_error.lower():
            return jsonify({"ok": False, "error": "Le téléphone client n’a pas été envoyé à Qonto car il n’est pas obligatoire."}), 400
        return jsonify({"ok": False, "error": format_qonto_error_for_front(exc)}), 400


