@app.get("/admin/sessions/<session_id>/stagiaires/<trainee_id>/summary")
@admin_login_required
def admin_trainee_summary(session_id: str, trainee_id: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        abort(404)

    trainees = _session_trainees_list(s)
    t = next((x for x in trainees if x.get("id") == trainee_id), None)
    if not t:
        abort(404)
    app.logger.info(
        "SUMMARY LOAD trainee_id=%s source_file=%s printed=%s printed_at=%s",
        trainee_id,
        DATA_FILE,
        t.get("printed"),
        t.get("printed_at"),
    )

    training_name = (s.get("name") or "").strip() or formation_label(_session_get(s, "training_type", ""))
    training_type = _session_get(s, "training_type", "")
    default_price = default_training_price(training_type)
    dstart = fr_date(_session_get(s, "date_start", ""))
    dend = fr_date(_session_get(s, "date_end", ""))
    formation_dates = f"Du {dstart} au {dend}" if dstart and dend else "Dates à confirmer"

    session_view = {
        "id": s.get("id"),
        "name": _session_get(s, "name", ""),
        "training_type": training_type,
        "date_start": _session_get(s, "date_start", ""),
        "date_end": _session_get(s, "date_end", ""),
    }

    training_type_key = (training_type or "").strip().upper()
    summary_training_badge = {"label": "FORMATION", "color": "gray"}
    if training_type_key.startswith("SSIAP"):
        summary_training_badge = {"label": training_type_key, "color": "red"}
    elif "VAE" in training_type_key:
        summary_training_badge = {"label": "VAE", "color": "orange"}
    elif "DIRIGEANT" in training_type_key:
        summary_training_badge = {"label": "DIRIGEANT", "color": "orange"}
    elif "APS" in training_type_key:
        summary_training_badge = {"label": "APS", "color": "blue"}
    elif "VTC" in training_type_key:
        summary_training_badge = {"label": "VTC", "color": "purple"}
    elif "A3P" in training_type_key:
        summary_training_badge = {"label": "A3P", "color": "green"}

    return render_template(
        "admin_trainee_summary.html",
        session=session_view,
        trainee=t,
        training_name=training_name or "Formation",
        formation_dates=formation_dates,
        is_vtc=("VTC" in (_session_get(s, "training_type", "") or "").upper()),
        summary_training_badge=summary_training_badge,
        summary_training_price=t.get("training_price") or default_price,
    )


