@app.post("/api/stagiaires/<trainee_id>/mark-printed")
@admin_login_required
def api_mark_trainee_printed(trainee_id: str):
    try:
        payload = request.get_json(silent=True) or {}
        printed = payload.get("printed", True)
        printed = printed if isinstance(printed, bool) else str(printed).strip().lower() in {"1", "true", "yes", "oui"}
        app.logger.info("MARK PRINTED START trainee_id=%s printed=%s", trainee_id, printed)

        data = load_data()
        found = False
        printed_at = _now_iso() if printed else ""

        for s in data.get("sessions", []):
            if isinstance(s.get("trainees"), list):
                for t in s["trainees"]:
                    if str(t.get("id")) == str(trainee_id):
                        app.logger.info("FOUND in trainees[]")
                        t["printed"] = printed
                        t["printed_at"] = printed_at
                        if not printed:
                            t["summary_printed_at"] = ""
                        found = True

            if isinstance(s.get("stagiaires"), list):
                for t in s["stagiaires"]:
                    if str(t.get("id")) == str(trainee_id):
                        app.logger.info("FOUND in stagiaires[]")
                        t["printed"] = printed
                        t["printed_at"] = printed_at
                        if not printed:
                            t["summary_printed_at"] = ""
                        found = True

        if not found:
            app.logger.error("TRAINEE NOT FOUND %s", trainee_id)
            return jsonify({"success": False, "error": "not found"}), 404

        save_data(data)
        app.logger.info("SAVE OK trainee_id=%s printed=%s", trainee_id, printed)

        return jsonify({"success": True, "printed": printed, "printed_at": printed_at})

    except Exception as e:
        import traceback
        traceback.print_exc()
        app.logger.error("ERROR MARK PRINTED: %s", str(e))
        return jsonify({"success": False, "error": str(e)}), 500


@app.get("/admin/sessions/<session_id>/stagiaires/<trainee_id>/fiche-adef")
@admin_login_required
def admin_trainee_adef_sheet(session_id: str, trainee_id: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        abort(404)

    trainees = _session_trainees_list(s)
    t = next((x for x in trainees if x.get("id") == trainee_id), None)
    if not t:
        abort(404)

    training_type = _session_get(s, "training_type", "")
    if not _is_adef_training(training_type):
        abort(404)

    if (t.get("dossier_status") or "").strip().lower() != "complete":
        abort(404)

    def pick(*values: Any) -> str:
        for value in values:
            txt = str(value or "").strip()
            if txt:
                return txt
        return ""

    birth_date_value = pick(t.get("birth_date"))
    birth_year = ""
    birth_month = ""
    if birth_date_value:
        try:
            dt = datetime.strptime(birth_date_value, "%Y-%m-%d")
            birth_year = str(dt.year)
            birth_month = f"{dt.month:02d}"
        except Exception:
            pass

    adef_data = {
        "social_security_number": pick(t.get("carte_vitale"), t.get("social_security_number"), t.get("ssn"), t.get("num_secu")),
        "nationality_birth_country": " - ".join([v for v in [pick(t.get("nationality")), pick(t.get("birth_country"))] if v]),
        "sex": pick(t.get("sex"), t.get("gender")),
        "birth_year": birth_year,
        "birth_month": birth_month,
        "civility": pick(t.get("civility"), t.get("civilite"), t.get("title")),
        "last_name": pick(t.get("last_name")),
        "first_name": pick(t.get("first_name")),
        "birth_date": fr_date(birth_date_value) or birth_date_value,
        "birth_city_country": " - ".join([v for v in [pick(t.get("birth_city")), pick(t.get("birth_country"))] if v]),
        "nationality": pick(t.get("nationality")),
        "address": pick(t.get("address")),
        "zip_code": pick(t.get("zip_code")),
        "city": pick(t.get("city")),
        "pre_or_car": pick(t.get("pre_number")),
    }

    return render_template(
        "admin_trainee_adef_sheet.html",
        session=s,
        trainee=t,
        adef=adef_data,
    )


def _build_candidate_sheet_data(session_data: Dict[str, Any], trainee_data: Dict[str, Any]) -> Dict[str, Any]:
    dossier = _vae_find_latest_for_trainee(str(trainee_data.get("id") or ""))
    candidat = (dossier or {}).get("candidat") or {}

    def pick(*values: Any) -> str:
        for value in values:
            txt = str(value or "").strip()
            if txt:
                return txt
        return ""

    def clean_phone(value: Any) -> str:
        raw = re.sub(r"\D", "", str(value or ""))
        if len(raw) == 10:
            return " ".join(raw[i:i + 2] for i in range(0, len(raw), 2))
        return str(value or "").strip()

    training_type = (_session_get(session_data, "training_type", "") or "").strip().upper()
    default_formation_type = "FORMATION INITIALE" if training_type == "DIRIGEANT INITIAL" else "Validation des acquis de l'expérience (VAE)"

    payload = {
        "formation_type": default_formation_type,
        "date_entree_stage": fr_date(_session_get(session_data, "date_start", "")) or "",
        "situation": pick(candidat.get("statut")),
        "company": pick(trainee_data.get("company_name"), trainee_data.get("employer"), trainee_data.get("entreprise")),
        "financing": "",
        "interviewer": "Clément VAILLANT",
        "last_name": pick(trainee_data.get("last_name"), candidat.get("nom_naissance")),
        "usage_name": pick(candidat.get("nom_usage")),
        "first_names": pick(trainee_data.get("first_name"), candidat.get("prenoms")),
        "address": pick(trainee_data.get("address"), candidat.get("adresse")),
        "postal_code": pick(trainee_data.get("zip_code"), trainee_data.get("postal_code")),
        "city": pick(trainee_data.get("city"), trainee_data.get("birth_city")),
        "phone": clean_phone(pick(trainee_data.get("phone"), candidat.get("telephone"))),
        "email": pick(trainee_data.get("email"), candidat.get("email")),
        "birth_date": fr_date(pick(trainee_data.get("birth_date"), candidat.get("date_naissance"))) or pick(trainee_data.get("birth_date"), candidat.get("date_naissance")),
        "birth_city": pick(trainee_data.get("birth_city"), trainee_data.get("birth_place")),
        "department": pick(trainee_data.get("department")),
        "country": pick(trainee_data.get("country"), "France"),
        "nationality": pick(trainee_data.get("nationality"), candidat.get("nationalite")),
        "emergency_contact": pick(trainee_data.get("emergency_contact"), trainee_data.get("emergency_phone")),
        "cnaps_number": "",
        "study_level": pick(candidat.get("niveau_formation")),
        "study_domain": pick(trainee_data.get("study_domain")),
        "last_certification_level": pick(candidat.get("niveau_certification")),
        "last_certification_domain": pick(trainee_data.get("last_certification_domain")),
        "last_job": pick(trainee_data.get("last_job")),
        "years_experience": pick(trainee_data.get("years_experience")),
        "company_name": pick(trainee_data.get("company_name"), trainee_data.get("employer")),
        "gross_salary": pick(trainee_data.get("gross_salary")),
    }

    saved_sheet = trainee_data.get("candidate_sheet")
    if isinstance(saved_sheet, dict):
        for key in payload.keys():
            if key in saved_sheet:
                payload[key] = str(saved_sheet.get(key) or "").strip()

    return payload


@app.post("/espace/<token>/fiche-candidat/enregistrer")
def public_trainee_candidate_sheet_save(token: str):
    data = load_data()
    s, t = find_session_and_trainee_by_token(data, token)
    if not s or not t:
        abort(404)

    if not _public_is_authed(token):
        return redirect(url_for("public_trainee_login", token=token))

    training_type = (_session_get(s, "training_type", "") or "").strip().upper()
    if not _is_dirigeant_candidate_sheet_training(training_type):
        abort(404)

    base_sheet = _build_candidate_sheet_data(s, t)
    saved_sheet: Dict[str, str] = {}
    for key in base_sheet.keys():
        saved_sheet[key] = str(request.form.get(key, "") or "").strip()
    t["candidate_sheet"] = saved_sheet
    t["candidate_sheet_saved_at"] = _now_iso()

    ensure_documents_schema_for_trainee(t, training_type)

    t["updated_at"] = _now_iso()
    t["dossier_status"] = "complete" if dossier_is_complete_total(t, training_type, _session_get(s, "date_start", "")) else "incomplete"

    s["trainees"] = _session_trainees_list(s)
    s.pop("stagiaires", None)
    save_data(data)

    return redirect(url_for("public_trainee_space", token=token) + "#doc_candidate_info_sheet")


