@app.post("/api/cnaps/pre_request")
@admin_login_required
@admin_write_required
def api_cnaps_pre_request():
    payload = request.get_json(silent=True) or {}
    items = payload.get("items") if isinstance(payload.get("items"), list) else []
    if not items:
        return jsonify({"ok": False, "error": "no_items"}), 400

    data = load_data()
    updated = 0

    for item in items:
        session_id = str(item.get("session_id") or "").strip()
        trainee_id = str(item.get("trainee_id") or "").strip()
        if not session_id or not trainee_id:
            continue
        s = find_session(data, session_id)
        if not s:
            continue
        trainees = _session_trainees_list(s)
        t = next((x for x in trainees if x.get("id") == trainee_id), None)
        if not t:
            continue
        record_cnaps_pre_request(t)
        updated += 1
        s["trainees"] = trainees
        s.pop("stagiaires", None)

    if updated:
        save_data(data)

    return jsonify({"ok": True, "updated": updated})


@app.post("/api/cnaps/import-pre")
@admin_login_required
def api_cnaps_import_pre():
    files = request.files.getlist("files")
    if not files:
        single = request.files.get("file")
        if single:
            files = [single]

    valid_files = [f for f in files if f and (f.filename or "").lower().endswith(".pdf")]
    if not valid_files:
        return jsonify({"ok": False, "error": "missing_pdf"}), 400

    data = load_data()
    pending = _cnaps_pending_imports(data)
    pending_hashes = {
        (item.get("sha1") or "").strip().lower()
        for item in pending
        if (item.get("sha1") or "").strip()
    }
    trainees_index: Dict[Tuple[str, str], List[Dict[str, Any]]] = {}
    trainees_by_last_name: Dict[str, List[Dict[str, Any]]] = {}

    for sess in data.get("sessions", []):
        if bool(sess.get("archived")) or not _cnaps_pre_training_type_is_allowed(_session_get(sess, "training_type", "")):
            continue
        trainees = _session_trainees_list(sess)
        for trainee in trainees:
            key = (
                _normalize_person_name(trainee.get("last_name", "")),
                _normalize_person_name(trainee.get("first_name", "")),
            )
            if not key[0] or not key[1]:
                continue
            entry = {
                "session": sess,
                "trainee": trainee,
            }
            trainees_index.setdefault(key, []).append(entry)
            trainees_by_last_name.setdefault(key[0], []).append(entry)

    matches = []
    unmatched = []

    for file_index, file in enumerate(valid_files):
        name = (file.filename or "document.pdf").strip() or "document.pdf"
        file_bytes = file.read() or b""
        digest = hashlib.sha1(file_bytes).hexdigest() if file_bytes else ""
        already_saved = bool(digest and digest in pending_hashes)
        text = _extract_pdf_text(file_bytes)
        alnum_haystack, _ = _build_pdf_search_haystacks(file_bytes)
        combined_text = (text or "") + "\n" + (alnum_haystack or "")

        if not text and not alnum_haystack:
            unmatched.append({"file_name": name, "reason": "pdf_unreadable"})
            continue

        pre_number = _extract_pre_from_text(text)
        if not pre_number:
            pre_number = _extract_pre_from_compact_text(alnum_haystack)

        last_name, first_name = _extract_name_from_cnaps_text(text)
        if not (last_name and first_name):
            text_entry = _find_cnaps_trainee_match_in_text(trainees_by_last_name, combined_text, first_name)
            if text_entry:
                trainee_guess = text_entry.get("trainee") or {}
                if not last_name:
                    last_name = _normalize_person_name(trainee_guess.get("last_name", ""))
                if not first_name:
                    first_name = _normalize_person_name(trainee_guess.get("first_name", ""))

        if not pre_number:
            unmatched.append({
                "file_name": name,
                "reason": "missing_pre",
                "extracted": {
                    "last_name": last_name,
                    "first_name": first_name,
                    "pre_number": pre_number,
                },
            })
            continue

        entry = _find_cnaps_trainee_match(trainees_index, trainees_by_last_name, last_name, first_name)
        if not entry and not (last_name and first_name):
            entry = _find_cnaps_trainee_match_in_text(trainees_by_last_name, combined_text, first_name)
        if not entry:
            matches.append({
                "source_index": file_index,
                "file_name": name,
                "last_name": last_name,
                "first_name": first_name,
                "pre_number": pre_number,
                "formation": "",
                "training_dates": {
                    "start": "",
                    "end": "",
                },
                "session_id": "",
                "trainee_id": "",
                "match_found": False,
                "already_merged": False,
                "already_saved": already_saved,
            })
            continue

        session_obj = entry["session"]
        trainee = entry["trainee"]
        matches.append({
            "source_index": file_index,
            "file_name": name,
            "last_name": trainee.get("last_name", ""),
            "first_name": trainee.get("first_name", ""),
            "pre_number": pre_number,
            "formation": formation_label(_session_get(session_obj, "training_type", "")),
            "training_dates": {
                "start": fr_date(_session_get(session_obj, "date_start", "")),
                "end": fr_date(_session_get(session_obj, "date_end", "")),
            },
            "session_id": session_obj.get("id"),
            "trainee_id": trainee.get("id"),
            "match_found": True,
            "already_merged": bool(trainee.get("cnaps_import_merged_once")),
            "already_saved": already_saved,
        })

    return jsonify({
        "ok": True,
        "matches": matches,
        "unmatched": unmatched,
        "count": len(matches),
    })


@app.post("/api/cnaps/import-pre/merge")
@admin_login_required
@admin_write_required
def api_cnaps_import_pre_merge():
    session_id = (request.form.get("session_id") or "").strip()
    trainee_id = (request.form.get("trainee_id") or "").strip()
    pre_raw = (request.form.get("pre_number") or "").strip()
    nub = (request.form.get("nub") or "").strip()
    uploaded = request.files.get("file")

    if not session_id or not trainee_id:
        return jsonify({"ok": False, "error": "missing_target"}), 400
    if not uploaded or not uploaded.filename:
        return jsonify({"ok": False, "error": "missing_file"}), 400
    if not (uploaded.filename or "").lower().endswith(".pdf"):
        return jsonify({"ok": False, "error": "invalid_file"}), 400

    pre_number = _normalize_pre_car(pre_raw)
    if not _is_valid_pre_car(pre_number):
        return jsonify({"ok": False, "error": "invalid_pre"}), 400

    data = load_data()
    s = find_session(data, session_id)
    if not s:
        return jsonify({"ok": False, "error": "session_not_found"}), 404

    trainees = _session_trainees_list(s)
    t = next((x for x in trainees if x.get("id") == trainee_id), None)
    if not t:
        return jsonify({"ok": False, "error": "trainee_not_found"}), 404

    training_type = _session_get(s, "training_type", "")
    if not _cnaps_pre_training_type_is_allowed(training_type):
        return jsonify({"ok": False, "error": "training_not_eligible"}), 400

    stored = _store_file(session_id, trainee_id, "documents", uploaded)
    token = _tokenize_path(stored)

    _attach_cnaps_to_trainee(t, training_type, pre_number, token, "Import PRE CNAPS fusionné", _session_get(s, "date_start", ""))
    t["cnaps_import_merged_once"] = True
    t["cnaps_import_merged_at"] = _now_iso()
    _mark_cnaps_status_change_imported(data, last_name=t.get("last_name", ""), nub=nub)

    s["trainees"] = trainees
    s.pop("stagiaires", None)
    save_data(data)

    return jsonify({"ok": True, "pre_number": pre_number, "pending_status_changes_count": _cnaps_pending_status_change_count(data)})


@app.post("/api/cnaps/import-pre/save")
@admin_login_required
@admin_write_required
def api_cnaps_import_pre_save():
    pre_raw = (request.form.get("pre_number") or "").strip()
    nub = (request.form.get("nub") or "").strip()
    last_name = _normalize_person_name(request.form.get("last_name") or "")
    first_name = _normalize_person_name(request.form.get("first_name") or "")
    uploaded = request.files.get("file")

    if not uploaded or not uploaded.filename:
        return jsonify({"ok": False, "error": "missing_file"}), 400
    if not (uploaded.filename or "").lower().endswith(".pdf"):
        return jsonify({"ok": False, "error": "invalid_file"}), 400

    pre_number = _normalize_pre_car(pre_raw)
    if not _is_valid_pre_car(pre_number):
        return jsonify({"ok": False, "error": "invalid_pre"}), 400

    if not last_name or not first_name:
        return jsonify({"ok": False, "error": "missing_name"}), 400

    data = load_data()
    pending = _cnaps_pending_imports(data)

    file_bytes = uploaded.read() or b""
    if not file_bytes:
        return jsonify({"ok": False, "error": "empty_file"}), 400

    digest = hashlib.sha1(file_bytes).hexdigest()
    duplicate = next((x for x in pending if (x.get("sha1") or "") == digest), None)
    if duplicate:
        notification_reviewed = _mark_cnaps_status_change_imported(data, last_name=last_name, nub=nub)
        if notification_reviewed:
            save_data(data)
        return jsonify({
            "ok": True,
            "saved": True,
            "already_saved": True,
            "notification_reviewed": notification_reviewed,
            "pending_status_changes_count": _cnaps_pending_status_change_count(data),
        })

    token = _store_cnaps_pending_pdf(file_bytes, uploaded.filename or "document.pdf")
    identifiers = _find_cnapsv3_identifier_for_pending(data, last_name, first_name)
    request_id = identifiers.get("request_id") or ""
    dossier_id = identifiers.get("dossier_id") or ""

    pending_item = {
        "id": "CPN-" + uuid.uuid4().hex[:10].upper(),
        "last_name": last_name,
        "first_name": first_name,
        "pre_number": pre_number,
        "file_name": (uploaded.filename or "document.pdf").strip() or "document.pdf",
        "file_token": token,
        "sha1": digest,
        "created_at": _now_iso(),
        "cnapsv3_request_id": request_id,
        "cnapsv3_dossier_id": dossier_id,
        "email": "",
    }
    pending.append(pending_item)

    if not request_id and not dossier_id:
        email = _find_pending_trainee_email(data, last_name, first_name)
        lookup_identifiers = sync_cnapsv3_lookup_identifier(
            first_name=first_name,
            last_name=last_name,
            email=email or None,
        )
        if lookup_identifiers:
            request_id = str(lookup_identifiers.get("request_id") or "").strip()
            dossier_id = str(lookup_identifiers.get("dossier_id") or "").strip()
            cnapsv3_email = str(lookup_identifiers.get("email") or "").strip()
            pending_item["cnapsv3_request_id"] = request_id
            pending_item["cnapsv3_dossier_id"] = dossier_id
            if cnapsv3_email:
                pending_item["email"] = cnapsv3_email
        else:
            app.logger.info(
                "[CNAPSV3_SYNC] Accept ignoré: aucun identifiant trouvé après lookup first_name=%s last_name=%s",
                first_name,
                last_name,
            )

    if not pending_item.get("email"):
        pending_item["email"] = _find_pending_trainee_email(data, last_name, first_name)

    notification_reviewed = _mark_cnaps_status_change_imported(data, last_name=last_name, nub=nub)
    save_data(data)

    cnapsv3_match_found = bool(request_id or dossier_id)

    sync_ok = False
    if cnapsv3_match_found:
        sync_ok = sync_cnapsv3_accept_status(request_id=request_id, dossier_id=dossier_id)

    return jsonify({
        "ok": True,
        "saved": True,
        "already_saved": False,
        "cnapsv3_sync_ok": sync_ok,
        "cnapsv3_match_found": cnapsv3_match_found,
        "notification_reviewed": notification_reviewed,
        "pending_status_changes_count": _cnaps_pending_status_change_count(data),
    })


