import re
import unicodedata
import threading
from flask import request, jsonify

def _norm_name(s: str) -> str:
    s = (s or "").strip().lower()
    s = unicodedata.normalize("NFD", s)
    s = "".join(ch for ch in s if unicodedata.category(ch) != "Mn")  # enlève accents
    s = re.sub(r"[^a-z0-9]+", " ", s)
    s = re.sub(r"\s+", " ", s).strip()
    return s

def _match_trainee_from_filename(trainees: list, filename: str):
    """
    Match si NOM et PRÉNOM apparaissent dans le nom de fichier (normalisé).
    Renvoie (trainee, None) si OK, sinon (None, reason).
    """
    fn = _norm_name(filename)

    hits = []
    for t in trainees:
        ln = _norm_name(t.get("last_name", ""))
        fnm = _norm_name(t.get("first_name", ""))
        if not ln or not fnm:
            continue
        if ln in fn and fnm in fn:
            hits.append(t)

    if len(hits) == 1:
        return hits[0], None
    if len(hits) == 0:
        return None, "nom/prénom non trouvés dans le fichier"
    return None, "plusieurs stagiaires correspondent (homonyme)"

def _extract_pdf_text(pdf_bytes: bytes) -> str:
    if not pdf_bytes or not PYPDF_LIBRARY_AVAILABLE:
        return ""
    try:
        from pypdf import PdfReader
        reader = PdfReader(BytesIO(pdf_bytes))
    except Exception:
        return ""

    pages = []
    for page in reader.pages:
        try:
            pages.append(page.extract_text() or "")
        except Exception:
            continue
    return "\n".join(pages)


def _match_trainee_from_parchemin_pdf(trainees: list, file_bytes: bytes):
    text = _norm_name(_extract_pdf_text(file_bytes))
    if not text:
        return None, "texte PDF illisible"

    hits = []
    for t in trainees:
        ln = _norm_name(t.get("last_name", ""))
        fnm = _norm_name(t.get("first_name", ""))
        if not ln or not fnm:
            continue
        if ln in text and fnm in text:
            hits.append(t)

    if len(hits) == 1:
        return hits[0], None
    if len(hits) == 0:
        return None, "nom/prénom non trouvés dans le parchemin"
    return None, "plusieurs stagiaires correspondent (homonyme)"


def _build_vae_parchemin_pdf(base_pdf_bytes: bytes, photo_path: str) -> bytes:
    if not base_pdf_bytes:
        raise ValueError("parchemin_source_introuvable")
    if not (PYPDF_LIBRARY_AVAILABLE and REPORTLAB_LIBRARY_AVAILABLE):
        raise ValueError("libs_pdf_non_disponibles")

    from pypdf import PdfReader, PdfWriter
    from reportlab.lib.utils import ImageReader
    from reportlab.pdfgen import canvas

    reader = PdfReader(BytesIO(base_pdf_bytes))
    if not reader.pages:
        raise ValueError("parchemin_pdf_vide")

    first_page = reader.pages[0]
    width = float(first_page.mediabox.width)
    height = float(first_page.mediabox.height)

    # Zone photo du parchemin PDF.
    # On applique un "bleed" (débord) pour masquer totalement
    # le blanc + le cadre noir visibles sur le côté droit.
    box_w = width * 0.105
    box_h = height * 0.195
    box_x = width * 0.836
    box_y = height * 0.711
    # Ajustement fin demandé : décale légèrement la photo vers la droite
    # pour supprimer le filet blanc visible sur le bord droit du cadre.
    box_x += width * 0.008
    padding = 4
    clip_x = box_x - padding
    clip_y = box_y - padding
    clip_w = box_w + (padding * 2)
    clip_h = box_h + (padding * 2)

    packet = BytesIO()
    c = canvas.Canvas(packet, pagesize=(width, height))

    with Image.open(photo_path) as im:
        corrected = ImageOps.exif_transpose(im)
        rgb = corrected.convert("RGB")
        img_reader = ImageReader(rgb)
        iw, ih = rgb.size
        if iw > 0 and ih > 0:
            target_w = max(1, clip_w)
            target_h = max(1, clip_h)

            # Remplissage total (cover) de la zone clippée, sans déformation.
            scale = max(target_w / iw, target_h / ih)
            draw_w = max(1, iw * scale)
            draw_h = max(1, ih * scale)
            draw_x = clip_x + (target_w - draw_w) / 2
            draw_y = clip_y + (target_h - draw_h) / 2

            c.saveState()
            clip_path = c.beginPath()
            clip_path.rect(clip_x, clip_y, target_w, target_h)
            c.clipPath(clip_path, stroke=0, fill=0)
            c.drawImage(img_reader, draw_x, draw_y, draw_w, draw_h, preserveAspectRatio=True, mask='auto')
            c.restoreState()

    c.save()
    packet.seek(0)

    overlay_reader = PdfReader(packet)
    overlay_page = overlay_reader.pages[0]
    first_page.merge_page(overlay_page)

    out = BytesIO()
    writer = PdfWriter()
    for page in reader.pages:
        writer.add_page(page)
    writer.write(out)
    return out.getvalue()


def _is_desp_diploma_session(session_obj: Dict[str, Any]) -> bool:
    """Return whether bulk diploma imports must receive the trainee photo."""
    descriptor = " ".join((
        str(_session_get(session_obj, "training_type", "") or ""),
        str(_session_get(session_obj, "name", "") or ""),
    )).upper()
    return "DIRIGEANT" in descriptor or "DESP" in descriptor


def _store_parchemin_generated_pdf(session_id: str, trainee_id: str, pdf_bytes: bytes) -> str:
    base = trainee_upload_dir(session_id, trainee_id)
    target_dir = os.path.join(base, "deliverables")
    os.makedirs(target_dir, exist_ok=True)
    name = uuid.uuid4().hex[:10] + ".pdf"
    path = os.path.join(target_dir, name)
    with open(path, "wb") as f:
        f.write(pdf_bytes)
    return path


def _persist_bulk_deliverable_token(
    session_id: str,
    trainee_id: str,
    kind: str,
    token: str,
) -> Dict[str, Any]:
    """Attach a bulk-uploaded deliverable using the latest persisted payload.

    Bulk imports can spend several seconds generating PDFs and sending Brevo
    notifications. Persisting from the payload loaded at the start of that
    work can overwrite newer trainee changes. This small atomic mutation also
    makes the document visible on the admin trainee sheet before notifications
    are attempted.
    """

    def mutate(canonical: Dict[str, Any]) -> Dict[str, Any]:
        session_obj = find_session(canonical, session_id)
        if not session_obj:
            return {"ok": False, "reason": "session introuvable pendant l'enregistrement"}

        current_trainees = _session_trainees_list(session_obj)
        current_trainee = next(
            (item for item in current_trainees if str(item.get("id") or "") == str(trainee_id)),
            None,
        )
        if not current_trainee:
            return {"ok": False, "reason": "stagiaire introuvable pendant l'enregistrement"}

        deliverables = current_trainee.setdefault("deliverables", {})
        existing = str(deliverables.get(kind) or "").strip()
        if existing and existing != token:
            label = DELIVERABLE_LABELS.get(kind, "document").lower()
            return {"ok": False, "reason": f"{label} déjà existant (non remplacé)"}

        deliverables[kind] = token
        current_trainee["updated_at"] = _now_iso()
        session_obj["trainees"] = current_trainees
        session_obj.pop("stagiaires", None)
        return {"ok": True}

    return _atomic_update_data(mutate)


def _persist_bulk_email_history_entry(
    session_id: str,
    trainee_id: str,
    entry: Optional[Dict[str, Any]],
) -> None:
    """Merge one Brevo history entry without rewriting a stale data payload."""
    if not isinstance(entry, dict):
        return

    def mutate(canonical: Dict[str, Any]) -> Dict[str, Any]:
        session_obj = find_session(canonical, session_id)
        if not session_obj:
            return {"ok": False}
        current_trainees = _session_trainees_list(session_obj)
        current_trainee = next(
            (item for item in current_trainees if str(item.get("id") or "") == str(trainee_id)),
            None,
        )
        if not current_trainee:
            return {"ok": False}

        history = current_trainee.get("sent_email_history")
        if not isinstance(history, list):
            history = []
        signature = (
            str(entry.get("to_email") or ""),
            str(entry.get("subject") or ""),
            str(entry.get("sent_at") or ""),
        )
        if not any((
            str(item.get("to_email") or ""),
            str(item.get("subject") or ""),
            str(item.get("sent_at") or ""),
        ) == signature for item in history if isinstance(item, dict)):
            history.insert(0, dict(entry))
        current_trainee["sent_email_history"] = history[:200]
        session_obj["trainees"] = current_trainees
        session_obj.pop("stagiaires", None)
        return {"ok": True}

    try:
        _atomic_update_data(mutate)
    except Exception:
        app.logger.exception(
            "Unable to persist bulk email history for session=%s trainee=%s",
            session_id,
            trainee_id,
        )


@app.post("/api/sessions/<session_id>/parchemin/bulk_upload")
@admin_login_required
@admin_write_required
def api_parchemin_bulk_upload(session_id: str):
    data = load_data()
    s = find_session(data, session_id)
    if not s:
        return jsonify({"ok": False, "error": "session_not_found"}), 404

    training_type = (_session_get(s, "training_type", "") or "").strip().upper()
    if training_type != "DIRIGEANT VAE":
        return jsonify({"ok": False, "error": "parchemin_reserved_for_vae"}), 400

    if not (PYPDF_LIBRARY_AVAILABLE and REPORTLAB_LIBRARY_AVAILABLE):
        return jsonify({"ok": False, "error": "missing_pdf_dependencies"}), 503

    files = request.files.getlist("files")
    if not files:
        return jsonify({"ok": False, "error": "no_files"}), 400

    send_notifications = (request.form.get("send_notifications", "1") or "1").strip().lower() not in {"0", "false", "no", "non", "off"}

    trainees = _session_trainees_list(s)
    received = 0
    added = []
    failed = []

    for f in files:
        if not f or not f.filename:
            continue

        received += 1
        original_name = f.filename
        ext = _safe_ext(original_name)
        if ext != ".pdf":
            failed.append({"filename": original_name, "reason": "format invalide (PDF uniquement)"})
            continue

        try:
            try:
                f.stream.seek(0)
            except Exception:
                pass
            pdf_bytes = f.read() or b""
        except Exception:
            failed.append({"filename": original_name, "reason": "lecture impossible"})
            continue

        trainee, reason = _match_trainee_from_parchemin_pdf(trainees, pdf_bytes)
        if not trainee:
            failed.append({"filename": original_name, "reason": reason or "non rattaché"})
            continue

        trainee_id = trainee.get("id") or trainee.get("trainee_id") or trainee.get("personal_id")
        if not trainee_id:
            failed.append({"filename": original_name, "reason": "trainee_id introuvable"})
            continue

        existing = ((trainee.get("deliverables") or {}).get("parchemin") or "").strip()
        if existing:
            failed.append({"filename": original_name, "reason": "parchemin déjà existant (non remplacé)"})
            continue

        photo_token = (trainee.get("identity_photo") or "").strip()
        if not photo_token:
            failed.append({"filename": original_name, "reason": "photo d'identité absente sur la fiche stagiaire"})
            continue

        photo_path = _detokenize_path(photo_token)
        if not os.path.exists(photo_path):
            failed.append({"filename": original_name, "reason": "photo d'identité introuvable"})
            continue

        try:
            final_pdf = _build_vae_parchemin_pdf(pdf_bytes, photo_path)
            final_path = _store_parchemin_generated_pdf(session_id, trainee_id, final_pdf)
            token = _tokenize_path(final_path)
        except Exception as e:
            failed.append({"filename": original_name, "reason": f"génération parchemin impossible: {str(e)}"})
            continue

        persist_result = _persist_bulk_deliverable_token(session_id, trainee_id, "parchemin", token)
        if not persist_result.get("ok"):
            _safe_remove_file(final_path)
            failed.append({
                "filename": original_name,
                "reason": persist_result.get("reason") or "enregistrement du parchemin impossible",
            })
            continue

        trainee.setdefault("deliverables", {})
        trainee["deliverables"]["parchemin"] = token
        trainee["updated_at"] = _now_iso()

        if send_notifications:
            try:
                link = f"{PUBLIC_STUDENT_PORTAL_BASE.rstrip('/')}/espace/{trainee.get('public_token','')}"
                label = DELIVERABLE_LABELS["parchemin"]
                first_name = (trainee.get("first_name") or "").strip() or "Madame, Monsieur"
                formation_type = formation_label(_session_get(s, "training_type", ""))
                dstart = fr_date(_session_get(s, "date_start", ""))
                dend = fr_date(_session_get(s, "date_end", ""))

                subject = f"{label} disponible – Intégrale Academy"
                html = mail_layout(f"""
                  <h2 style=\"text-align:center\">✅ {label} disponible</h2>

                  <p>Bonjour <strong>{first_name}</strong>,</p>

                  <p>
                    Nous avons le plaisir de vous informer que votre <strong>{label}</strong>
                    est désormais disponible dans votre espace stagiaire.
                  </p>

                  <div style=\"background:#f3f4f6;border:1px solid #e5e7eb;border-radius:12px;padding:14px;margin:16px 0\">
                    <p style=\"margin:0 0 10px 0\">
                      <strong>📌 Formation :</strong> {formation_type}
                      {" — <strong>Dates :</strong> " + dstart + " au " + dend if (dstart or dend) else ""}
                    </p>

                    <p style=\"margin:0\">
                      <strong>📍 Accéder à votre espace stagiaire :</strong><br>
                      <a href=\"{link}\" style=\"color:#1f8f4a;text-decoration:none;font-weight:bold\">{link}</a>
                    </p>
                  </div>

                  <p style=\"text-align:center;margin-top:18px\">
                    <a href=\"{link}\"
                       style=\"display:inline-block;background:#1f8f4a;color:white;padding:12px 18px;border-radius:10px;
                              text-decoration:none;font-weight:bold\">
                      👉 Accéder à mon espace stagiaire
                    </a>
                  </p>
                """)

                sms_name = (trainee.get("first_name") or "").strip()
                sms = (
                    f"Intégrale Academy ✅ {sms_name + ', ' if sms_name else ''}\n"
                    f"Votre {label} est disponible sur votre espace :\n"
                    f"{link}\n"
                    f"A bientôt, la Team Intégrale Academy"
                )

                email_sent = brevo_send_email(trainee.get("email", ""), subject, html, trainee=trainee)
                if email_sent:
                    history = trainee.get("sent_email_history") or []
                    _persist_bulk_email_history_entry(
                        session_id,
                        trainee_id,
                        history[0] if history else None,
                    )
                brevo_send_sms(trainee.get("phone", ""), sms)
            except Exception:
                pass

        added.append({
            "filename": original_name,
            "trainee_id": trainee_id,
            "trainee_name": f"{trainee.get('first_name','')} {trainee.get('last_name','')}".strip()
        })

    return jsonify({
        "ok": True,
        "received": received,
        "added_count": len(added),
        "added": added,
        "failed": failed,
        "send_notifications": send_notifications,
    })


