@app.post("/api/sessions/<session_id>/diplome/bulk_upload")
@admin_login_required
@admin_write_required
def api_diplome_bulk_upload(session_id: str):
    import traceback

    data = load_data()
    s = find_session(data, session_id)
    if not s:
        return jsonify({"ok": False, "error": "session_not_found"}), 404

    is_desp_diploma = _is_desp_diploma_session(s)
    if is_desp_diploma and not (PYPDF_LIBRARY_AVAILABLE and REPORTLAB_LIBRARY_AVAILABLE):
        return jsonify({"ok": False, "error": "missing_pdf_dependencies"}), 503

    files = request.files.getlist("files")
    if not files:
        return jsonify({"ok": False, "error": "no_files"}), 400

    send_notifications = (request.form.get("send_notifications", "1") or "1").strip().lower() not in {"0", "false", "no", "non", "off"}

    trainees = _session_trainees_list(s)

    received = 0
    added = []
    failed = []

    for f in files:
        if not f or not f.filename:
            continue

        received += 1
        original_name = f.filename
        ext = _safe_ext(original_name)

        if is_desp_diploma and ext != ".pdf":
            failed.append({"filename": original_name, "reason": "format invalide (PDF uniquement pour un diplôme DESP)"})
            continue

        if ext not in (".pdf", ".jpg", ".jpeg", ".png"):
            failed.append({"filename": original_name, "reason": "extension non autorisée"})
            continue

        pdf_bytes = None
        trainee, reason = _match_trainee_from_filename(trainees, original_name)
        if not trainee and ext == ".pdf":
            try:
                f.stream.seek(0)
                pdf_bytes = f.read() or b""
                f.stream.seek(0)
                trainee, pdf_reason = _match_trainee_from_parchemin_pdf(trainees, pdf_bytes)
                if not trainee:
                    if reason == "nom/prénom non trouvés dans le fichier" and pdf_reason == "nom/prénom non trouvés dans le parchemin":
                        reason = "nom/prénom non trouvés dans le nom du fichier ni dans le PDF"
                    else:
                        reason = f"{reason}; PDF: {pdf_reason}"
            except Exception:
                reason = f"{reason}; lecture du PDF impossible"
        if not trainee:
            failed.append({"filename": original_name, "reason": reason or "non rattaché"})
            continue

        trainee_id = trainee.get("id") or trainee.get("trainee_id") or trainee.get("personal_id")
        if not trainee_id:
            failed.append({"filename": original_name, "reason": "trainee_id introuvable"})
            continue

        # ✅ si déjà un diplôme, on n'écrase pas + on n'envoie pas
        existing = ((trainee.get("deliverables") or {}).get("diplome") or "").strip()
        if existing:
            failed.append({"filename": original_name, "reason": "déjà un diplôme existant (non remplacé)"})
            continue

        photo_path = ""
        if is_desp_diploma:
            photo_token = str(trainee.get("identity_photo") or "").strip()
            if not photo_token:
                failed.append({"filename": original_name, "reason": "photo d'identité absente sur la fiche stagiaire"})
                continue
            photo_path = _detokenize_path(photo_token)
            if not os.path.exists(photo_path):
                failed.append({"filename": original_name, "reason": "photo d'identité introuvable"})
                continue

        try:
            try:
                f.stream.seek(0)
            except Exception:
                pass

            if is_desp_diploma:
                if pdf_bytes is None:
                    pdf_bytes = f.read() or b""
                final_pdf = _build_vae_parchemin_pdf(pdf_bytes, photo_path)
                stored = _store_parchemin_generated_pdf(session_id, trainee_id, final_pdf)
            else:
                stored = _store_file(session_id, trainee_id, "deliverables", f)
            token = _tokenize_path(stored)
        except Exception as e:
            print("=== BULK DIPLOME: erreur stockage ===")
            traceback.print_exc()
            reason = "génération du diplôme avec photo impossible" if is_desp_diploma else "erreur stockage"
            failed.append({"filename": original_name, "reason": f"{reason}: {str(e)}"})
            continue

        persist_result = _persist_bulk_deliverable_token(session_id, trainee_id, "diplome", token)
        if not persist_result.get("ok"):
            _safe_remove_file(stored)
            failed.append({
                "filename": original_name,
                "reason": persist_result.get("reason") or "enregistrement du diplôme impossible",
            })
            continue

        trainee.setdefault("deliverables", {})
        trainee["deliverables"]["diplome"] = token
        trainee["updated_at"] = _now_iso()

        # ✅ Envoi mail + SMS (mail enrichi + CNAPS + avis Google)
